const QUESTIONS = [{"chapter": 1, "number": 1, "id": "415505723", "question": "Thời gian và địa điểm thực dân Pháp nổ súng mở đầu cho cuộc chiến tranh xâm lược Việt Nam lần thứ nhất?", "options": ["1858 - tại Lăng Cô, Huế", "1883 - tại Thanh Trì, Hà Nội", "1858 - tại Sơn Trà, Đà Nẵng", "1858 - tại chợ Bến Thành, Sài Gòn"], "answer": "C", "key": "1.1", "explanation": "1858 → Sơn Trà, Đà Nẵng: mốc mở đầu xâm lược của Pháp.", "topic": "Trước 1911 · Xã hội & phong trào yêu nước", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Nhớ nơi quân Pháp đánh vào đầu tiên ở miền Trung, giữa thế kỷ XIX."}, {"chapter": 1, "number": 2, "id": "415505724", "question": "Trong xã hội phong kiến, mâu thuẫn nào là lớn nhất ở Việt Nam?", "options": ["Mâu thuẫn dân tộc", "Mâu thuẫn dân tộc và giai cấp", "Mâu thuẫn giai cấp", "Không có mâu thuẫn nào"], "answer": "C", "key": "1.2", "explanation": "Phong kiến → địa chủ và nông dân: mâu thuẫn giai cấp nổi bật.", "topic": "Trước 1911 · Xã hội & phong trào yêu nước", "extra": false, "review": false, "tier": 7, "sources": [], "hint": "Đề chỉ nói xã hội phong kiến: xét quan hệ giữa người có ruộng và người cày."}, {"chapter": 1, "number": 3, "id": "415505725", "question": "Mâu thuẫn cơ bản và chủ yếu ở Việt Nam cuối thế kỷ XIX, đầu thế kỷ XX là?", "options": ["Mâu thuẫn giữa giai cấp nông dân với giai cấp địa chủ phong kiến", "Mâu thuẫn giữa giai cấp công nhân với giai cấp tư sản", "Mâu thuẫn giữa giai cấp công nhân và nông dân với thực dân và phong kiến", "Mâu thuẫn giữa dân tộc Việt Nam với thực dân Pháp và tay sai"], "answer": "D", "key": "1.3", "explanation": "Thuộc địa → dân tộc Việt Nam đối lập thực dân Pháp và tay sai.", "topic": "Trước 1911 · Xã hội & phong trào yêu nước", "extra": false, "review": false, "tier": 7, "sources": [], "hint": "Phân biệt mâu thuẫn dân tộc với mâu thuẫn giai cấp; chú ý hoàn cảnh mất nước."}, {"chapter": 1, "number": 4, "id": "415505726", "question": "Sau khi thực dân Pháp tiến hành cai trị nước ta, tính chất xã hội Việt Nam đã thay đổi như thế nào?", "options": ["Từ xã hội nửa phong kiến sang xã hội thuộc địa nửa phong kiến", "Từ xã hội nửa phong kiến sang xã hội thuộc địa", "Từ xã hội phong kiến sang xã hội thuộc địa", "Từ xã hội phong kiến sang xã hội thuộc địa nửa phong kiến"], "answer": "D", "key": "1.4", "explanation": "Pháp thống trị nhưng vẫn duy trì quan hệ phong kiến → thuộc địa nửa phong kiến.", "topic": "Trước 1911 · Xã hội & phong trào yêu nước", "extra": false, "review": false, "tier": 7, "sources": [], "hint": "Chế độ cũ chưa mất hẳn, trong khi quyền thống trị thuộc về ngoại bang."}, {"chapter": 1, "number": 5, "id": "415505727", "question": "Giai cấp công nhân Việt Nam ra đời trong khoảng thời gian nào?", "options": ["Trước khi thực dân Pháp xâm lược Việt Nam", "Ngay sau khi thực dân Pháp chiếm đóng Việt Nam", "Trong đợt khai thác thuộc địa lần thứ nhất của Pháp tại Việt Nam", "Sau Chiến tranh thế giới lần thứ nhất 1914 – 1918"], "answer": "C", "key": "1.5", "explanation": "Khai thác lần thứ nhất → hình thành công nhân trong hầm mỏ, đồn điền, nhà máy.", "topic": "Trước 1911 · Xã hội & phong trào yêu nước", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Gắn sự hình thành nhà máy, hầm mỏ với đợt khai thác thuộc địa sớm nhất."}, {"chapter": 1, "number": 6, "id": "415505728", "question": "Nội dung nào sau đây không đúng về giai cấp công nhân Việt Nam?", "options": ["Ra đời trong cuộc khai thác thuộc địa lần thứ nhất của Pháp", "Phần lớn xuất thân từ nông dân", "Chịu sự áp bức, bóc lột của đế quốc, phong kiến và tư sản", "Ra đời sau giai cấp tư sản Việt Nam"], "answer": "D", "key": "1.6", "explanation": "Câu phủ định: công nhân ra đời TRƯỚC tư sản Việt Nam.", "topic": "Trước 1911 · Xã hội & phong trào yêu nước", "extra": false, "review": false, "tier": 8, "sources": [], "hint": "Tìm phát biểu sai về thứ tự xuất hiện của công nhân và tư sản."}, {"chapter": 1, "number": 7, "id": "415505729", "question": "Trong xã hội phong kiến, yêu cầu bức thiết nhất của giai cấp nông dân Việt Nam là:", "options": ["Sở hữu ruộng đất", "Giải phóng dân tộc", "Bỏ các thứ thuế vô lý", "Tự do đi lại"], "answer": "A", "key": "1.7", "explanation": "Nông dân gắn với ruộng đất → yêu cầu có ruộng để canh tác.", "topic": "Trước 1911 · Xã hội & phong trào yêu nước", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Hãy nghĩ đến tư liệu sản xuất thiết thân nhất của người làm nông."}, {"chapter": 1, "number": 8, "id": "415505730", "question": "Có tinh thần dân tộc, yêu nước, rất nhạy cảm về chính trị và thời cuộc nhưng hay dao động, thiếu kiên định là đặc điểm của giai cấp, tầng lớp nào?", "options": ["Công nhân", "Nông dân", "Tư sản", "Tiểu tư sản"], "answer": "D", "key": "1.8", "explanation": "Tiểu tư sản → nhạy thời cuộc nhưng dễ dao động về lập trường.", "topic": "Trước 1911 · Xã hội & phong trào yêu nước", "extra": false, "review": false, "tier": 7, "sources": [], "hint": "Xét tầng lớp có trí thức, học sinh, người làm nghề nhỏ và tâm lý thiếu ổn định."}, {"chapter": 1, "number": 9, "id": "415505731", "question": "Trước Chiến tranh thế giới thứ nhất, ở Việt Nam có những giai cấp nào?", "options": ["Địa chủ phong kiến và nông dân", "Địa chủ phong kiến, nông dân, tư sản, tiểu tư sản và công nhân", "Địa chủ phong kiến, nông dân và công nhân", "Địa chủ phong kiến, nông dân và tiểu tư sản"], "answer": "C", "key": "1.9", "explanation": "Trước 1914 → địa chủ, nông dân, công nhân; tư sản chưa thành giai cấp rõ nét.", "topic": "Trước 1911 · Xã hội & phong trào yêu nước", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Đừng đưa các giai cấp chỉ hình thành rõ sau cuộc khai thác thuộc địa thứ hai vào đây."}, {"chapter": 1, "number": 10, "id": "415505732", "question": "Cuộc khởi nghĩa tiêu biểu nhất trong phong trào Cần Vương là?", "options": ["Khởi nghĩa Ba Đình", "Khởi nghĩa Bãi Sậy", "Khởi nghĩa Hương Khê", "Khởi nghĩa Hùng Lĩnh"], "answer": "C", "key": "1.10", "explanation": "Cần Vương → Hương Khê là cuộc khởi nghĩa tiêu biểu nhất.", "topic": "Trước 1911 · Xã hội & phong trào yêu nước", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Tìm cuộc khởi nghĩa gắn với Phan Đình Phùng và Cao Thắng."}, {"chapter": 1, "number": 11, "id": "415505733", "question": "“Còn mang nặng cốt cách phong kiến” là nhận xét của lãnh tụ Hồ Chí Minh về phong trào đấu tranh yêu nước nào?", "options": ["Phong trào Cần Vương", "Phong trào nông dân Yên Thế", "Phong trào dân chủ tư sản", "Phong trào tiểu tư sản trí thức"], "answer": "B", "key": "1.11", "explanation": "Yên Thế → phong trào nông dân, còn cốt cách phong kiến.", "topic": "Trước 1911 · Xã hội & phong trào yêu nước", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Phân biệt phong trào phò vua với phong trào nông dân do Hoàng Hoa Thám lãnh đạo."}, {"chapter": 1, "number": 12, "id": "415505734", "question": "Phong trào nào không thuộc khuynh hướng đấu tranh dân chủ tư sản?", "options": ["Phong trào Đông Du", "Phong trào Duy Tân", "Phong trào Đông Kinh Nghĩa Thục", "Phong trào đấu tranh đòi tự do, dân chủ, cơm áo, hòa bình (1936 - 1939)"], "answer": "D", "key": "1.12", "explanation": "1936–1939 do Đảng Cộng sản lãnh đạo → khác khuynh hướng dân chủ tư sản.", "topic": "Trước 1911 · Xã hội & phong trào yêu nước", "extra": false, "review": false, "tier": 8, "sources": [], "hint": "Xem phong trào nào do Đảng Cộng sản lãnh đạo, thay vì các nhà yêu nước tư sản."}, {"chapter": 1, "number": 13, "id": "415505735", "question": "“Không thành công cũng thành nhân” là khẩu hiệu của cuộc khởi nghĩa nào?", "options": ["Khởi nghĩa Yên Bái", "Khởi nghĩa Ba Đình", "Khởi nghĩa Hương Khê", "Khởi nghĩa Bãi Sậy"], "answer": "A", "key": "1.13", "explanation": "Yên Bái → Nguyễn Thái Học → không thành công cũng thành nhân.", "topic": "Trước 1911 · Xã hội & phong trào yêu nước", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Khẩu hiệu gắn với Nguyễn Thái Học và Việt Nam Quốc dân Đảng."}, {"chapter": 1, "number": 14, "id": "415505736", "question": "Các phong trào yêu nước theo khuynh hướng phong kiến và dân chủ tư sản tuy thất bại nhưng để lại nhiều ý nghĩa, ý nghĩa lớn nhất là?", "options": ["Để lại nhiều bài học kinh nghiệm quý báu", "Chứng tỏ tư tưởng phong kiến và dân chủ tư sản đã lỗi thời không còn phù hợp để lãnh đạo phong trào đấu tranh", "Tạo ra môi trường xã hội thuận lợi cho phong trào yêu nước về sau phát triển", "Cho thấy tinh thần yêu nước, chống giặc ngoại xâm kiên cường của dân tộc Việt Nam"], "answer": "C", "key": "1.14", "explanation": "Theo tài liệu: phong trào cũ tạo môi trường xã hội cho phong trào sau.", "topic": "Trước 1911 · Xã hội & phong trào yêu nước", "extra": false, "review": true, "tier": 8, "sources": [], "hint": "Đề hỏi đóng góp dù thất bại: nghĩ đến điều kiện xã hội cho phong trào tiếp nối."}, {"chapter": 1, "number": 15, "id": "415505737", "question": "Sự thất bại của các phong trào yêu nước Việt Nam cuối thế kỷ XIX, đầu thế kỷ XX đặt ra yêu cầu cấp thiết gì?", "options": ["Đoàn kết toàn dân đấu tranh chống giặc ngoại xâm", "Thành lập một chính đảng của giai cấp tiên tiến", "Tìm ra con đường cứu nước mới cho dân tộc", "Đánh đổ chế độ phong kiến, xây dựng chế độ mới"], "answer": "C", "key": "1.15", "explanation": "Đường lối cũ thất bại → cần tìm con đường cứu nước mới.", "topic": "Trước 1911 · Xã hội & phong trào yêu nước", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Các con đường cũ bế tắc; cần đổi hướng ở cấp độ đường lối cứu nước."}, {"chapter": 1, "number": 16, "id": "415505738", "question": "Khi ra đi tìm đường cứu nước ngày 5/6/1911 Bác đã lấy tên gọi là gì?", "options": ["Nguyễn Ái Quốc", "Lý Thuỵ", "Văn Ba", "Thầu Chín"], "answer": "C", "key": "1.16", "explanation": "5/6/1911 → Văn Ba → ra đi tìm đường cứu nước.", "topic": "1911–1929 · Nguyễn Ái Quốc & tổ chức tiền thân", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Phân biệt tên dùng khi làm phụ bếp năm 1911 với tên hoạt động ở Pháp sau đó."}, {"chapter": 1, "number": 17, "id": "415505739", "question": "Cuộc cách mạng nào đã làm biến đổi sâu sắc tình hình thế giới cuối thế kỉ XIX, đầu thế kỉ XX?", "options": ["Cách mạng tư sản Pháp", "Cách mạng tư sản Anh", "Cách mạng Tân Hợi – Trung Quốc", "Cách mạng Tháng Mười Nga"], "answer": "D", "key": "1.17", "explanation": "Tháng Mười Nga 1917 → mở thời đại cách mạng vô sản.", "topic": "1911–1929 · Nguyễn Ái Quốc & tổ chức tiền thân", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Tìm cuộc cách mạng mở ra thời đại cách mạng vô sản, diễn ra năm 1917."}, {"chapter": 1, "number": 18, "id": "415505740", "question": "“Cách mạng tới nơi” là nhận xét của lãnh tụ Hồ Chí Minh về cuộc cách mạng nào?", "options": ["Cách mạng Tư sản Pháp", "Cách mạng Tân Hợi", "Cách mạng Tư sản Anh", "Cách mạng Tháng Mười Nga"], "answer": "D", "key": "1.18", "explanation": "Cách mạng tới nơi → Tháng Mười Nga, giải phóng người lao động.", "topic": "1911–1929 · Nguyễn Ái Quốc & tổ chức tiền thân", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Nhận xét nhấn mạnh giải phóng người lao động, vượt giới hạn của cách mạng tư sản."}, {"chapter": 1, "number": 19, "id": "415505741", "question": "Thay mặt Hội những người An Nam yêu nước ở Pháp, Nguyễn Ái Quốc gửi bản Yêu sách của nhân dân An Nam tới hội nghị nào?", "options": ["Hội nghị Vécxây", "Hội nghị Tehran", "Hội nghị Ianta", "Hội nghị Potsdam"], "answer": "A", "key": "1.19", "explanation": "1919 → Yêu sách nhân dân An Nam → Hội nghị Vécxây.", "topic": "1911–1929 · Nguyễn Ái Quốc & tổ chức tiền thân", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Nhớ hội nghị hòa bình sau Chiến tranh thế giới thứ nhất, tổ chức tại Pháp."}, {"chapter": 1, "number": 20, "id": "415505742", "question": "Lãnh tụ Hồ Chí Minh đã thốt lên “Hỡi đồng bào bị đọa đày đau khổ! Đây là cái cần thiết cho chúng ta, đây là con đường giải phóng chúng ta” khi đọc và nghiên cứu văn bản nào dưới đây?", "options": ["Tuyên ngôn của Đảng cộng sản", "Tuyên ngôn nhân quyền và dân quyền của cách mạng Pháp", "Tuyên ngôn độc lập của Hoa Kỳ", "Sơ thảo lần thứ nhất những luận cương về vấn đề dân tộc và vấn đề thuộc địa của V.I. Lênin"], "answer": "D", "key": "1.20", "explanation": "Luận cương Lênin về dân tộc và thuộc địa → nhận ra con đường giải phóng.", "topic": "1911–1929 · Nguyễn Ái Quốc & tổ chức tiền thân", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Đây là văn bản lý luận giải quyết trực tiếp vấn đề giải phóng các dân tộc thuộc địa."}, {"chapter": 1, "number": 21, "id": "415505743", "question": "Sau khi tìm thấy con đường cứu nước, Nguyễn Ái Quốc - Hồ Chí Minh đã rời pháp sang Liên Xô với mục đích gì?", "options": ["Truyền bá chủ nghĩa Mác - Lênin về Việt Nam", "Tiếp tục khảo sát, tìm hiểu để hoàn thiện nhận thức về đường lối cách mạng vô sản", "Tham gia thành lập Hội liên hiệp thuộc địa", "Xây dựng mối quan hệ gắn bó giữa những người cộng sản và nhân dân lao động Pháp với các nước thuộc địa và phụ thuộc"], "answer": "B", "key": "1.21", "explanation": "Sang Liên Xô → tiếp tục nghiên cứu, hoàn thiện nhận thức cách mạng vô sản.", "topic": "1911–1929 · Nguyễn Ái Quốc & tổ chức tiền thân", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Chú ý mục đích đi nghiên cứu ở Liên Xô, không nhầm với hoạt động tuyên truyền về nước."}, {"chapter": 1, "number": 22, "id": "415505744", "question": "Vai trò to lớn nhất của Nguyễn Ái Quốc đối với CMVN giai đoạn 1919 - 1925 là:", "options": ["Tìm thấy con đường cứu nước đúng đắn - con đường cách mạng vô sản", "Truyền bá chủ nghĩa Mác - Lênin về Việt Nam", "Sáng lập Hội Việt Nam cách mạng thanh niên", "Hợp nhất ba tổ chức cộng sản thành một đảng duy nhất - Đảng Cộng sản Việt Nam"], "answer": "A", "key": "1.22", "explanation": "1919–1925 → công lao lớn nhất là tìm ra con đường cứu nước đúng.", "topic": "1911–1929 · Nguyễn Ái Quốc & tổ chức tiền thân", "extra": false, "review": false, "tier": 7, "sources": [], "hint": "Khoanh đúng giai đoạn 1919–1925; sự kiện thành lập Đảng nằm ngoài khoảng này."}, {"chapter": 1, "number": 23, "id": "415505745", "question": "Hoạt động chủ yếu của lãnh tụ Nguyễn Ái Quốc sau khi thành lập Hội Việt Nam Cách mạng Thanh niên tại Quảng Châu (Trung Quốc) là:", "options": ["Thực hiện phong trào vô sản hóa", "Mở lớp huấn luyện chính trị, đào tạo cán bộ cách mạng", "Tổ chức các cuộc bãi công của giai cấp công nhân ở các nhà máy xí nghiệp", "Bí mật chuyển các tài liệu tuyên truyền cách mạng về nước"], "answer": "B", "key": "1.23", "explanation": "Quảng Châu → mở lớp chính trị, đào tạo cán bộ làm nòng cốt.", "topic": "1911–1929 · Nguyễn Ái Quốc & tổ chức tiền thân", "extra": false, "review": false, "tier": 7, "sources": [], "hint": "Hãy tìm hoạt động tạo đội ngũ cán bộ cho tổ chức mới thành lập."}, {"chapter": 1, "number": 24, "id": "415505746", "question": "Luận điểm nào sau đây không đúng về Hội Việt Nam Cách mạng Thanh niên?", "options": ["Là tổ chức trực tiếp truyền bá chủ nghĩa Mác - Lênin vào Việt Nam", "Là tổ chức thúc đẩy việc truyền bá chữ quốc ngữ tới nhân dân", "Là tổ chức tiền thân của Đảng Cộng sản Việt Nam", "Là tổ chức có ảnh hưởng và thúc đẩy mạnh mẽ sự chuyển biến của phong trào công nhân Việt Nam"], "answer": "B", "key": "1.24", "explanation": "Câu phủ định: truyền bá chữ quốc ngữ không phải chức năng đặc trưng của Hội Thanh niên.", "topic": "1911–1929 · Nguyễn Ái Quốc & tổ chức tiền thân", "extra": false, "review": false, "tier": 8, "sources": [], "hint": "Câu phủ định: phân biệt đào tạo cách mạng với hoạt động phổ cập chữ viết."}, {"chapter": 1, "number": 25, "id": "415505747", "question": "Tổ chức nào là nòng cốt để lãnh tụ Nguyễn Ái Quốc thành lập Hội Việt Nam Cách mạng Thanh niên năm 1925?", "options": ["Thanh niên Tân Việt", "Cộng sản Đoàn", "Hội Liên hiệp thuộc địa", "Tổ chức Việt Nam Quốc dân Đảng"], "answer": "B", "key": "1.25", "explanation": "Cộng sản Đoàn → hạt nhân tổ chức Hội Thanh niên năm 1925.", "topic": "1911–1929 · Nguyễn Ái Quốc & tổ chức tiền thân", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Tìm nhóm cộng sản làm hạt nhân bên trong tổ chức thanh niên rộng hơn."}, {"chapter": 1, "number": 26, "id": "415505748", "question": "Năm 1927, các bài giảng của lãnh tụ Nguyễn Ái Quốc trong các lớp đào tạo, bồi dưỡng cán bộ cách mạng tại Quảng Châu (Trung Quốc) được xuất bản thành tác phẩm nào?", "options": ["Tác phẩm Kháng chiến nhất định thắng lợi", "Tác phẩm Tự chỉ trích", "Tác phẩm Đường cách mệnh", "Tác phẩm Bản án chế độ thực dân Pháp"], "answer": "C", "key": "1.26", "explanation": "1927 → tập hợp bài giảng → Đường cách mệnh.", "topic": "1911–1929 · Nguyễn Ái Quốc & tổ chức tiền thân", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Tác phẩm được tập hợp từ bài giảng huấn luyện cán bộ, không phải sách tố cáo thực dân."}, {"chapter": 1, "number": 27, "id": "415505749", "question": "Trong cuốn Đường cách mệnh, Nguyễn Ái Quốc khẳng định, con đường cách mạng của các dân tộc bị áp bức là:", "options": ["Đánh đuổi đế quốc giải phóng dân tộc", "Đánh đổ phong kiến chia ruộng đất cho dân cày", "Giải phóng giai cấp, giải phóng dân tộc", "Giải phóng người lao động khỏi mọi sự áp bức"], "answer": "C", "key": "1.27", "explanation": "Đường cách mệnh → gắn giải phóng giai cấp với giải phóng dân tộc.", "topic": "1911–1929 · Nguyễn Ái Quốc & tổ chức tiền thân", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Chọn cách diễn đạt bao quát quan hệ giữa vấn đề dân tộc và vấn đề giai cấp."}, {"chapter": 1, "number": 28, "id": "415505750", "question": "Cuốn sách chính trị đầu tiên của CMVN là:", "options": ["Bản án chế độ thực dân Pháp", "Đường cách mệnh", "Sửa đổi lối làm việc", "Kháng chiến nhất định thắng lợi"], "answer": "B", "key": "1.28", "explanation": "Sách lý luận chính trị cho cách mạng Việt Nam → Đường cách mệnh.", "topic": "1911–1929 · Nguyễn Ái Quốc & tổ chức tiền thân", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Đừng nhầm sách tố cáo chế độ thực dân với sách trình bày lý luận, phương pháp cách mạng."}, {"chapter": 1, "number": 29, "id": "415505751", "question": "Sự khác nhau cơ bản giữa Hội Việt Nam Cách mạng Thanh niên và Tân Việt Cách mạng Đảng là về?", "options": ["Địa bàn hoạt động", "Thành phần tham gia", "Khuynh hướng cách mạng", "Phương pháp, hình thức đấu tranh"], "answer": "C", "key": "1.29", "explanation": "Theo đáp án nguồn: khác biệt chính là khuynh hướng; Tân Việt có quá trình phân hóa.", "topic": "1911–1929 · Nguyễn Ái Quốc & tổ chức tiền thân", "extra": false, "review": true, "tier": 8, "sources": [], "hint": "Xét định hướng tư tưởng của tổ chức, không chỉ vùng hoạt động hay thành phần tham gia."}, {"chapter": 1, "number": 30, "id": "415505752", "question": "Hội Việt Nam Cách mạng Thanh niên thực hiện chủ trương “vô sản hóa” khi nào?", "options": ["Cuối năm 1926 đầu năm 1927", "Cuối năm 1927 đầu năm 1928", "Cuối năm 1928 đầu năm 1929", "Cuối năm 1929 đầu năm 1930"], "answer": "C", "key": "1.30", "explanation": "Vô sản hóa → cuối 1928, đầu 1929 → đi vào lao động với công nhân.", "topic": "1911–1929 · Nguyễn Ái Quốc & tổ chức tiền thân", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Nhớ thời điểm phong trào đi vào nhà máy, trước khi xuất hiện ba tổ chức cộng sản."}, {"chapter": 1, "number": 31, "id": "415505753", "question": "Địa bàn hoạt động chủ yếu của Tân Việt Cách mạng Đảng là:", "options": ["Bắc kỳ", "Trung kỳ", "Nam kỳ", "Quảng Châu (Trung Quốc)"], "answer": "B", "key": "1.31", "explanation": "Tân Việt → hoạt động chủ yếu ở Trung Kỳ.", "topic": "1911–1929 · Nguyễn Ái Quốc & tổ chức tiền thân", "extra": false, "review": false, "tier": 7, "sources": [], "hint": "Gắn Tân Việt với vùng hoạt động của nhiều trí thức yêu nước miền Trung."}, {"chapter": 1, "number": 32, "id": "415505754", "question": "Đông Dương Cộng sản Liên Đoàn được ra đời từ tổ chức thanh niên yêu nước nào?", "options": ["Hội Việt Nam Cách mạng Thanh niên", "Việt Nam Quốc Dân Đảng", "Nam đồng thư xã", "Tân Việt Cách mạng Đảng"], "answer": "D", "key": "1.32", "explanation": "Tân Việt phân hóa → bộ phận tiên tiến lập Đông Dương Cộng sản Liên đoàn.", "topic": "1911–1929 · Nguyễn Ái Quốc & tổ chức tiền thân", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Chú ý tổ chức tiền thân phân hóa; không phải mọi tổ chức cộng sản đều từ Hội Thanh niên."}, {"chapter": 1, "number": 33, "id": "415505755", "question": "Tổ chức cộng sản đảng ra đời đầu tiên ở Việt Nam là:", "options": ["Đông Dương Cộng sản Đảng", "An Nam Cộng sản Đảng", "Đông Dương Cộng sản Liên đoàn", "Hội Việt Nam Cách mạng Thanh niên"], "answer": "A", "key": "1.33", "explanation": "Ba tổ chức năm 1929 → Đông Dương Cộng sản Đảng ra đời trước.", "topic": "1911–1929 · Nguyễn Ái Quốc & tổ chức tiền thân", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "So thứ tự xuất hiện của ba tổ chức cộng sản trong năm 1929."}, {"chapter": 1, "number": 34, "id": "415505756", "question": "Cơ quan ngôn luận của Đông Dương Cộng sản Đảng là:", "options": ["Báo Thanh niên", "Báo Búa liềm", "Báo Cứu quốc", "Báo Việt Nam độc lập"], "answer": "B", "key": "1.34", "explanation": "Đông Dương Cộng sản Đảng → báo Búa liềm.", "topic": "1911–1929 · Nguyễn Ái Quốc & tổ chức tiền thân", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Tên báo mang biểu tượng quen thuộc của phong trào công nhân và nông dân."}, {"chapter": 1, "number": 35, "id": "415505757", "question": "Đông Dương Cộng sản Đảng và An Nam Cộng sản Đảng ra đời từ tổ chức tiền thân nào?", "options": ["Tân Việt Cách mạng Đảng", "Hội Việt Nam Cách mạng Thanh niên", "Hội truyền bá chữ quốc ngữ", "Việt Nam Quốc dân Đảng"], "answer": "B", "key": "1.35", "explanation": "Hội Thanh niên phân hóa → Đông Dương Cộng sản Đảng và An Nam Cộng sản Đảng.", "topic": "1911–1929 · Nguyễn Ái Quốc & tổ chức tiền thân", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Hai tổ chức này cùng xuất phát từ sự phân hóa của một hội thanh niên cách mạng."}, {"chapter": 1, "number": 36, "id": "415505758", "question": "Sự phát triển của phong trào công nhân Việt Nam giai đoạn 1926 - 1929 có ý nghĩa lớn nhất là:", "options": ["Chứng tỏ giai cấp công nhân Việt Nam đã đủ sức lãnh đạo phong trào cách mạng", "Chứng tỏ ý thức giác ngộ và lập trường cách mạng của giai cấp công nhân Việt Nam đã được nâng cao", "Là một yếu tố dẫn tới sự ra đời của ba tổ chức cộng sản đảng", "Thúc đẩy cuộc đấu tranh chống thực dân Pháp của cả dân tộc Việt Nam"], "answer": "C", "key": "1.36", "explanation": "Phong trào công nhân phát triển → cơ sở thực tiễn hình thành các tổ chức cộng sản.", "topic": "1911–1929 · Nguyễn Ái Quốc & tổ chức tiền thân", "extra": false, "review": false, "tier": 7, "sources": [], "hint": "Đề hỏi ý nghĩa lớn nhất đối với quá trình chuẩn bị thành lập chính đảng."}, {"chapter": 1, "number": 37, "id": "415505759", "question": "Sự kiện nào đánh dấu phong trào công nhân Việt Nam bước đầu chuyển từ đấu tranh tự phát lên đấu tranh tự giác?", "options": ["Năm 1920 (tổ chức Công hội ở Sài Gòn được thành lập)", "Năm 1925 (cuộc bãi công Ba Son)", "Năm 1929 (sự ra đời ba tổ chức cộng sản)", "Năm 1930 (ĐCSVN ra đời)"], "answer": "B", "key": "1.37", "explanation": "Ba Son 1925 → BƯỚC ĐẦU tự giác; chú ý từ bước đầu.", "topic": "1911–1929 · Nguyễn Ái Quốc & tổ chức tiền thân", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Chú ý BƯỚC ĐẦU; nghĩ đến cuộc bãi công có tinh thần đoàn kết quốc tế năm 1925."}, {"chapter": 1, "number": 38, "id": "415505760", "question": "Sự kiện nào đánh dấu phong trào công nhân Việt Nam hoàn toàn chuyển sang đấu tranh tự giác?", "options": ["Sự thành lập Công hội năm 1920", "Cuộc bãi công của công nhân nhà máy đóng tàu Ba Son tháng 8/1925", "Phong trào vô sản hóa cuối năm 1928", "ĐCSVN ra đời đầu năm 1930"], "answer": "D", "key": "1.38", "explanation": "Đảng ra đời 1930 → HOÀN TOÀN tự giác; khác mốc Ba Son.", "topic": "1911–1929 · Nguyễn Ái Quốc & tổ chức tiền thân", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Chú ý HOÀN TOÀN; tìm mốc có chính đảng vô sản thống nhất lãnh đạo."}, {"chapter": 1, "number": 39, "id": "415505761", "question": "Yêu cầu cấp thiết của CMVN ở cuối năm 1929 đầu năm 1930 là:", "options": ["Đề cao nhiệm vụ giải phóng dân tộc", "Đề cao nhiệm vụ giải phóng dân tộc và xây dựng CNXH", "Khắc phục sự chia rẽ, phân tán của ba tổ chức cộng sản", "Khắc phục những tiêu cực trong hoạt động của giai cấp vô sản"], "answer": "C", "key": "1.39", "explanation": "Ba tổ chức hoạt động riêng → yêu cầu hợp nhất, khắc phục chia rẽ.", "topic": "1930 · Thành lập Đảng & Cương lĩnh", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Ba tổ chức cùng khuynh hướng nhưng riêng rẽ: vấn đề cấp thiết là tổ chức lại thế nào?"}, {"chapter": 1, "number": 40, "id": "415505762", "question": "Điểm chung trong khuynh hướng đấu tranh của ba tổ chức cộng sản ra đời cuối năm 1929 ở Việt Nam là:", "options": ["Theo khuynh hướng cách mạng vô sản", "Theo khuynh hướng cách mạng tư sản", "Theo khuynh hướng phong kiến", "Theo khuynh hướng xã hội không tưởng"], "answer": "A", "key": "1.40", "explanation": "Ba tổ chức tuy riêng rẽ nhưng cùng khuynh hướng vô sản.", "topic": "1930 · Thành lập Đảng & Cương lĩnh", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Phân biệt khuynh hướng tư tưởng chung với sự chia rẽ về mặt tổ chức."}, {"chapter": 1, "number": 41, "id": "415505763", "question": "Tổ chức nào là tiền thân của Đảng Cộng sản Việt Nam ( 3/2/1930)?", "options": ["Tân Việt Cách mạng Đảng", "Việt Nam Quốc Dân Đảng", "Hội Việt Nam cách mạng thanh niên", "Nam Đồng thư xã"], "answer": "C", "key": "1.41", "explanation": "Hội Thanh niên → đào tạo cán bộ, truyền bá lý luận → tiền thân của Đảng.", "topic": "1930 · Thành lập Đảng & Cương lĩnh", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Nhớ tổ chức do Nguyễn Ái Quốc lập năm 1925 để chuẩn bị cán bộ và tư tưởng."}, {"chapter": 1, "number": 42, "id": "415505764", "question": "Những tổ chức cộng sản Đảng nào đã tham dự Hội nghị hợp nhất diễn ra từ ngày 6/1/1930 đến 7/2/1930?", "options": ["Đông Dương Cộng sản Đảng, Đông Dương Cộng sản Liên đoàn", "Đông Dương Cộng sản Đảng, An Nam Cộng sản Đảng", "An Nam Cộng sản Đảng, Đông Dương Cộng sản Liên đoàn", "Đông Dương Cộng sản Đảng, An Nam Cộng sản Đảng, Đông Dương Cộng sản Liên đoàn"], "answer": "B", "key": "1.42", "explanation": "Hội nghị hợp nhất ban đầu có Đông Dương Cộng sản Đảng và An Nam Cộng sản Đảng.", "topic": "1930 · Thành lập Đảng & Cương lĩnh", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Đừng mặc định cả ba đều dự họp; có một tổ chức gia nhập sau hội nghị hợp nhất."}, {"chapter": 1, "number": 43, "id": "415505765", "question": "Hội nghị hợp nhất các tổ chức cộng sản diễn ra ở đâu?", "options": ["Hà Quảng - Cao Bằng", "Hàm Long - Hà Nội", "Hương Cảng - Trung Quốc", "Ma cao - Trung Quốc"], "answer": "C", "key": "1.43", "explanation": "Hội nghị hợp nhất → Hương Cảng, Trung Quốc.", "topic": "1930 · Thành lập Đảng & Cương lĩnh", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Địa điểm hội nghị ở ngoài lãnh thổ Việt Nam, tại một trung tâm cảng của Trung Quốc."}, {"chapter": 1, "number": 44, "id": "415505766", "question": "Nguyễn Ái Quốc đã lấy tư cách gì để triệu tập hội nghị hợp nhất các tổ chức Cộng sản năm 1930?", "options": ["Chủ trì hội nghị", "Phái viên của Quốc tế Cộng sản", "Khách mời của hội nghị", "Đại biểu tham dự hội nghị"], "answer": "B", "key": "1.44", "explanation": "Nguyễn Ái Quốc → tư cách phái viên Quốc tế Cộng sản để triệu tập.", "topic": "1930 · Thành lập Đảng & Cương lĩnh", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Hãy xét thẩm quyền triệu tập từ tổ chức cộng sản quốc tế, không chỉ vai trò tại cuộc họp."}, {"chapter": 1, "number": 45, "id": "415505767", "question": "ĐCSVN ra đời là bước ngoặt vĩ đại của CMVN vì đã chấm dứt:", "options": ["Sự hoạt động riêng rẽ của 3 tổ chức cộng sản đảng", "Thời kỳ CMVN không phải là một bộ phận khăng khít của cách mạng vô sản thế giới", "Thời kỳ mọi giai cấp, tầng lớp nhân dân Việt Nam cam chịu áp bức, bóc lột của thực dân và phong kiến tay sai", "Thời kỳ CMVN thiếu đường lối chính trị đúng đắn để giải quyết triệt để những mâu thuẫn cơ bản, chủ yếu của xã hội"], "answer": "D", "key": "1.45", "explanation": "Đảng ra đời → chấm dứt khủng hoảng đường lối và giai cấp lãnh đạo.", "topic": "1930 · Thành lập Đảng & Cương lĩnh", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Nghĩ đến cuộc khủng hoảng đường lối và lực lượng lãnh đạo trước năm 1930."}, {"chapter": 1, "number": 46, "id": "415505768", "question": "Đảng Cộng sản Việt Nam ra đời là sự kết hợp của:", "options": ["Chủ nghĩa Mác - Lênin với phong trào công nhân", "Chủ nghĩa Mác - Lênin với phong trào yêu nước", "Phong trào công nhân và phong trào yêu nước", "Chủ nghĩa Mác - Lênin với phong trào công nhân và phong trào yêu nước"], "answer": "D", "key": "1.46", "explanation": "Ba yếu tố → Mác–Lênin + công nhân + yêu nước.", "topic": "1930 · Thành lập Đảng & Cương lĩnh", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Công thức ở Việt Nam có thêm một phong trào dân tộc bên cạnh hai yếu tố phổ biến."}, {"chapter": 1, "number": 47, "id": "415505769", "question": "Vai trò to lớn nhất của Nguyễn Ái Quốc đối với CMVN giai đoạn 1925 - 1930 là:", "options": ["Tìm ra con đường cứu nước đúng đắn cho dân tộc Việt Nam", "Mở các lớp huấn luyện chính trị ở Quảng Châu (Trung Quốc)", "Soạn thảo Cương lĩnh chính trị đầu tiên của ĐCSVN", "Hợp nhất ba tổ chức cộng sản thành một đảng duy nhất - Đảng Cộng sản Việt Nam"], "answer": "D", "key": "1.47", "explanation": "1925–1930 → đỉnh cao vai trò tổ chức là thành lập Đảng. Lưu ý hội nghị đầu tiên hợp nhất hai tổ chức; Liên đoàn gia nhập sau.", "topic": "1930 · Thành lập Đảng & Cương lĩnh", "extra": false, "review": true, "tier": 8, "sources": [], "hint": "Giai đoạn này nhấn mạnh việc tổ chức lực lượng thành một chính đảng thống nhất."}, {"chapter": 1, "number": 48, "id": "415505770", "question": "Đường lối chiến lược của CMVN được xác định trong Cương lĩnh chính trị đầu tiên (1930) là:", "options": ["Tiến hành cách mạng tư sản dân quyền và thổ địa cách mạng để đi tới xã hội cộng sản", "Tiến hành cách mạng tư sản dân quyền, tiến lên xây dựng CNXH", "Xây dựng chính quyền công nông binh, tiến lên xây dựng CNXH", "Đánh đổ đế quốc và phong kiến làm cho Việt Nam hoàn toàn độc lập"], "answer": "A", "key": "1.48", "explanation": "Cương lĩnh 1930 → tư sản dân quyền + thổ địa cách mạng → xã hội cộng sản.", "topic": "1930 · Thành lập Đảng & Cương lĩnh", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Tìm đầy đủ hai nhiệm vụ cách mạng và đích phát triển cuối cùng trong câu chữ Cương lĩnh."}, {"chapter": 1, "number": 49, "id": "415505771", "question": "Nhiệm vụ cách mạng hàng đầu được xác định trong Cương lĩnh chính trị đầu tiên của ĐCSVN là:", "options": ["Giải phóng dân tộc", "Đánh đổ phong kiến", "Xây dựng chính quyền công nông binh", "Cải thiện đời sống của nhân dân"], "answer": "A", "key": "1.49", "explanation": "Cương lĩnh đầu tiên → ưu tiên giải phóng dân tộc.", "topic": "1930 · Thành lập Đảng & Cương lĩnh", "extra": false, "review": false, "tier": 7, "sources": [], "hint": "Phân biệt nhiệm vụ cấp thiết của một nước thuộc địa với nhiệm vụ về ruộng đất."}, {"chapter": 1, "number": 50, "id": "415505772", "question": "Cương lĩnh chính trị đầu tiên của ĐCSVN xác định giai cấp lãnh đạo cách mạng là:", "options": ["Nông dân", "Tư sản dân tộc", "Công nhân", "Địa chủ phong kiến"], "answer": "C", "key": "1.50", "explanation": "Giai cấp công nhân lãnh đạo thông qua đội tiên phong là Đảng.", "topic": "1930 · Thành lập Đảng & Cương lĩnh", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Phân biệt giai cấp lãnh đạo với lực lượng đông đảo nhất tham gia cách mạng."}, {"chapter": 1, "number": 51, "id": "415505773", "question": "Cương lĩnh chính trị đầu tiên xác định mối quan hệ quốc tế của CMVN là:", "options": ["Một bộ phận của phong trào cách mạng châu Á", "Gắn bó mật thiết với cách mạng vô sản Pháp", "Gắn bó mật thiết với cách mạng Liên Xô", "Là một bộ phận của phong trào cách mạng thế giới"], "answer": "D", "key": "1.51", "explanation": "Cách mạng Việt Nam → bộ phận của cách mạng thế giới.", "topic": "1930 · Thành lập Đảng & Cương lĩnh", "extra": false, "review": false, "tier": 7, "sources": [], "hint": "Xét vị trí cách mạng Việt Nam trong phong trào quốc tế, không phải hoạt động tách biệt."}, {"chapter": 1, "number": 52, "id": "415505774", "question": "Cương lĩnh chính trị đầu tiên của Đảng xác định cách mạng “hết sức liên lạc” với lực lượng nào sau đây?", "options": ["Tiểu tư sản, trí thức, trung nông", "Phú nông, trung, tiểu địa chủ và tư bản An Nam", "Tiểu tư sản và tư sản dân tộc", "Phong kiến yêu nước, tư sản dân tộc"], "answer": "A", "key": "1.52", "explanation": "Hết sức liên lạc → tiểu tư sản, trí thức, trung nông để mở rộng lực lượng.", "topic": "1930 · Thành lập Đảng & Cương lĩnh", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Chú ý cụm HẾT SỨC LIÊN LẠC, không nhầm với lực lượng nòng cốt công–nông."}, {"chapter": 1, "number": 53, "id": "415505775", "question": "Một trong những nhiệm vụ chính trị của CMVN được xác định trong Cương lĩnh chính trị đầu tiên là:", "options": ["Đánh đổ đế quốc chủ nghĩa Pháp và bọn phong kiến", "Đánh đổ phong kiến và giai cấp tư sản mại bản", "Đánh đổ đế quốc chủ nghĩa pháp và tư sản mại bản", "Đánh đổ phong kiến, thủ tiêu hết các thứ quốc trái"], "answer": "A", "key": "1.53", "explanation": "Hai đối tượng → đế quốc Pháp và phong kiến.", "topic": "1930 · Thành lập Đảng & Cương lĩnh", "extra": false, "review": false, "tier": 7, "sources": [], "hint": "Chọn đủ hai đối tượng cần đánh đổ trong nhiệm vụ chính trị."}, {"chapter": 1, "number": 54, "id": "415505776", "question": "Hội nghị nào quyết định đổi tên ĐCSVN thành Đảng Cộng sản Đông Dương?", "options": ["Hội nghị hợp nhất thành lập Đảng tháng 2/1930", "Hội nghị Trung ương Đảng tháng 10/1930", "Hội nghị Trung ương 8 tháng 5/1941", "Hội nghị Toàn quốc tháng 8/1945"], "answer": "B", "key": "1.54", "explanation": "10/1930 → đổi tên thành Đảng Cộng sản Đông Dương.", "topic": "1930 · Thành lập Đảng & Cương lĩnh", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Nhớ hội nghị thông qua Luận cương chính trị, diễn ra sau ngày thành lập Đảng."}, {"chapter": 1, "number": 55, "id": "415505777", "question": "Trong Luận cương chính trị tháng 10/1930, vấn đề nào được coi là “cái cốt của cuộc cách mạng tư sản dân quyền” ?", "options": ["Vấn đề thổ địa", "Vấn đề giải phóng dân tộc", "Vấn đề thành lập chính phủ công nông binh", "Vấn đề cải thiện đời sống nhân dân"], "answer": "A", "key": "1.55", "explanation": "Luận cương 10/1930 → thổ địa là cái cốt.", "topic": "1930 · Thành lập Đảng & Cương lĩnh", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Phân biệt trọng tâm của Luận cương với sự ưu tiên vấn đề dân tộc trong Cương lĩnh đầu tiên."}, {"chapter": 1, "number": 56, "id": "415505778", "question": "Luận cương chính trị tháng 10/1930 đã chỉ ra mâu thuẫn giai cấp diễn ra gay gắt ở Việt Nam là:", "options": ["Giữa một bên là toàn thể dân tộc Việt Nam với một bên là thực dân Pháp và tay sai", "Giữa một bên là địa chủ phong kiến với một bên là nông dân", "Giữa một bên là thợ thuyền, dân cày với các phần tử lao khổ với một bên là địa chủ, phong kiến, tư bổn và đế quốc chủ nghĩa", "Giữa một bên là các thành phần lao khổ với một bên là bọn áp bức, bóc lột"], "answer": "C", "key": "1.56", "explanation": "Luận cương nhấn mạnh đối kháng giai cấp giữa lao động và bóc lột.", "topic": "1930 · Thành lập Đảng & Cương lĩnh", "extra": false, "review": false, "tier": 7, "sources": [], "hint": "Luận cương nhấn mạnh đối kháng giữa người lao động và các lực lượng bóc lột."}, {"chapter": 1, "number": 57, "id": "415505779", "question": "Cương lĩnh chính trị đầu tiên của Đảng với Luận cương chính trị tháng 10/1930 có sự khác biệt về?", "options": ["Phương hướng chiến lược của cách mạng", "Chủ trương tập hợp lực lượng cách mạng", "Quan hệ quốc tế của CMVN", "Vai trò lãnh đạo cách mạng"], "answer": "B", "key": "1.57", "explanation": "Cương lĩnh tập hợp rộng; Luận cương thiên về công–nông.", "topic": "1930 · Thành lập Đảng & Cương lĩnh", "extra": false, "review": false, "tier": 8, "sources": [], "hint": "So phạm vi tập hợp các tầng lớp: văn kiện nào rộng hơn ngoài công nhân, nông dân?"}, {"chapter": 1, "number": 58, "id": "415505780", "question": "Nội dung nào phản ánh hạn chế của Luận cương chính trị tháng 10/1930 của Đảng?", "options": ["Xác định nhiều vấn đề cơ bản về chiến lược và sách lược cách mạng", "Lực lượng cách mạng chỉ có công nhân và nông dân", "Khẳng định công nhân là lực lượng lãnh đạo cách mạng", "Gắn cách mạng Đông Dương với cách mạng thế giới"], "answer": "B", "key": "1.58", "explanation": "Hạn chế → đánh giá lực lượng hẹp, chưa phát huy đầy đủ các tầng lớp yêu nước.", "topic": "1930 · Thành lập Đảng & Cương lĩnh", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Tìm hạn chế trong đánh giá, tập hợp những lực lượng yêu nước ngoài công–nông."}, {"chapter": 1, "number": 59, "id": "415505781", "question": "Luận điểm đánh giá nào sau đây không đúng về Luận cương chính trị tháng 10/1930?", "options": ["Luận cương đã xác định nhiều vấn đề cơ bản về chiến lược cách mạng", "Luận cương đã xác định cách mạng Đông Dương là một bộ phận của cách mạng vô sản thế giới", "Luận cương đã xác định giai cấp lãnh đạo cách mạng là giai cấp công nhân", "Luận cương đã đề ra được một chiến lược liên minh dân tộc và giai cấp rộng rãi đấu tranh chống đế quốc xâm lược và tay sai"], "answer": "D", "key": "1.59", "explanation": "Câu phủ định: liên minh dân tộc rộng rãi chưa được Luận cương giải quyết tốt.", "topic": "1930 · Thành lập Đảng & Cương lĩnh", "extra": false, "review": false, "tier": 8, "sources": [], "hint": "Câu phủ định: đừng gán ưu điểm của Cương lĩnh đầu tiên cho Luận cương tháng 10."}, {"chapter": 1, "number": 60, "id": "415505782", "question": "Chương trình hành động của Đảng Cộng sản Đông Dương (6/1932) vạch ra nhiều nhiệm vụ đấu tranh trước mắt để:", "options": ["Phát triển tổ chức Đảng trên khắp đất nước", "Thúc đẩy các cuộc đấu tranh của nhân dân phát triển mạnh mẽ hơn nữa", "Khôi phục hệ thống tổ chức Đảng và phong trào cách mạng", "Đối phó lại với sự đàn áp, khủng bố của kẻ thù"], "answer": "C", "key": "1.60", "explanation": "6/1932 → Chương trình hành động → phục hồi tổ chức, phong trào.", "topic": "1932–1939 · Phục hồi & dân chủ", "extra": false, "review": false, "tier": 7, "sources": [], "hint": "Đặt trong bối cảnh tổ chức bị đàn áp sau cao trào 1930–1931: cần khôi phục điều gì?"}, {"chapter": 1, "number": 61, "id": "415505783", "question": "Đại hội ĐBTQ lần thứ I của Đảng Cộng sản Đông Dương đã bầu ai làm Tổng Bí thư?", "options": ["Trần Phú", "Lê Hồng Phong", "Hà Huy Tập", "Trường Chinh"], "answer": "B", "key": "1.61", "explanation": "Đại hội I năm 1935 → Tổng Bí thư Lê Hồng Phong.", "topic": "1932–1939 · Phục hồi & dân chủ", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Nhớ người đứng đầu Đảng được bầu tại đại hội ở Ma Cao năm 1935."}, {"chapter": 1, "number": 62, "id": "415505784", "question": "Đại hội ĐBTQ lần thứ I (3/1935) của Đảng Cộng sản Đông Dương đánh dấu:", "options": ["Bước ngoặt phát triển mới của cách mạng Đông Dương", "Bước trưởng thành mới của Đảng về mặt tổ chức và hoạch định đường lối cách mạng", "Sự phục hồi hệ thống tổ chức của Đảng và phong trào cách mạng quần chúng", "Đảng Cộng sản Đông Dương được Quốc tế Cộng sản công nhận là một chi bộ độc lập"], "answer": "C", "key": "1.62", "explanation": "Đại hội I → dấu mốc phục hồi hệ thống tổ chức Đảng.", "topic": "1932–1939 · Phục hồi & dân chủ", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Đại hội đầu tiên sau khủng bố trắng đánh dấu kết quả phục hồi, chưa phải giành chính quyền."}, {"chapter": 1, "number": 63, "id": "415505785", "question": "Nội dung nào sau đây không phải là điều kiện khách quan tác động tới quyết định đề cao vấn đề dân chủ trong giai đoạn 1936-1939 của Đảng Cộng sản Đông Dương?", "options": ["Sự xuất hiện của chủ nghĩa phát xít và nguy cơ chiến tranh", "Những quyết định của Đại hội VII Quốc tế Cộng sản (7/1935)", "Chính sách nới lỏng của mặt trận nhân dân Pháp", "Nhu cầu về tự do, dân chủ, cơm áo và hòa bình của nhân dân Việt Nam"], "answer": "D", "key": "1.63", "explanation": "Nhu cầu của nhân dân trong nước là yếu tố CHỦ QUAN, không phải khách quan quốc tế.", "topic": "1932–1939 · Phục hồi & dân chủ", "extra": false, "review": false, "tier": 8, "sources": [], "hint": "Phân biệt tác động từ quốc tế với nhu cầu bên trong xã hội Việt Nam."}, {"chapter": 1, "number": 64, "id": "415505786", "question": "Mục tiêu cụ thể trước mắt của cao trào cách mạng 1936-1939 là gì?", "options": ["Độc lập dân tộc", "Các quyền dân chủ đơn sơ", "Ruộng đất cho dân cày", "Tất cả các mục tiêu"], "answer": "B", "key": "1.64", "explanation": "1936–1939 → nhiệm vụ trước mắt là quyền dân chủ đơn sơ.", "topic": "1932–1939 · Phục hồi & dân chủ", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Đề hỏi mục tiêu TRƯỚC MẮT, không phải mục tiêu chiến lược cuối cùng."}, {"chapter": 1, "number": 65, "id": "415505787", "question": "Đối tượng của CMVN trong giai đoạn 1936-1939 là:", "options": ["Bọn đế quốc xâm lược", "Địa chủ phong kiến", "Đế quốc và phong kiến", "Bọn phản động thuộc địa và tay sai"], "answer": "D", "key": "1.65", "explanation": "Đối tượng trước mắt → phản động thuộc địa và tay sai; không đánh đồng toàn bộ người Pháp.", "topic": "1932–1939 · Phục hồi & dân chủ", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Đối tượng trước mắt được thu hẹp để tập hợp lực lượng rộng hơn, không đánh đồng mọi người Pháp."}, {"chapter": 1, "number": 66, "id": "415505788", "question": "Các hình thức tổ chức và đấu tranh cách mạng trong giai đoạn 1936 - 1939 là:", "options": ["Công khai, hợp pháp.", "Nửa công khai, nửa hợp pháp.", "Bí mật, bất hợp pháp.", "Công khai, nửa công khai, hợp pháp, nửa hợp pháp và bí mật"], "answer": "D", "key": "1.66", "explanation": "1936–1939 → kết hợp công khai, hợp pháp với bí mật.", "topic": "1932–1939 · Phục hồi & dân chủ", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Điều kiện mới cho phép tận dụng hình thức hợp pháp nhưng vẫn cần tổ chức bí mật."}, {"chapter": 1, "number": 67, "id": "415505789", "question": "Phong trào dân chủ 1936-1939 ở Việt Nam là một bước chuẩn bị cho thắng lợi của Cách mạng Tháng Tám năm 1945 vì đã:", "options": ["Đưa Đảng Cộng sản Đông Dương ra hoạt động công khai", "Khắc phục triệt để hạn chế của Luận cương chính trị tháng 10/1930", "Đảng Cộng sản Đông Dương tích lũy thêm nhiều kinh nghiệm mới", "Xây dựng được một lực lượng chính trị quần chúng đông đảo"], "answer": "D", "key": "1.67", "explanation": "Phong trào dân chủ → rèn luyện, tập hợp lực lượng chính trị đông đảo.", "topic": "1932–1939 · Phục hồi & dân chủ", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Nghĩ đến đội ngũ quần chúng được tổ chức và rèn luyện trước tổng khởi nghĩa."}, {"chapter": 1, "number": 68, "id": "415505790", "question": "Vì sao trong những năm 1939-1941 Đảng Cộng sản Đông Dương lãnh đạo chuyển hướng chiến lược đấu tranh cách mạng?", "options": ["Do sự biến đổi mau lẹ của tình hình thế giới", "Do chính sách thống trị và bóc lột của Pháp - Nhật", "Do yêu cầu của sự nghiệp giải phóng dân tộc đặt ra cấp thiết", "Do yêu cầu giải quyết vấn đề dân tộc trong khuôn khổ từng nước Đông Dương"], "answer": "C", "key": "1.68", "explanation": "Chiến tranh thế giới làm vấn đề độc lập cấp bách → chuyển hướng giải phóng dân tộc.", "topic": "1939–1941 · Chuyển hướng chiến lược", "extra": false, "review": false, "tier": 7, "sources": [], "hint": "Chiến tranh thế giới làm vấn đề sống còn của dân tộc trở nên cấp bách hơn."}, {"chapter": 1, "number": 69, "id": "415505791", "question": "Khi quân Nhật tiến vào Đông Dương, thực dân Pháp đã làm gì?", "options": ["Tấn công quân Nhật để độc chiếm Đông Dương", "Ráo riết chuẩn bị, chờ thời cơ phản công quân Nhật", "Nhanh chóng đầu hàng", "Ra sức vơ vét, bóc lột nhân dân ta"], "answer": "C", "key": "1.69", "explanation": "Nhật vào Đông Dương → Pháp đầu hàng, cấu kết với Nhật.", "topic": "1939–1941 · Chuyển hướng chiến lược", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Phân biệt thái độ chống Nhật với việc Pháp nhanh chóng chấp nhận cùng thống trị Đông Dương."}, {"chapter": 1, "number": 70, "id": "415505792", "question": "Hội nghị lần thứ Tám của Ban Chấp hành Trung ương Đảng Cộng sản Đông Dương (5/1941) đồng chí nào chủ trì?", "options": ["Đồng chí Nguyễn Ái Quốc", "Đồng chí Võ Văn Tần", "Đồng chí Trường Chinh", "Đồng chí Lê Duẩn"], "answer": "A", "key": "1.70", "explanation": "Trung ương 8, tháng 5/1941 → Nguyễn Ái Quốc chủ trì.", "topic": "1939–1941 · Chuyển hướng chiến lược", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Hội nghị diễn ra sau khi vị lãnh tụ tìm đường cứu nước trở về Tổ quốc."}, {"chapter": 1, "number": 71, "id": "415505793", "question": "Hội nghị lần thứ Tám của Ban Chấp hành Trung ương Đảng Cộng sản Đông Dương (5/1941) nhấn mạnh mâu thuẫn chủ yếu đòi hỏi phải được giải quyết cấp bách là:", "options": ["Mâu thuẫn giữa dân tộc Việt Nam với Pháp xâm lược", "Mâu thuẫn giữa dân tộc Việt Nam với phát xít Nhật", "Mâu thuẫn giữa dân tộc Việt Nam với Pháp và Nhật", "Mâu thuẫn giữa giai cấp nông dân và địa chủ phong kiến"], "answer": "C", "key": "1.71", "explanation": "Pháp–Nhật cùng áp bức → mâu thuẫn dân tộc nổi lên cấp bách.", "topic": "1939–1941 · Chuyển hướng chiến lược", "extra": false, "review": false, "tier": 7, "sources": [], "hint": "Chọn mâu thuẫn bao quát toàn dân tộc dưới ách hai thế lực ngoại xâm."}, {"chapter": 1, "number": 72, "id": "415505794", "question": "Hội nghị lần thứ 8 của Ban Chấp hành Trung ương Đảng Cộng sản Đông Dương (5/1941) chỉ ra nhiệm vụ trung tâm của Đảng và nhân dân Việt Nam là:", "options": ["Củng cố và phát triển tổ chức đảng, làm cho Đảng vững mạnh", "Ra sức phát triển lực lượng chính trị và lực lượng vũ trang", "Chĩa mũi nhọn tấn công vào Pháp - Nhật", "Chuẩn bị khởi nghĩa vũ trang giành chính quyền"], "answer": "D", "key": "1.72", "explanation": "Nhiệm vụ trung tâm 1941 → chuẩn bị khởi nghĩa vũ trang.", "topic": "1939–1941 · Chuyển hướng chiến lược", "extra": false, "review": false, "tier": 7, "sources": [], "hint": "Phân biệt mục tiêu giải phóng dân tộc với công việc trực tiếp chuẩn bị giành chính quyền."}, {"chapter": 1, "number": 73, "id": "415505795", "question": "Hội nghị lần thứ 8 Ban chấp hành Trung ương Đảng (5/1941) đã quyết định tạm gác khẩu hiệu nào?", "options": ["Giảm tô, giảm thuế", "Giải phóng dân tộc", "Đánh đổ địa chủ, chia ruộng đất cho dân cày", "Tịch thu ruộng đất của Đế quốc và Việt gian"], "answer": "C", "key": "1.73", "explanation": "Ưu tiên độc lập → tạm gác đánh đổ địa chủ, chia ruộng đất.", "topic": "1939–1941 · Chuyển hướng chiến lược", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Để đoàn kết toàn dân, yêu cầu đấu tranh giai cấp nào được tạm thời lùi lại?"}, {"chapter": 1, "number": 74, "id": "415505796", "question": "Các tổ chức quần chúng trong Mặt trận Việt Minh đều có tên gọi chung là:", "options": ["Hội Phản đế", "Hội Cứu tế", "Hội Ái hữu", "Hội Cứu quốc"], "answer": "D", "key": "1.74", "explanation": "Việt Minh → các hội quần chúng mang tên Cứu quốc.", "topic": "1939–1941 · Chuyển hướng chiến lược", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Tên các hội thành viên thể hiện chung mục đích cứu nước."}, {"chapter": 1, "number": 75, "id": "415505797", "question": "Hội nghị lần thứ 8 Ban Chấp hành Trung ương Đảng (5/1941) chủ trương sau khi cách mạng thành công sẽ thành lập Nhà nước?", "options": ["Nhà nước Việt Nam Dân chủ Cộng hòa theo tinh thần tân dân chủ", "Nhà nước Việt Nam Dân chủ Cộng hòa theo tinh thần tân tư sản", "Nhà nước Việt Nam Dân chủ Cộng hòa theo tinh thần tân phong kiến", "Nhà nước Việt Nam Tư sản Cộng hòa theo tinh thần tân dân chủ"], "answer": "A", "key": "1.75", "explanation": "Nhà nước dự kiến → Việt Nam Dân chủ Cộng hòa theo tinh thần tân dân chủ.", "topic": "1939–1941 · Chuyển hướng chiến lược", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Chủ trương hướng tới một nhà nước độc lập có hình thức cộng hòa và dân chủ."}, {"chapter": 1, "number": 76, "id": "415505798", "question": "Vì sao Hội nghị tháng 5/1941 của Ban Chấp hành Trung ương Đảng Cộng sản Đông Dương có tầm quan trọng đặc biệt đối với Cách mạng Tháng Tám 1945?", "options": ["Chủ trương giương cao ngọn cờ giải phóng dân tộc", "Hoàn chỉnh chủ trương chiến lược được đề ra từ Hội nghị Trung ương tháng 11/1939", "Giải quyết vấn đề dân tộc trong khuôn khổ từng nước Đông Dương", "Củng cố được khối đoàn kết toàn dân"], "answer": "B", "key": "1.76", "explanation": "11/1939 khởi đầu chuyển hướng; 5/1941 hoàn chỉnh chuyển hướng.", "topic": "1939–1941 · Chuyển hướng chiến lược", "extra": false, "review": false, "tier": 7, "sources": [], "hint": "Đừng nhầm KHỞI ĐẦU chuyển hướng năm 1939 với HOÀN CHỈNH vào năm 1941."}, {"chapter": 1, "number": 77, "id": "415505799", "question": "Nội dung nào sau đây là không đúng về nạn đói năm 1945?", "options": ["Nạn đói kéo dài từ cuối năm 1944 sang đầu năm 1945", "Nạn đói xảy ra trên phạm vi cả nước", "Nạn đói làm chết hơn 2 triệu đồng bào", "Một phần sáu dân số miền Bắc bị chết trong nạn đói"], "answer": "B", "key": "1.77", "explanation": "Câu phủ định: nạn đói 1945 tập trung ở Bắc Bộ và Bắc Trung Bộ, không trên cả nước.", "topic": "1944–1945 · Cách mạng Tháng Tám", "extra": false, "review": false, "tier": 8, "sources": [], "hint": "Câu phủ định: kiểm tra phạm vi địa lý của nạn đói, tránh khái quát thành toàn quốc."}, {"chapter": 1, "number": 78, "id": "415505800", "question": "Nội dung nào sau đây không đúng về tình hình Việt Nam sau ngày 9/3/1945?", "options": ["Pháp thiết lập trở lại nền thống trị trên toàn Việt Nam", "Vai trò thống trị của Pháp ở Việt Nam hoàn toàn bị thủ tiêu", "CMVN có một kẻ thù ngoại xâm duy nhất", "Mâu thuẫn dân tộc là mâu thuẫn lớn nhất trong lòng xã hội Việt Nam"], "answer": "A", "key": "1.78", "explanation": "9/3/1945 → Nhật đảo chính Pháp; không phải Pháp tái lập thống trị.", "topic": "1944–1945 · Cách mạng Tháng Tám", "extra": false, "review": false, "tier": 8, "sources": [], "hint": "Sau đảo chính, quyền thống trị thuộc bên nào? Loại phương án khôi phục vị trí cũ của Pháp."}, {"chapter": 1, "number": 79, "id": "415505801", "question": "Kẻ thù của nhân dân Đông Dương trước ngày 9/3/1945 là ai?", "options": ["Thực dân Pháp và bọn phong kiến tay sai", "Thực dân Pháp, phát xít Nhật và bọn tay sai của chúng", "Phát xít Nhật và bọn tay sai của chúng", "Thực dân Pháp và đồng minh của Pháp ở Đông Dương"], "answer": "B", "key": "1.79", "explanation": "Trước đảo chính → kẻ thù gồm cả Pháp, Nhật và tay sai.", "topic": "1944–1945 · Cách mạng Tháng Tám", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Chú ý TRƯỚC ngày đảo chính: hai thế lực ngoại xâm vẫn cùng tồn tại."}, {"chapter": 1, "number": 80, "id": "415505802", "question": "Khi Nhật đảo chính Pháp (9/3/1945), Ban thường vụ Trung ương Đảng họp và ra chỉ thị:", "options": ["“Tổng khởi nghĩa giành chính quyền”", "“Nhật - Pháp bắn nhau và hành động của chúng ta”", "“Phá kho thóc, giải quyết nạn đói”", "“Đả đảo đế quốc, đả đảo phong kiến”"], "answer": "B", "key": "1.80", "explanation": "Nhật đảo chính Pháp → chỉ thị Nhật–Pháp bắn nhau và hành động của chúng ta.", "topic": "1944–1945 · Cách mạng Tháng Tám", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Tên chỉ thị mô tả sự xung đột giữa hai kẻ thù và định hướng hành động cách mạng."}, {"chapter": 1, "number": 81, "id": "415505803", "question": "Sau khi Ban thường vụ Trung ương ra chỉ thị “Nhật - Pháp bắn nhau và hành động của chúng ta” (12/3/1945), quần chúng nhân dân đã thực hiện:", "options": ["Cao trào đánh Pháp, đuổi Nhật", "Cao trào kháng Nhật cứu nước", "Cao trào đánh Pháp", "Tổng khởi nghĩa giành chính quyền"], "answer": "B", "key": "1.81", "explanation": "12/3/1945 → phát động cao trào kháng Nhật cứu nước.", "topic": "1944–1945 · Cách mạng Tháng Tám", "extra": false, "review": true, "tier": 8, "sources": [], "hint": "Phân biệt cao trào sau tháng 3 với tổng khởi nghĩa toàn quốc tháng 8."}, {"chapter": 1, "number": 82, "id": "415505804", "question": "Thay khẩu hiệu \"Đánh đuổi Nhật - Pháp\" bằng khẩu hiệu \"Đánh đuổi phát xít Nhật\" được nêu ra trong:", "options": ["Chỉ thị \"Nhật - Pháp bắn nhau và hành động của chúng ta\" (3/1945)", "Hội nghị Ban chấp hành Trung ương Đảng (5/1945)", "Hội nghị Toàn quốc của Đảng (8/1945)", "Nghị quyết của Đại hội quốc dân Tân Trào (8/1945)"], "answer": "A", "key": "1.82", "explanation": "Chỉ thị tháng 3/1945 → xác định kẻ thù chính, trước mắt là phát xít Nhật.", "topic": "1944–1945 · Cách mạng Tháng Tám", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Tìm văn bản ra ngay sau cuộc đảo chính tháng 3, không phải hội nghị tháng 8."}, {"chapter": 1, "number": 83, "id": "415505805", "question": "Trong cao trào kháng Nhật cứu nước, xuất phát từ lợi ích sống còn trước mắt của quần chúng, Đảng đã kịp thời đề ra khẩu hiệu:", "options": ["Đánh đuổi phát xít Pháp - Nhật", "Đập tan sự cấu kết bóc lột của phát xít Pháp - Nhật", "Đánh đuổi phát xít Nhật ra khỏi Đông Dương, giành độc lập dân tộc", "Phá kho thóc, giải quyết nạn đói"], "answer": "D", "key": "1.83", "explanation": "Cứu đói gắn cứu nước → phá kho thóc, giải quyết nạn đói.", "topic": "1944–1945 · Cách mạng Tháng Tám", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Khẩu hiệu kết hợp lợi ích thiết thân trước mắt với việc tập hợp quần chúng chống Nhật."}, {"chapter": 1, "number": 84, "id": "415505806", "question": "Nội dung nào sau đây không đúng về cao trào kháng Nhật, cứu nước?", "options": ["Là một cuộc khởi nghĩa từng phần và chiến tranh du kích cục bộ, giành chính quyền ở những nơi có điều kiện", "Làm cho trận địa cách mạng được mở rộng, lực lượng cách mạng được tăng cường", "Làm cho toàn Đảng, toàn dân sẵn sàng, chủ động, tiến lên chớp thời cơ tổng khởi nghĩa", "Là thời kỳ cả dân tộc thực hiện “dù phải đốt cháy cả dãy Trường Sơn cũng phải kiên quyết giành cho được độc lập”"], "answer": "D", "key": "1.84", "explanation": "Cao trào kháng Nhật là khởi nghĩa từng phần; câu nói quyết giành độc lập gắn thời cơ tổng khởi nghĩa.", "topic": "1944–1945 · Cách mạng Tháng Tám", "extra": false, "review": false, "tier": 8, "sources": [], "hint": "Câu phủ định: phân biệt thời kỳ khởi nghĩa từng phần với quyết tâm khi thời cơ tổng khởi nghĩa đến."}, {"chapter": 1, "number": 85, "id": "415505807", "question": "Ai là người đứng đầu đội Việt Nam tuyên truyền giải phóng quân ngay khi thành lập (22/12/1944)?", "options": ["Đồng chí Trường Chinh", "Đồng chí Phạm Văn Đồng", "Đồng chí Võ Nguyên Giáp", "Đồng chí Lê Hồng Phong"], "answer": "C", "key": "1.85", "explanation": "22/12/1944 → Võ Nguyên Giáp tổ chức, chỉ huy theo chỉ thị Hồ Chí Minh. Phân biệt người chỉ đạo tổ chức với đội trưởng đầu tiên Hoàng Sâm; đề dùng đứng đầu chưa rõ chức danh.", "topic": "1944–1945 · Cách mạng Tháng Tám", "extra": false, "review": true, "tier": 8, "sources": [], "hint": "Đề dùng đứng đầu chưa rõ: phân biệt người tổ chức chỉ huy với chức danh đội trưởng đầu tiên."}, {"chapter": 1, "number": 86, "id": "415505808", "question": "Vì sao Đảng Cộng sản Đông Dương không phát động tổng khởi nghĩa khi Nhật đảo chính Pháp ngày 9/3/1945?", "options": ["Quân Nhật mới chỉ suy yếu", "Tầng lớp trung gian vẫn chưa ngả hẳn về phía cách mạng", "Đảng Cộng sản Đông Dương và quần chúng chưa sẵn sàng hành động", "Thời cơ cách mạng chưa chín muồi"], "answer": "D", "key": "1.86", "explanation": "Tháng 3/1945 → thời cơ tổng khởi nghĩa chưa chín muồi.", "topic": "1944–1945 · Cách mạng Tháng Tám", "extra": false, "review": false, "tier": 7, "sources": [], "hint": "Nhật–Pháp xung đột tạo cơ hội nhưng chưa đủ mọi điều kiện để giành chính quyền toàn quốc."}, {"chapter": 1, "number": 87, "id": "415505809", "question": "“Giờ quyết định cho vận mệnh dân tộc ta đã đến. Toàn quốc đồng bào hãy đứng dậy đem sức ta mà tự giải phóng cho ta” là câu nói của ai?", "options": ["Võ Nguyên Giáp", "Phạm Văn Đồng", "Trường Chinh", "Hồ Chí Minh"], "answer": "D", "key": "1.87", "explanation": "Đem sức ta tự giải phóng cho ta → Hồ Chí Minh kêu gọi tự lực.", "topic": "1944–1945 · Cách mạng Tháng Tám", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Câu nói nhấn mạnh tự lực giải phóng và lời hiệu triệu toàn dân của lãnh tụ cách mạng."}, {"chapter": 1, "number": 88, "id": "415505810", "question": "Hội nghị Toàn quốc từ ngày 14 đến 15/8/1945 quyết định phát động toàn dân nổi dậy tổng khởi nghĩa giành chính quyền khi nào?", "options": ["Khi quân Đồng minh kéo vào Đông Dương đánh Nhật", "Khi Nhật đầu hàng Đồng minh", "Sau khi quân Đồng minh kéo vào Đông Dương", "Trước khi quân Đồng minh kéo vào Đông Dương"], "answer": "D", "key": "1.88", "explanation": "Chớp thời cơ → giành chính quyền trước khi Đồng minh vào Đông Dương.", "topic": "1944–1945 · Cách mạng Tháng Tám", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Thời cơ có giới hạn: cần hành động trước khi một lực lượng bên ngoài vào giải giáp Nhật."}, {"chapter": 1, "number": 89, "id": "415505811", "question": "Hội nghị toàn quốc của Đảng (14-15/8/1945) họp tại Tân Trào đã xác định ba nguyên tắc chỉ đạo khởi nghĩa là?", "options": ["Thần tốc, táo bạo, kịp thời", "Đánh nhanh, thắng nhanh, táo bạo", "Tập trung, thống nhất, kịp thời", "Đánh chắc, tiến chắc, thần tốc"], "answer": "C", "key": "1.89", "explanation": "Ba nguyên tắc → tập trung – thống nhất – kịp thời.", "topic": "1944–1945 · Cách mạng Tháng Tám", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Ba nguyên tắc nói về sự điều hành thống nhất và tốc độ hành động khi thời cơ đến."}, {"chapter": 1, "number": 90, "id": "415505812", "question": "Đại hội Quốc dân Tân Trào (16/8/1945) gồm những đại biểu thuộc các thành phần và các miền nào?", "options": ["Ba xứ thuộc đủ các giới, các đảng phái chính trị, các đoàn thể quần chúng, dân tộc, tôn giáo trong nước và đại biểu nước ngoài", "Giai cấp công nhân, nông dân cả nước", "Giai cấp tiểu tư sản, học sinh, sinh viên, trí thức cả nước", "Các đảng phái, đoàn thể tổ chức mặt trận trong cả nước"], "answer": "A", "key": "1.90", "explanation": "Quốc dân Đại hội → đại biểu nhiều giới, nhiều miền, dân tộc và tôn giáo.", "topic": "1944–1945 · Cách mạng Tháng Tám", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Quốc dân Đại hội mang tính đại diện rộng rãi, không giới hạn một giai cấp hay một miền."}, {"chapter": 1, "number": 91, "id": "415505813", "question": "Trong cách mạng Tháng Tám, thời cơ giành chính quyền chỉ tồn tại trong khoảng thời gian?", "options": ["Từ khi Nhật đảo chính Pháp đến khi Nhật đầu hàng Đồng minh vô điều kiện", "Từ khi Nhật đảo chính Pháp đến trước khi quân Đồng minh vào Đông Dương giải giáp quân đội Nhật", "Từ khi Nhật đầu hàng Đồng minh vô điều kiện đến trước khi quân Đồng minh vào Đông Dương giải giáp quân đội Nhật.", "Từ khi Nhật đầu hàng Đồng minh vô điều kiện đến trước khi Pháp quay trở lại xâm lược Việt Nam lần thứ hai"], "answer": "C", "key": "1.91", "explanation": "Cửa sổ thời cơ → Nhật đầu hàng, Đồng minh chưa vào.", "topic": "1944–1945 · Cách mạng Tháng Tám", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Xác định hai đầu thời cơ: Nhật mất khả năng thống trị và quân Đồng minh chưa tiến vào."}, {"chapter": 1, "number": 92, "id": "415505814", "question": "Cách mạng Tháng Tám chĩa mũi nhọn tấn công vào kẻ thù nào?", "options": ["Pháp - Nhật", "Pháp - Nhật và chế độ phong kiến", "Chế độ phong kiến", "Phát xít Nhật"], "answer": "D", "key": "1.92", "explanation": "Tháng Tám 1945 → chính quyền phát xít Nhật và tay sai là mục tiêu trực tiếp.", "topic": "1944–1945 · Cách mạng Tháng Tám", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Chú ý kẻ thù trực tiếp đang nắm chính quyền sau cuộc đảo chính tháng 3."}, {"chapter": 1, "number": 93, "id": "415505815", "question": "Cách mạng Tháng Tám 1945 thành công ở Hà Nội vào thời gian nào?", "options": ["19/8/1945", "23/8/1945", "25/8/1945", "2/9/1945"], "answer": "A", "key": "1.93", "explanation": "Hà Nội → 19/8/1945; đừng nhầm Huế 23/8, Sài Gòn 25/8.", "topic": "1944–1945 · Cách mạng Tháng Tám", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Nhớ chuỗi Hà Nội → Huế → Sài Gòn trong tháng 8; Hà Nội giành chính quyền trước."}, {"chapter": 1, "number": 94, "id": "415505816", "question": "Thắng lợi của cuộc khởi nghĩa ở Hà Nội (19/8/1945) đã có ý nghĩa như thế nào?", "options": ["Cổ vũ mạnh mẽ phong trào cách mạng cả nước", "Làm cho chính quyền tay sai của Nhật ở nhiều nơi thêm hoảng hốt", "Tạo thuận lợi lớn cho quá trình tổng khởi nghĩa", "Tất cả ba đáp án trên"], "answer": "D", "key": "1.94", "explanation": "Hà Nội thắng → cổ vũ cả nước, làm tay sai hoảng loạn, thúc đẩy tổng khởi nghĩa.", "topic": "1944–1945 · Cách mạng Tháng Tám", "extra": false, "review": false, "tier": 7, "sources": [], "hint": "Xét đồng thời tác động tinh thần, tác động tới tay sai và sự lan rộng của khởi nghĩa."}, {"chapter": 1, "number": 95, "id": "415505817", "question": "Ngày 30/8/1945 ghi dấu sự kiện lịch sử gì của dân tộc Việt Nam?", "options": ["Vua Bảo Đại thoái vị", "Cách mạng Tháng Tám thành công", "Tổng khởi nghĩa giành chính quyền ở Sài Gòn", "Tổng khởi nghĩa giành chính quyền ở Hà Nội"], "answer": "A", "key": "1.95", "explanation": "30/8/1945 → Bảo Đại thoái vị, kết thúc chế độ quân chủ.", "topic": "1944–1945 · Cách mạng Tháng Tám", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Đây là sự kiện kết thúc chế độ quân chủ, diễn ra trước Tuyên ngôn Độc lập."}, {"chapter": 1, "number": 96, "id": "415505818", "question": "Trong thời gian bao lâu, tổng khởi nghĩa Cách mạng Tháng Tám 1945 giành được chính quyền?", "options": ["10 ngày", "15 ngày", "20 ngày", "25 ngày"], "answer": "B", "key": "1.96", "explanation": "Theo tài liệu → khoảng 15 ngày; cần thống nhất cách tính mốc với giảng viên.", "topic": "1944–1945 · Cách mạng Tháng Tám", "extra": false, "review": true, "tier": 8, "sources": [], "hint": "Nhớ cuộc tổng khởi nghĩa diễn ra rất nhanh trong nửa cuối tháng 8; đọc lưu ý cách tính mốc."}, {"chapter": 1, "number": 97, "id": "415505819", "question": "Nhân tố chủ yếu nhất quyết định thắng lợi của Cách mạng Tháng Tám năm 1945?", "options": ["Mâu thuẫn dân tộc gay gắt", "Sức mạnh của liên minh công nông", "Sự lãnh đạo của Đảng", "Bối cảnh quốc tế thuận lợi"], "answer": "C", "key": "1.97", "explanation": "Nhân tố quyết định → sự lãnh đạo của Đảng, tổ chức và chớp thời cơ.", "topic": "1944–1945 · Cách mạng Tháng Tám", "extra": false, "review": false, "tier": 7, "sources": [], "hint": "Phân biệt nhân tố lãnh đạo, tổ chức quyết định với những điều kiện thuận lợi khách quan."}, {"chapter": 1, "number": 98, "id": "415505820", "question": "Phương pháp đấu tranh chủ yếu trong Cách mạng tháng Tám năm 1945 ở Việt Nam là gì?", "options": ["Đấu tranh chính trị", "Đấu tranh vũ trang", "Đấu tranh ngoại giao", "Đấu tranh cải lương, thỏa hiệp"], "answer": "B", "key": "1.98", "explanation": "Đáp án nguồn B cần đối chiếu: tổng khởi nghĩa kết hợp chính trị và vũ trang; không nên học giản lược thành chỉ vũ trang.", "topic": "1944–1945 · Cách mạng Tháng Tám", "extra": false, "review": true, "tier": 8, "sources": [{"label": "QĐND · phối hợp chính trị và vũ trang", "url": "https://www.qdnd.vn/80-nam-cach-mang-thang-tam-va-quoc-khanh-2-9/tong-khoi-nghia-thang-tam-nam-1945-va-bai-hoc-ve-xay-dung-the-tran-long-dan-hien-nay-842321"}], "hint": "Đề có nghi vấn: phân biệt hình thức khởi nghĩa với vai trò của lực lượng chính trị và vũ trang."}, {"chapter": 1, "number": 99, "id": "415505821", "question": "Nội dung nào sau đây không phải là ý nghĩa của Cách mạng Tháng Tám năm 1945?", "options": ["Phá tan xiềng xích nô lệ của Pháp - Nhật và phong kiến, đem lại độc lập tự do cho dân tộc", "Mở ra một kỉ nguyên mới trong lịch sử dân tộc: độc lập dân tộc gắn liền với CNXH", "Đã góp phần làm phong phú thêm kho tàng lý luận của chủ nghĩa Mác - Lênin", "Chấm dứt sự tồn tại của chế độ quân chủ chuyên chế hàng nghìn năm, lập nên nước Việt Nam Dân chủ Cộng hòa"], "answer": "B", "key": "1.99", "explanation": "Nguồn chọn B nhưng cách diễn đạt này cũng xuất hiện trong tài liệu chính thống về ý nghĩa Cách mạng Tháng Tám. Chưa có phương án sai rõ ràng; nên hỏi giảng viên, không học máy móc đáp án B.", "topic": "1944–1945 · Cách mạng Tháng Tám", "extra": false, "review": true, "tier": 8, "sources": [{"label": "Báo Chính phủ · ý nghĩa Cách mạng Tháng Tám", "url": "https://baochinhphu.vn/cach-mang-thang-tam-bai-hoc-lich-su-gia-tri-tuong-lai-102169685.htm"}], "hint": "Câu phủ định có vấn đề: so ý nghĩa mở ra thời đại mới với việc hoàn thành xây dựng chế độ mới."}, {"chapter": 1, "number": 100, "id": "415505822", "question": "Luận điểm nào sau đây không phải là ý nghĩa đối với quốc tế của Cách mạng Tháng Tám năm 1945?", "options": ["Cách mạng Tháng Tám mở ra kỷ nguyên mới trong tiến trình lịch sử dân tộc, kỷ nguyên độc lập, tự do và hướng tới CNXH", "Cách mạng Tháng Tám không chỉ là chiến công của dân tộc Việt Nam mà còn là chiến công chung của các dân tộc thuộc địa đang đấu tranh vì độc lập tự do", "Cách mạng Tháng Tám chứng tỏ cuộc cách mạng giải phóng dân tộc ở một nước thuộc địa do Đảng cộng sản lãnh đạo hoàn toàn có khả năng giành thắng lợi trước cuộc đấu tranh của giai cấp công nhân ở chính quốc", "Cách mạng Tháng Tám đã góp phần làm phong phú thêm kho tàng lý luận của chủ nghĩa Mác - Lênin về cách mạng giải phóng dân tộc"], "answer": "A", "key": "1.100", "explanation": "Câu hỏi về QUỐC TẾ: kỷ nguyên mới của dân tộc là ý nghĩa trong nước.", "topic": "1944–1945 · Cách mạng Tháng Tám", "extra": false, "review": false, "tier": 8, "sources": [], "hint": "Đề hỏi ý nghĩa QUỐC TẾ; tìm phương án chỉ mô tả tác động trong phạm vi dân tộc."}, {"chapter": 1, "number": 101, "id": "415505823", "question": "Thắng lợi của Cách mạng Tháng Tám đã giải quyết thành công vấn đề cơ bản của một cuộc cách mạng xã hội là:", "options": ["Vấn đề chính quyền", "Vấn đề ruộng đất", "Vấn đề xóa bỏ áp bức, bất công", "Vấn đề dân sinh, dân chủ"], "answer": "A", "key": "1.101", "explanation": "Vấn đề cơ bản của cách mạng xã hội → giành chính quyền nhà nước.", "topic": "1944–1945 · Cách mạng Tháng Tám", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Mọi cuộc cách mạng xã hội phải giải quyết vấn đề quyền lực thuộc về ai."}, {"chapter": 1, "number": 102, "id": "415505824", "question": "Thắng lợi của Cách mạng Tháng Tám năm 1945 chỉ ra trong cách mạng thuộc địa phải đặt nhiệm vụ nào lên hàng đầu?", "options": ["Nhiệm vụ giải phóng dân tộc", "Nhiệm vụ cách mạng ruộng đất", "Nhiệm vụ đánh đổ chế độ quân chủ chuyên chế", "Nhiệm vụ đấu tranh đòi dân sinh, dân chủ, cải thiện đời sống nhân dân"], "answer": "A", "key": "1.102", "explanation": "Cách mạng thuộc địa → đặt giải phóng dân tộc lên hàng đầu.", "topic": "1944–1945 · Cách mạng Tháng Tám", "extra": false, "review": false, "tier": 7, "sources": [], "hint": "Ở thuộc địa, nhiệm vụ sống còn nào cần ưu tiên để tập hợp toàn thể dân tộc?"}, {"chapter": 1, "number": 103, "id": "415505825", "question": "Mặt trận nào sau đây là điển hình thành công của Đảng về huy động lực lượng toàn dân tộc lên trận địa cách mạng, đưa cả dân tộc vùng lên đấu tranh giành chính quyền thành công?", "options": ["Mặt trận nhân dân phản đế Đông Dương", "Mặt trận dân tộc thống nhất phản đế Đông Dương", "Mặt trận Việt Nam độc lập đồng minh", "Mặt trận Tổ quốc Việt Nam"], "answer": "C", "key": "1.103", "explanation": "Việt Minh → đoàn kết toàn dân, huy động lực lượng giành chính quyền.", "topic": "1944–1945 · Cách mạng Tháng Tám", "extra": false, "review": false, "tier": 7, "sources": [], "hint": "Tìm mặt trận được thành lập năm 1941, quy tụ các hội Cứu quốc."}, {"chapter": 2, "number": 1, "id": "415507617", "question": "Thuận lợi cơ bản nhất của nước Việt Nam Dân chủ Cộng hòa sau Cách mạng Tháng Tám năm 1945 là:", "options": ["Việt Nam trở thành quốc gia độc lập, tự do và xây dựng được chính quyền của riêng mình", "Nhân dân Việt Nam từ thân phận nô lệ, bị áp bức trở thành chủ nhân của chế độ dân chủ mới", "Đảng Cộng sản trở thành Đảng cầm quyền lãnh đạo cách mạng trong cả nước", "Nhân dân đoàn kết, tin tưởng vào sự lãnh đạo của Đảng, của Chủ tịch Hồ Chí Minh"], "answer": "A", "key": "2.1", "explanation": "Sau Tháng Tám → đã có độc lập và chính quyền của nhân dân, nền tảng để vượt khó.", "topic": "1945–1946 · Bảo vệ chính quyền", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Phân biệt nền tảng thuận lợi căn bản sau cách mạng với sự hỗ trợ từ bên ngoài."}, {"chapter": 2, "number": 2, "id": "415507618", "question": "Hãy điền đáp án đúng vào chỗ … trong câu sau: Sau khi Cách mạng Tháng Tám thành công, Chủ tịch Hồ Chí Minh đã trở thành … của nền độc lập, tự do, là trung tâm của khối đại đoàn kết toàn dân tộc Việt Nam.", "options": ["Tượng đài", "Biểu tượng", "Tấm gương", "Tất cả các đáp án trên"], "answer": "B", "key": "2.2", "explanation": "Hồ Chí Minh → biểu tượng độc lập, trung tâm đoàn kết toàn dân.", "topic": "1945–1946 · Bảo vệ chính quyền", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Cần một từ nói về hình ảnh đại diện tinh thần cho nền độc lập và sự đoàn kết."}, {"chapter": 2, "number": 3, "id": "415507619", "question": "Nội dung nào sau đây không phải là tình hình thuận lợi của Việt Nam sau Cách mạng Tháng Tám?", "options": ["Việt Nam trở thành quốc gia độc lập, tự do", "Nhân dân Việt Nam từ thân phận nô lệ, bị áp bức trở thành chủ nhân của chế độ dân chủ mới", "Đảng Cộng sản trở thành Đảng cầm quyền lãnh đạo cách mạng trong cả nước", "Liên Xô ủng hộ lập trường độc lập của Việt Nam"], "answer": "D", "key": "2.3", "explanation": "Câu phủ định: khi mới thành lập, Việt Nam chưa được nước lớn công nhận chính thức.", "topic": "1945–1946 · Bảo vệ chính quyền", "extra": false, "review": false, "tier": 8, "sources": [], "hint": "Câu phủ định: kiểm tra tình trạng công nhận ngoại giao của chính quyền vừa ra đời."}, {"chapter": 2, "number": 4, "id": "415507620", "question": "Nhiệm vụ quan trọng nhất của Nhà nước Việt Nam Dân chủ Cộng hoà sau khi Cách mạng Tháng Tám thành công là gì?", "options": ["Tiếp nhận chính quyền cách mạng từ tay quân đội Đồng Minh", "Tổ chức cuộc kháng chiến chống thực dân Pháp xâm lược ở Nam Bộ", "Giải quyết những khó khăn về nạn đói, nạn dốt, nạn ngoại xâm", "Xây dựng chế độ mới và chính quyền cách mạng"], "answer": "D", "key": "2.4", "explanation": "Chính quyền còn non trẻ → ưu tiên xây dựng, củng cố chế độ mới.", "topic": "1945–1946 · Bảo vệ chính quyền", "extra": false, "review": false, "tier": 7, "sources": [], "hint": "Quyền lực mới còn non trẻ; cần ưu tiên việc bảo đảm nhà nước cách mạng tồn tại."}, {"chapter": 2, "number": 5, "id": "415507621", "question": "Theo thỏa thuận của Hiệp ước Potsdam (Đức), việc giải giáp quân đội Nhật thua trận ở Bắc vĩ tuyến 16 Việt Nam do đội quân nào thực hiện?", "options": ["Quân Tưởng Giới Thạch", "Quân Pháp", "Quân Anh", "Quân Anh và quân Pháp"], "answer": "A", "key": "2.5", "explanation": "Bắc vĩ tuyến 16 → quân Tưởng vào giải giáp Nhật.", "topic": "1945–1946 · Bảo vệ chính quyền", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Nhớ sự phân công quân Đồng minh: miền Bắc do lực lượng từ Trung Quốc tiến vào."}, {"chapter": 2, "number": 6, "id": "415507622", "question": "Theo thỏa thuận của Hiệp ước Potsdam (Đức), việc giải giáp quân đội Nhật thua trận ở Nam vĩ tuyến 16 Việt Nam do đội quân nào thực hiện?", "options": ["Quân Tưởng Giới Thạch", "Quân Pháp", "Quân Anh và quân Pháp", "Quân Anh"], "answer": "D", "key": "2.6", "explanation": "Nam vĩ tuyến 16 → quân Anh vào giải giáp Nhật.", "topic": "1945–1946 · Bảo vệ chính quyền", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Nhớ sự phân công quân Đồng minh: miền Nam do lực lượng của một nước châu Âu tiến vào."}, {"chapter": 2, "number": 7, "id": "415507623", "question": "Sau khi Cách mạng Tháng Tám thành công, trên đất nước Việt Nam, ngoài lực lượng quân đội Đồng minh vào giải giáp quân đội Nhật còn có bao nhiêu vạn quân Nhật chưa được giải giáp?", "options": ["5 vạn quân", "6 vạn quân", "7 vạn quân", "8 vạn quân"], "answer": "B", "key": "2.7", "explanation": "Theo số liệu tài liệu → 6 vạn quân Nhật còn chờ giải giáp.", "topic": "1945–1946 · Bảo vệ chính quyền", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Đây là số quân Nhật còn trên đất Việt Nam, không phải số quân Tưởng kéo vào."}, {"chapter": 2, "number": 8, "id": "415507624", "question": "“Diệt Cộng, cầm Hồ” là âm mưu thâm độc của lực lượng ngoại xâm nào?", "options": ["Quân Tưởng Giới Thạch và tay sai", "Quân Pháp và tay sai", "Quân Anh", "Quân Nhật"], "answer": "A", "key": "2.8", "explanation": "Diệt Cộng, cầm Hồ → âm mưu của Tưởng và tay sai.", "topic": "1945–1946 · Bảo vệ chính quyền", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Khẩu hiệu này gắn với lực lượng từ phía Bắc vào giải giáp Nhật và các đảng phái thân họ."}, {"chapter": 2, "number": 9, "id": "415507625", "question": "Địa vị pháp lý của nước Việt Nam Dân chủ Cộng hòa khi mới thành lập trong quan hệ ngoại giao là:", "options": ["Được Liên Xô công nhận", "Được Trung Quốc công nhận", "Được Mỹ công nhận", "Không có nước lớn nào công nhận"], "answer": "D", "key": "2.9", "explanation": "Nhà nước mới → chưa được nước lớn công nhận về ngoại giao.", "topic": "1945–1946 · Bảo vệ chính quyền", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Phân biệt Việt Nam tự tuyên bố độc lập với việc các nước lớn chính thức công nhận."}, {"chapter": 2, "number": 10, "id": "415507626", "question": "Để khẳng định địa vị pháp lý của Nhà nước Việt Nam Dân chủ Cộng hoà, Đảng và Chủ tịch Hồ Chí Minh đã chủ trương cần phải giải quyết ngay nhiệm vụ nào?", "options": ["Diệt giặc đói, giặc dốt, giặc ngoại xâm", "Sớm tổ chức một cuộc bầu cử toàn quốc theo hình thức phổ thông đầu phiếu", "Thiết lập quan hệ với các nước Đồng Minh", "Thiết lập quan hệ với Liên Xô và các nước xã hội chủ nghĩa"], "answer": "B", "key": "2.10", "explanation": "Tổng tuyển cử → tạo cơ sở pháp lý, khẳng định chính quyền của nhân dân.", "topic": "1945–1946 · Bảo vệ chính quyền", "extra": false, "review": false, "tier": 7, "sources": [], "hint": "Cơ sở pháp lý của chính quyền dân chủ cần được nhân dân xác nhận qua lá phiếu."}, {"chapter": 2, "number": 11, "id": "415507627", "question": "Ngày 3/9/1945, Chính phủ lâm thời họp phiên đầu tiên đã đề ra những nhiệm vụ cấp bách của chính quyền cách mạng và xác định nhiệm vụ lớn là?", "options": ["Diệt giặc đói", "Diệt giặc dốt", "Diệt giặc ngoại xâm", "Diệt giặc đói, giặc dốt, giặc ngoại xâm"], "answer": "D", "key": "2.11", "explanation": "Ba giặc → đói – dốt – ngoại xâm; nhớ bộ ba sau 1945.", "topic": "1945–1946 · Bảo vệ chính quyền", "extra": false, "review": false, "tier": 7, "sources": [], "hint": "Nhớ ba nguy cơ tác động đồng thời tới đời sống, học vấn và chủ quyền."}, {"chapter": 2, "number": 12, "id": "415507628", "question": "Ngay sau khi Cách mạng Tháng Tám thành công, chính quyền cách mạng vừa mới được thiết lập đã phải đối mặt với khó khăn lớn nhất về tài chính là?", "options": ["Chính quyền cách mạng chưa kiểm soát được ngân hàng Đông Dương", "Đồng bạc Đông dương mất giá", "Ngân khố cạn kiệt, kho bạc trống rỗng", "Chưa phát hành được đồng tiền của chính quyền mới"], "answer": "C", "key": "2.12", "explanation": "Tài chính → ngân khố trống rỗng, cần huy động nguồn lực nhân dân.", "topic": "1945–1946 · Bảo vệ chính quyền", "extra": false, "review": false, "tier": 7, "sources": [], "hint": "Xét số tiền, tài sản sẵn có trong ngân khố, không chỉ năng lực sản xuất lâu dài."}, {"chapter": 2, "number": 13, "id": "415507629", "question": "Sau khi Cách mạng Tháng Tám thành công, chính quyền cách mạng vừa mới được thiết lập phải đối mặt với hậu quả của chế độ cũ để lại là:", "options": ["Chưa có nước nào công nhận nền độc lập của nước ta", "Các nước Đồng minh vào giải giáp vũ khí quân đội phát xít", "95% dân số thất học, mù chữ", "Việt Nam hoàn toàn bị cô lập"], "answer": "C", "key": "2.13", "explanation": "Giặc dốt → tỷ lệ mù chữ rất cao; nguồn ghi 95%.", "topic": "1945–1946 · Bảo vệ chính quyền", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Đây là hậu quả về trình độ học vấn của dân cư dưới chế độ cũ."}, {"chapter": 2, "number": 14, "id": "415507630", "question": "Sau khi Cách mạng Tháng Tám thành công, chính quyền cách mạng vừa mới được thiết lập có quan hệ đối ngoại là:", "options": ["Chưa có nước nào trên thế giới công nhận Việt Nam độc lập", "Các nước Đồng minh công nhận Việt Nam độc lập", "Các nước xã hội chủ nghĩa công nhận Việt Nam độc lập", "Liên Xô và các nước Đông Âu công nhận Việt Nam độc lập"], "answer": "A", "key": "2.14", "explanation": "Đối ngoại buổi đầu → chưa có sự công nhận độc lập từ nước ngoài.", "topic": "1945–1946 · Bảo vệ chính quyền", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Phân biệt sự ủng hộ tinh thần với quan hệ công nhận ngoại giao chính thức."}, {"chapter": 2, "number": 15, "id": "415507631", "question": "Sau ngày 2/9/1945, đất nước ta lâm vào tình thế “ngàn cân treo sợi tóc”, khó khăn nào dưới đây là lớn nhất?", "options": ["Chính quyền cách mạng mới được thành lập còn non trẻ, yếu kém về nhiều mặt", "Việt Nam phải cùng lúc đối phó với nhiều thế lực thù địch cả trong và ngoài nước", "Nền kinh tế xơ xác, tài chính rối ren", "Không có nước nào công nhận địa vị pháp lý của Nhà nước Việt Nam Dân chủ Cộng hòa"], "answer": "B", "key": "2.15", "explanation": "Nguy cơ lớn → thù trong giặc ngoài cùng đe dọa chính quyền non trẻ.", "topic": "1945–1946 · Bảo vệ chính quyền", "extra": false, "review": false, "tier": 7, "sources": [], "hint": "Khó khăn lớn nhất đe dọa trực tiếp sự tồn tại chính quyền mới, từ cả trong và ngoài."}, {"chapter": 2, "number": 16, "id": "415507632", "question": "Những biện pháp trước mắt để chống nạn đói, đẩy lùi nạn đói mà Đảng, Chính phủ và Chủ tịch Hồ Chí Minh tập trung chỉ đạo, động viên mọi tầng lớp nhân dân tham gia sau khi chính quyền cách mạng được thành lập là?", "options": ["Khai hoang, mở rộng diện tích đất nông nghiệp", "Chia ruộng đất cho dân cày nghèo", "Tăng gia sản xuất, lập hũ gạo tiết kiệm", "Tất cả các đáp án trên"], "answer": "C", "key": "2.16", "explanation": "Cứu đói → hũ gạo tiết kiệm hỗ trợ ngay; tăng gia sản xuất giải quyết bền vững.", "topic": "1945–1946 · Bảo vệ chính quyền", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Tìm biện pháp vừa chia sẻ lương thực trước mắt vừa tăng nguồn cung thực tế."}, {"chapter": 2, "number": 17, "id": "415507633", "question": "Chống giặc dốt, xoá nạn mù chữ được Đảng và Chủ tịch Hồ Chí Minh đặc biệt coi trọng, thông qua phát động phong trào nào?", "options": ["Tăng gia sản xuất, lập hũ gạo tiết kiệm, tổ chức “Tuần lễ vàng”", "Giáo dục lại tinh thần nhân dân bằng Cần, Kiệm, Liêm, Chính", "Toàn dân học chữ quốc ngữ (Bình dân học vụ)", "Toàn dân diệt giặc đói, giặc dốt, giặc ngoại xâm"], "answer": "C", "key": "2.17", "explanation": "Giặc dốt → Bình dân học vụ, học chữ quốc ngữ.", "topic": "1945–1946 · Bảo vệ chính quyền", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Phong trào này giúp người dân đọc, viết chữ quốc ngữ sau ngày độc lập."}, {"chapter": 2, "number": 18, "id": "415507634", "question": "“Thà chết tự do còn hơn sống nô lệ” là tinh thần đấu tranh của nhân dân các tỉnh nào trong cả nước khi đứng lên kháng chiến chống thực dân Pháp sau ngày 23/9/1945?", "options": ["Nhân dân các tỉnh Nam Bộ", "Nhân dân các tỉnh Nam Trung bộ", "Nhân dân các tỉnh Đông Nam bộ", "Nhân dân các tỉnh Tây Nam bộ"], "answer": "A", "key": "2.18", "explanation": "23/9/1945 → Nam Bộ đứng lên chống Pháp trở lại.", "topic": "1945–1946 · Bảo vệ chính quyền", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Gắn ngày 23/9 với địa bàn Pháp trở lại đánh chiếm đầu tiên sau cách mạng."}, {"chapter": 2, "number": 19, "id": "415507635", "question": "“Thành đồng Tổ quốc” là danh hiệu mà Chủ tịch Hồ Chí Minh gửi tặng đồng bào các tỉnh nào ngay sau khi thực dân Pháp quay trở lại xâm lược nước ta lần thứ hai?", "options": ["Đồng bào Nam Trung bộ", "Đồng bào Nam Bộ", "Đồng bào Tây Nam bộ", "Đồng bào Đông Nam bộ"], "answer": "B", "key": "2.19", "explanation": "Nam Bộ kháng chiến → danh hiệu Thành đồng Tổ quốc.", "topic": "1945–1946 · Bảo vệ chính quyền", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Danh hiệu gắn với miền đi đầu kháng chiến chống Pháp trở lại."}, {"chapter": 2, "number": 20, "id": "415507636", "question": "Chỉ thị “Kháng chiến kiến quốc” ngày 25/11/1945 của Ban Chấp hành Trung ương Đảng xác định mục tiêu phải nêu cao của CMVN là:", "options": ["Dân tộc giải phóng", "Bảo vệ thành quả của Cách mạng Tháng Tám", "Đập tan âm mưu xâm lược của thực dân Pháp", "Chống Pháp ở Nam Bộ, chống quân đội Tưởng Giới Thạch ở miền Bắc"], "answer": "A", "key": "2.20", "explanation": "Kháng chiến kiến quốc → nêu cao mục tiêu dân tộc giải phóng.", "topic": "1945–1946 · Bảo vệ chính quyền", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Chỉ thị vẫn đặt nhiệm vụ bảo vệ độc lập lên trên các mục tiêu khác."}, {"chapter": 2, "number": 21, "id": "415507637", "question": "Chỉ thị “Kháng chiến kiến quốc” ngày 25/11/1945 của Ban chấp hành Trung ương Đảng xác định nhiệm vụ nào là trung tâm, bao trùm của CMVN?", "options": ["Củng cố chính quyền cách mạng", "Chống thực dân Pháp xâm lược", "Bài trừ nội phản", "Cải thiện đời sống cho nhân dân"], "answer": "A", "key": "2.21", "explanation": "Nhiệm vụ trung tâm sau giành độc lập → củng cố chính quyền cách mạng.", "topic": "1945–1946 · Bảo vệ chính quyền", "extra": false, "review": false, "tier": 7, "sources": [], "hint": "Đã giành chính quyền thì nhiệm vụ bao trùm là giữ và làm vững chính quyền ấy."}, {"chapter": 2, "number": 22, "id": "415507638", "question": "Chỉ thị “Kháng chiến kiến quốc” ngày 25/11/1945 của Ban Chấp hành Trung ương Đảng xác định biện pháp về mặt ngoại giao của chính quyền mới là:", "options": ["Hòa với Tưởng để đánh Pháp ở miền Nam", "Làm cho nước mình ít kẻ thù và nhiều bạn đồng minh hơn hết", "Hoà với Pháp để đuổi Tưởng về nước", "Bắt tay với cả Tưởng và Pháp để giữ hoà bình"], "answer": "B", "key": "2.22", "explanation": "Ngoại giao → thêm bạn, bớt thù để bảo vệ chính quyền.", "topic": "1945–1946 · Bảo vệ chính quyền", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Nghĩ tới cách giảm số đối thủ phải đối phó cùng lúc và mở rộng sự ủng hộ."}, {"chapter": 2, "number": 23, "id": "415507639", "question": "Những quan điểm và chủ trương, biện pháp lớn được Đảng nêu ra trong bản Chỉ thị Kháng chiến kiến quốc ngày 25/11/1945 đã đáp ứng yêu cầu gì của cách mạng Việt Nam?", "options": ["Quan trọng", "Cấp bách", "Chủ yếu", "Trọng tâm"], "answer": "B", "key": "2.23", "explanation": "25/11/1945 → chỉ thị đáp ứng yêu cầu cấp bách của chính quyền mới.", "topic": "1945–1946 · Bảo vệ chính quyền", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Đặt chỉ thị trong tình thế chính quyền non trẻ đang bị nhiều nguy cơ đe dọa."}, {"chapter": 2, "number": 24, "id": "415507640", "question": "Ngày 6/1/1946, có ý nghĩa như thế nào đối với nhân dân cả nước?", "options": ["Là ngày nhân dân cả nước tham gia Tuần lễ vàng, Quỹ độc lập", "Là ngày nhân dân cả nước tham gia phong trào chống nạn dốt, đẩy lùi nạn dốt", "Là ngày nhân dân cả nước tham gia cuộc bầu cử", "Là ngày nhân dân cả nước tham gia phong trào chống nạn đói, đẩy lùi nạn đói"], "answer": "C", "key": "2.24", "explanation": "6/1/1946 → Tổng tuyển cử đầu tiên bầu Quốc hội.", "topic": "1945–1946 · Bảo vệ chính quyền", "extra": false, "review": false, "tier": 7, "sources": [], "hint": "Phân biệt ngày người dân bỏ phiếu với ngày Quốc hội họp phiên đầu tiên."}, {"chapter": 2, "number": 25, "id": "415507641", "question": "Trong Bức thư gửi cho Uỷ ban nhân dân các cấp ngày 17-10-1945, Chủ tịch Hồ Chí Minh đã yêu cầu chính quyền các cấp phải khắc phục và bỏ ngay những thói hư, tật xấu gì?", "options": ["Gây chia rẽ mất đoàn kết dân tộc", "Gây chia rẽ gây mất đoàn kết trong nội bộ Đảng", "Cậy thế, hủ hoá, chia rẽ trong nội bộ", "Cậy thế, hủ hoá, tư túng, chia rẽ, kiêu ngạo"], "answer": "D", "key": "2.25", "explanation": "Chống thói xấu → cậy thế, hủ hóa, tư túng, chia rẽ, kiêu ngạo; đọc kỹ danh sách trong nguồn. Đề liệt kê 5 lỗi; bức thư gốc còn nêu cả trái phép, nên không coi đây là danh sách đầy đủ.", "topic": "1945–1946 · Bảo vệ chính quyền", "extra": false, "review": true, "tier": 8, "sources": [], "hint": "Đề hỏi thói xấu trong bộ máy: đọc kỹ danh sách, lưu ý nguồn có thể liệt kê chưa đủ."}, {"chapter": 2, "number": 26, "id": "415507642", "question": "Trong Bức thư gửi cho Uỷ ban nhân dân các cấp ngày 17-10-1945, Chủ tịch Hồ Chí Minh đã chỉ rõ các cơ quan của Chính phủ từ toàn quốc đến các làng đều phải là:", "options": ["Đầy tớ tận tâm với nhân dân", "Đầy tớ phục vụ nhân dân", "Công bộc của dân", "Nô bộc của nhân dân"], "answer": "C", "key": "2.26", "explanation": "Công bộc → người phục vụ nhân dân, không đứng trên dân.", "topic": "1945–1946 · Bảo vệ chính quyền", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Hồ Chí Minh nhấn mạnh cán bộ phải phục vụ dân, thay vì làm quan cai trị dân."}, {"chapter": 2, "number": 27, "id": "415507643", "question": "Hội Liên hiệp quốc dân Việt Nam (Liên Việt) được thành lập năm 1946 bầu ai làm Hội trưởng?", "options": ["Tôn Đức Thắng", "Vĩnh Thuỵ (tức cựu hoàng Bảo Đại)", "Hồ Chí Minh", "Huỳnh Thúc Kháng"], "answer": "D", "key": "2.27", "explanation": "Liên Việt năm 1946 → Hội trưởng Huỳnh Thúc Kháng.", "topic": "1945–1946 · Bảo vệ chính quyền", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Nhớ vị chí sĩ từng được giao quyền Chủ tịch nước khi Hồ Chí Minh sang Pháp."}, {"chapter": 2, "number": 28, "id": "415507644", "question": "Để làm thất bại âm mưu “diệt cộng, cầm Hồ”, phá Việt Minh của quân Tưởng và tay sai, Đảng, Chính phủ Hồ Chí Minh đã chủ trương thực hiện sách lược gì?", "options": ["Triệt để lợi dụng mâu thuẫn trong hàng ngũ kẻ thù", "Thực hiện giao thiệp thân thiện, ứng xử mềm dẻo, linh hoạt với các yêu sách của quân Tưởng.", "Thực hiện giao thiệp thân thiện, ứng xử mềm dẻo, linh hoạt với yêu sách của các đảng phái chính trị tay sai thân Tưởng", "Tất cả các đáp án trên"], "answer": "D", "key": "2.28", "explanation": "Đối phó Tưởng → lợi dụng mâu thuẫn, mềm dẻo giao thiệp, bảo vệ chính quyền.", "topic": "1945–1946 · Bảo vệ chính quyền", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Xem các biện pháp có bổ trợ cho nhau trong sách lược mềm dẻo, tránh cùng lúc nhiều kẻ thù không."}, {"chapter": 2, "number": 29, "id": "415507645", "question": "Ngay sau khi Cách mạng Tháng Tám thành công, chống giặc nào được coi là một “giải pháp quan trọng” để xây dựng hệ thống chính quyền cách mạng, phát huy quyền dân chủ của nhân dân?", "options": ["Chống giặc dốt, xóa nạn mù chữ", "Chống giặc đói, đẩy lùi nạn đói", "Chống thực dân Pháp xâm lược ở miền Nam", "Chống thù trong, giặc ngoài"], "answer": "A", "key": "2.29", "explanation": "Biết chữ → có điều kiện tham gia quản lý nhà nước, thực hiện dân chủ.", "topic": "1945–1946 · Bảo vệ chính quyền", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Khả năng đọc, viết giúp người dân thực hiện quyền dân chủ và tham gia quản lý."}, {"chapter": 2, "number": 30, "id": "415507646", "question": "Khi quay trở lại xâm lược Việt Nam lần thứ hai, thực dân Pháp đã thực hiện chiến lược chiến tranh nào?", "options": ["Dùng người Việt đánh người Việt", "Lấy chiến tranh nuôi chiến tranh", "Đánh nhanh, thắng nhanh", "Đánh chắc, thắng chắc"], "answer": "C", "key": "2.30", "explanation": "Pháp tái xâm lược → muốn đánh nhanh, thắng nhanh.", "topic": "1946–1947 · Toàn quốc kháng chiến", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Pháp kỳ vọng kết thúc cuộc tái xâm lược trong thời gian ngắn, trước khi ta củng cố lực lượng."}, {"chapter": 2, "number": 31, "id": "415507647", "question": "Trong đấu tranh ngoại giao với Pháp và Tưởng, từ tháng 9/1945 đến 3/1946, Đảng đưa ra chủ trương?", "options": ["Hòa với Pháp", "Hòa với Tưởng", "Hòa với Pháp và Tưởng", "Đánh cả Pháp và Tưởng"], "answer": "B", "key": "2.31", "explanation": "Trước 6/3/1946 → hòa Tưởng để tập trung chống Pháp ở Nam Bộ.", "topic": "1946–1947 · Toàn quốc kháng chiến", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Chú ý mốc TRƯỚC Hiệp định Sơ bộ: ưu tiên chống Pháp ở phía Nam."}, {"chapter": 2, "number": 32, "id": "415507648", "question": "Trong đấu tranh ngoại giao với Pháp và Tưởng, từ tháng 3/1946 đến 12/1946, Đảng đưa ra chủ trương?", "options": ["Hòa với Pháp và Tưởng", "Đánh cả Pháp và Tưởng", "Hòa với Tưởng", "Hòa với Pháp"], "answer": "D", "key": "2.32", "explanation": "Sau 6/3/1946 → hòa Pháp để đẩy quân Tưởng về nước.", "topic": "1946–1947 · Toàn quốc kháng chiến", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Chú ý mốc SAU Hiệp định Sơ bộ: thương lượng để loại bớt một lực lượng ngoại xâm phía Bắc."}, {"chapter": 2, "number": 33, "id": "415507649", "question": "Nguyên nhân chủ yếu để Chính phủ Việt Nam Dân chủ Cộng hòa quyết định tạm thời hòa hoãn với Trung Hoa Dân Quốc sau Cách mạng Tháng Tám năm 1945 là?", "options": ["Do Trung Hoa Dân Quốc vào Việt Nam dưới danh nghĩa quân Đồng Minh", "Do Việt Nam cần tập trung lực lượng để đánh Pháp ở miền Nam", "Do Trung Hoa Dân Quốc vào Việt Nam chỉ đòi các quyền lợi về kinh tế", "Do Trung Hoa Dân Quốc không thể ở lại Việt Nam lâu dài"], "answer": "B", "key": "2.33", "explanation": "Hòa Tưởng → tránh nhiều mặt trận, tập trung lực lượng chống Pháp miền Nam.", "topic": "1946–1947 · Toàn quốc kháng chiến", "extra": false, "review": false, "tier": 7, "sources": [], "hint": "Mục đích hòa hoãn là tránh phải phân tán lực lượng trên nhiều hướng đối phó."}, {"chapter": 2, "number": 34, "id": "415507650", "question": "Vì sao Đảng lại lựa chọn giải pháp thương lượng với Pháp sau khi Hiệp ước Trùng Khánh (28/2/1946) được kí kết?", "options": ["Vì Pháp lúc này rất mạnh", "Để đuổi nhanh quân Tưởng về nước", "Phối hợp với Pháp tấn công Tưởng.", "Dân tộc Việt Nam không muốn chiến tranh"], "answer": "B", "key": "2.34", "explanation": "Hòa Pháp sau Hiệp ước Hoa–Pháp → loại quân Tưởng khỏi miền Bắc.", "topic": "1946–1947 · Toàn quốc kháng chiến", "extra": false, "review": false, "tier": 7, "sources": [], "hint": "Hiệp ước Hoa–Pháp tạo nguy cơ mới; ta dùng thương lượng để đẩy một lực lượng về nước."}, {"chapter": 2, "number": 35, "id": "415507651", "question": "Hiệp ước Trùng Khánh được ký kết vào ngày 18/02/1946 giữa Chính phủ Pháp với Chính phủ Trung Hoa dân quốc bàn về vấn đề gì?", "options": ["Tưởng để Pháp đưa quân đội ra Bắc vĩ tuyến 16 làm nhiệm vụ giải giáp quân đội Nhật", "Tưởng để Pháp đưa quân đội ra Bắc vĩ tuyến 16 làm nhiệm vụ thay thế cho quân đội Nhật", "Pháp nhượng lại cho Tưởng nhiều quyền lợi quan trọng về kinh tế ở Việt Nam", "Pháp nhượng lại cho Tưởng nhiều quyền lợi quan trọng về chính trị ở Việt Nam"], "answer": "A", "key": "2.35", "explanation": "Pháp thay Tưởng ra Bắc giải giáp Nhật; đề ghi 18/2, cần sửa mốc thành 28/2/1946.", "topic": "1946–1947 · Toàn quốc kháng chiến", "extra": false, "review": true, "tier": 8, "sources": [], "hint": "Đề có sai mốc ngày: tập trung nội dung Pháp thay quân Trung Hoa Dân Quốc ở miền Bắc."}, {"chapter": 2, "number": 36, "id": "415507652", "question": "Ý nghĩa quan trọng nhất của việc thực hiện các sách lược hòa hoãn trong giai đoạn từ tháng 9/1945 đến tháng 12/1946 là:", "options": ["Ngăn chặn bước tiến của đội quân xâm lược Pháp ở Nam Bộ", "Vạch trần và làm thất bại mọi âm mưu, hoạt động chống phá cách mạng Việt Nam của các kẻ thù", "Củng cố, giữ vững và bảo vệ bộ máy chính quyền cách mạng từ Trung ương đến cơ sở và những thành quả của cuộc Cách mạng Tháng Tám", "Tạo thêm thời gian hòa bình, hòa hoãn, tranh thủ xây dựng thực lực, chuẩn bị sẵn sàng cho cuộc kháng chiến lâu dài."], "answer": "D", "key": "2.36", "explanation": "Hòa hoãn → tranh thủ thời gian xây dựng lực lượng, chuẩn bị kháng chiến lâu dài.", "topic": "1946–1947 · Toàn quốc kháng chiến", "extra": false, "review": false, "tier": 7, "sources": [], "hint": "Đề hỏi giá trị chung của hòa hoãn: thứ gì cần tranh thủ để chuẩn bị kháng chiến?"}, {"chapter": 2, "number": 37, "id": "415507653", "question": "Người đại diện cho Chính phủ Cộng hoà Pháp tại Hà Nội ký Hiệp định Sơ bộ ngày 6/3/1946 với Chính phủ Việt Nam Dân chủ Cộng hoà là ai?", "options": ["J. Xanhtơry (Jean Saiteny)", "Tướng De Castries", "Tướng Philippe Leclerc", "Tướng Etienne Valluy"], "answer": "A", "key": "2.37", "explanation": "Hiệp định Sơ bộ → đại diện Pháp Jean Sainteny; tên phiên âm trong nguồn có sai khác.", "topic": "1946–1947 · Toàn quốc kháng chiến", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Đây là đại diện Pháp ký tại Hà Nội, không phải quan chức Việt Nam hay lãnh đạo cấp cao ở Paris."}, {"chapter": 2, "number": 38, "id": "415507654", "question": "Sau khi kí Hiệp định Sơ bộ (6/3/1946) và Tạm ước (14/9/1946) với Chính phủ Việt Nam Dân chủ Cộng hòa, hành động của thực dân Pháp là:", "options": ["Thực hiện nghiêm chỉnh nội dung Hiệp định Sơ bộ và Tạm ước", "Rút quân về nước đúng kế hoạch", "Cùng với Chính phủ Việt Nam Dân chủ Cộng hòa tiếp tục đàm phán", "Leo thang các hoạt động quân sự nhằm xâm lược Việt Nam một lần nữa"], "answer": "D", "key": "2.38", "explanation": "Pháp ký nhưng tiếp tục lấn tới → tăng hoạt động quân sự, phá hòa hoãn.", "topic": "1946–1947 · Toàn quốc kháng chiến", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "So hành động thực tế của Pháp với cam kết hòa hoãn đã ký."}, {"chapter": 2, "number": 39, "id": "415507655", "question": "Ai được cử làm trưởng phái đoàn Quốc hội Việt Nam đi thăm và tham dự đàm phán chính giữa hai bên Việt - Pháp tại Hội nghị Phôngtennơblô vào tháng 9/1946?", "options": ["Hồ Chí Minh", "Phạm Văn Đồng", "Huỳnh Thúc Kháng", "Võ Nguyên Giáp"], "answer": "B", "key": "2.39", "explanation": "Nguồn chọn Phạm Văn Đồng; đề trộn phái đoàn Quốc hội với phái đoàn Chính phủ, cần đối chiếu.", "topic": "1946–1947 · Toàn quốc kháng chiến", "extra": false, "review": true, "tier": 8, "sources": [], "hint": "Phân biệt trưởng phái đoàn Chính phủ đàm phán với trưởng phái đoàn Quốc hội đi thăm Pháp."}, {"chapter": 2, "number": 40, "id": "415507656", "question": "Ai được bầu là Trưởng ban soạn thảo Hiến pháp đầu tiên của Nhà nước Việt Nam Dân chủ Cộng Hoà (11/1946)?", "options": ["Nguyễn Văn Tố", "Hồ Chí Minh", "Huỳnh Thúc Kháng", "Tôn Đức Thắng"], "answer": "B", "key": "2.40", "explanation": "Hiến pháp đầu tiên → Hồ Chí Minh đứng đầu Ban soạn thảo.", "topic": "1946–1947 · Toàn quốc kháng chiến", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Nhớ người đứng đầu Chính phủ, trực tiếp chỉ đạo xây dựng nền tảng pháp lý nhà nước mới."}, {"chapter": 2, "number": 41, "id": "415507657", "question": "Đại diện Pháp ở Hà Nội đã đơn phương cắt đứt mọi liên hệ với Chính phủ Việt Nam, đưa liên tiếp 3 tối hậu thư đòi phía Việt Nam phải thực hiện điều phi lý gì?", "options": ["Trao trụ sở Bộ Tài chính, Bộ Giao thông công chính cho Pháp", "Yêu cầu được kiểm soát mọi hoạt động của đồng bào Hà Nội ở phố Yên Ninh và Hàng Bún", "Đòi độc quyền thực thi nhiệm vụ giữ gìn an ninh, trật tự của thành phố", "Tất cả các đáp án trên"], "answer": "C", "key": "2.41", "explanation": "Tối hậu thư → Pháp đòi quyền giữ an ninh Hà Nội, đe dọa chủ quyền.", "topic": "1946–1947 · Toàn quốc kháng chiến", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Yêu sách này nhằm tước quyền giữ an ninh của chính quyền ta ngay tại thủ đô."}, {"chapter": 2, "number": 42, "id": "415507658", "question": "Trong văn bản nào dưới đây, Chủ tịch Hồ Chí Minh đã viết: “Chúng ta muốn hoà bình, chúng ta phải nhân nhượng. Nhưng chúng ta càng nhân nhượng, thực dân Pháp càng lấn tới, vì chúng quyết tâm cướp nước ta một lần nữa!…”?", "options": ["Bài viết Công việc khẩn cấp bây giờ (20/10/1946)", "Lời kêu gọi toàn quốc kháng chiến (19/12/1946)", "Thư Chủ tịch Hồ Chí Minh gửi thư cho đồng bào Nam Bộ ngày 31/5/1946 nói rõ quyết tâm kiên quyết bảo vệ độc lập, thống nhất Tổ quốc.", "Lời kêu gọi thi đua ái quốc (6/1948)"], "answer": "B", "key": "2.42", "explanation": "19/12/1946 → Lời kêu gọi toàn quốc kháng chiến.", "topic": "1946–1947 · Toàn quốc kháng chiến", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Câu trích đối lập thiện chí hòa bình của ta với hành động lấn tới của Pháp."}, {"chapter": 2, "number": 43, "id": "415507659", "question": "Đặc điểm mối quan hệ Việt - Pháp từ ngày 6/3/1946 đến trước ngày 19/12/1946 là?", "options": ["Đối đầu", "Đồng minh", "Hòa hoãn", "Thù địch"], "answer": "C", "key": "2.43", "explanation": "6/3 đến trước 19/12/1946 → quan hệ hòa hoãn nhưng căng thẳng, Pháp lấn tới.", "topic": "1946–1947 · Toàn quốc kháng chiến", "extra": false, "review": false, "tier": 7, "sources": [], "hint": "Hai bên đã ký thỏa thuận nhưng chưa giải quyết xung đột căn bản; quan hệ chưa phải đồng minh."}, {"chapter": 2, "number": 44, "id": "415507660", "question": "Đường lối kháng chiến chống thực dân Pháp của Đảng được hình thành, bổ sung, phát triển qua thực tiễn cách mạng từ năm 1945 đến 1947 có nội dung cơ bản là?", "options": ["Dựa vào sức mạnh đoàn kết toàn dân tộc", "Dựa vào sức mạnh toàn dân, tiến hành kháng chiến toàn dân, toàn diện, lâu dài, dựa vào sức mình là chính", "Dựa vào truyền thống yêu nước", "Dựa vào tinh thần đoàn kết của ba nước Đông Dương"], "answer": "B", "key": "2.44", "explanation": "Bốn ý → toàn dân – toàn diện – lâu dài – tự lực là chính.", "topic": "1946–1947 · Toàn quốc kháng chiến", "extra": false, "review": false, "tier": 8, "sources": [], "hint": "Chọn phương án đủ các yếu tố: phạm vi lực lượng, lĩnh vực, thời gian và nguồn sức mạnh."}, {"chapter": 2, "number": 45, "id": "415507661", "question": "“Mỗi người dân là một chiến sĩ, mỗi làng xã là một pháo đài, mỗi phố là một mặt trận” thể hiện tính chất nào của đường lối kháng chiến chống thực dân Pháp xâm lược?", "options": ["Tính chất toàn dân", "Tính chất toàn diện", "Tính chất lâu dài", "Tính chất dựa vào sức mình là chính"], "answer": "A", "key": "2.45", "explanation": "Mỗi người dân là chiến sĩ → toàn dân tham gia kháng chiến.", "topic": "1946–1947 · Toàn quốc kháng chiến", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Chú ý chủ thể tham gia: từ mỗi người tới từng làng, phố đều trở thành lực lượng kháng chiến."}, {"chapter": 2, "number": 46, "id": "415507662", "question": "Khi Trung ương Đảng phát động Toàn quốc kháng chiến chống thực dân Pháp, quân và dân ở Hà Nội, ở các đô thị từ Bắc vĩ tuyến 16 trở ra đã đồng loạt nổ súng. Ý nghĩa lớn nhất của các cuộc chiến đấu này là?", "options": ["Đánh phá các kho tàng hậu cần và cơ sở hạ tầng chiến tranh của địch, gây thiệt hại lớn cho chúng", "Kìm giữ chân địch không cho chúng mở rộng địa bàn chiếm đóng ra các vùng xung quanh thành phố, thị xã, thị trấn.", "Ta tiếp tục phát triển lực lượng, huy động, di chuyển nhân tài, vật lực lên các khu căn cứ địa, chuẩn bị cho cuộc kháng chiến lâu dài.", "Bước đầu làm thất bại kế hoạch “đánh nhanh thắng nhanh” của thực dân Pháp"], "answer": "D", "key": "2.46", "explanation": "Đô thị chiến đấu → giam chân địch, bước đầu phá kế hoạch đánh nhanh.", "topic": "1946–1947 · Toàn quốc kháng chiến", "extra": false, "review": false, "tier": 7, "sources": [], "hint": "Phân biệt bước đầu phá ý đồ chiến lược ở đô thị với đánh bại hoàn toàn ở Việt Bắc."}, {"chapter": 2, "number": 47, "id": "415507663", "question": "Khi cuộc kháng chiến toàn quốc chống thực dân Pháp bùng nổ, sự chiến đấu của quân và dân địa phương nào là điển hình cho tinh thần “Quyết tử cho Tổ quốc quyết sinh”?", "options": ["Hà Nội", "Sài Gòn", "Đà Nẵng", "Quảng Nam"], "answer": "A", "key": "2.47", "explanation": "Hà Nội → Quyết tử cho Tổ quốc quyết sinh.", "topic": "1946–1947 · Toàn quốc kháng chiến", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Khẩu hiệu gắn với cuộc chiến đấu bảo vệ thủ đô trong những ngày đầu toàn quốc kháng chiến."}, {"chapter": 2, "number": 48, "id": "415507664", "question": "Cuộc chiến đấu 60 ngày đêm của quân và dân Hà Nội từ ngày 19/12/1946 đến 17/2/1947 có ý nghĩa quan trọng nhất là?", "options": ["Giam chân địch trong thành phố, không cho chúng mở rộng vùng chiến tranh", "Đánh tiêu hao nhiều sinh lực địch", "Bảo vệ an toàn các cơ quan đầu não, lãnh đạo của Trung ương và nhân dân rút ra ngoại thành, từ đó tiếp tục di chuyển lên các khu căn cứ địa", "Góp phần làm thất bại kế hoạch đánh nhanh, thắng nhanh của thực dân Pháp, đưa cuộc kháng chiến chuyển sang giai đoạn mới"], "answer": "C", "key": "2.48", "explanation": "60 ngày đêm → giam chân địch, bảo vệ cơ quan đầu não rút lên căn cứ.", "topic": "1946–1947 · Toàn quốc kháng chiến", "extra": false, "review": false, "tier": 7, "sources": [], "hint": "Giam chân địch tạo điều kiện cho cơ quan lãnh đạo và lực lượng rút đi an toàn."}, {"chapter": 2, "number": 49, "id": "415507665", "question": "Thắng lợi của chiến dịch nào đã bảo toàn tuyệt đối an toàn cơ quan đầu não và căn cứ địa kháng chiến, đánh bại hoàn toàn ảo vọng chiến tranh đánh nhanh, thắng nhanh của thực dân Pháp?", "options": ["Chiến dịch Việt Bắc thu đông 1947", "Chiến dịch Biên giới thu đông 1950", "Chiến dịch Hòa Bình 1951", "Chiến dịch Điện Biên Phủ 1954"], "answer": "A", "key": "2.49", "explanation": "Việt Bắc 1947 → bảo vệ đầu não, đánh bại hoàn toàn đánh nhanh thắng nhanh.", "topic": "1946–1947 · Toàn quốc kháng chiến", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Tìm chiến dịch đầu kháng chiến bảo vệ căn cứ đầu não trước cuộc tiến công lớn của Pháp."}, {"chapter": 2, "number": 50, "id": "415507666", "question": "Để đối phó với cuộc tấn công của thực dân Pháp lên Việt Bắc năm 1947, Ban Thường vụ Trung ương Đảng đã ra Chỉ thị phải phá tan cuộc tấn công mùa đông của giặc Pháp, trong đó nêu rõ quyết tâm gì?", "options": ["Phải ra sức phát động mạnh mẽ cuộc chiến tranh du kích ở đồng bằng Bắc Bộ và Trung Du", "Phải ra sức phát động mạnh mẽ cuộc chiến tranh du kích ở những vùng địch chiếm đóng", "Phải ra sức phát động mạnh mẽ cuộc chiến tranh du kích ở vùng có đồng bào Công giáo", "Phải ra sức phát động mạnh mẽ các cuộc chiến tranh du kích ở tất cả các địa phương trong cả nước"], "answer": "A", "key": "2.50", "explanation": "Địch đánh Việt Bắc → phát động du kích ở đồng bằng và trung du để phối hợp.", "topic": "1946–1947 · Toàn quốc kháng chiến", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Đánh địch ở hướng khác để chia lửa, không chỉ phòng thủ tại nơi bị tiến công."}, {"chapter": 2, "number": 51, "id": "415507667", "question": "Đâu không phải là kết quả mà quân và dân ta đạt được trong chiến dịch Việt Bắc thu đông 1947?", "options": ["Lần lượt bẻ gãy tất cả các mũi tiến công nguy hiểm của giặc Pháp", "Loại khỏi vòng chiến đấu hàng ngàn tên địch, phá hủy hàng trăm xe cơ giới, bắn chìm nhiều tàu xuồng và nhiều phương tiện chiến tranh khác", "Bảo toàn tuyệt đối an toàn cơ quan đầu não và căn cứ địa kháng chiến", "Tiêu diệt được một bộ phận quan trọng sinh lực địch và mở rộng căn cứ địa cách mạng"], "answer": "D", "key": "2.51", "explanation": "Nguồn chọn D nhưng nội dung tiêu diệt sinh lực địch, mở rộng căn cứ dễ chồng lấn kết quả thực tế; cần hỏi giảng viên.", "topic": "1946–1947 · Toàn quốc kháng chiến", "extra": false, "review": true, "tier": 8, "sources": [], "hint": "Câu phủ định có nội dung chồng lấn; phân biệt bảo vệ Việt Bắc với mở thông biên giới năm 1950."}, {"chapter": 2, "number": 52, "id": "415507668", "question": "Thắng lợi của chiến dịch nào đã giúp quân ta giành được quyền chủ động chiến lược trên chiến trường chính Bắc bộ?", "options": ["Chiến dịch Việt Bắc thu đông (1947)", "Chiến dịch Biên Giới thu đông (1950)", "Chiến dịch Hà - Nam - Ninh (1951)", "Chiến dịch Điện Biên Phủ (1954)"], "answer": "B", "key": "2.52", "explanation": "Biên giới 1950 → giành quyền chủ động trên chiến trường chính Bắc Bộ.", "topic": "1950–1954 · Kháng chiến chống Pháp", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Nhớ chiến dịch sau Việt Bắc ba năm, giúp mở thông đường liên lạc quốc tế."}, {"chapter": 2, "number": 53, "id": "415507669", "question": "Đại hội đại biểu lần thứ II của Đảng (2/1951) quyết định ở Việt Nam, Đảng ra hoạt động công khai, lấy tên là?", "options": ["Đảng Cộng sản Việt Nam", "Đảng Dân chủ", "Đảng Xã hội", "Đảng Lao động Việt Nam"], "answer": "D", "key": "2.53", "explanation": "Đại hội II, 1951 → Đảng hoạt động công khai với tên Đảng Lao động Việt Nam.", "topic": "1950–1954 · Kháng chiến chống Pháp", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Đại hội II đưa Đảng ra công khai dưới tên gắn với lực lượng lao động."}, {"chapter": 2, "number": 54, "id": "415507670", "question": "Đại hội ĐBTQ lần thứ II của Đảng (2/1951) quyết định thành lập ở mỗi nước Đông Dương một Đảng riêng vì lý do chủ yếu nào?", "options": ["Để phù hợp với đặc điểm phát triển của cách mạng mỗi nước", "Để phù hợp với xu hướng phát triển của cách mạng thế giới", "Để nhanh chóng đưa cuộc kháng chiến chống thực dân Pháp tới thắng lợi", "Để chứng tỏ sự lớn mạnh của cách mạng ở Đông Dương"], "answer": "A", "key": "2.54", "explanation": "Mỗi nước Đông Dương có Đảng riêng → phù hợp đặc điểm cách mạng từng nước.", "topic": "1950–1954 · Kháng chiến chống Pháp", "extra": false, "review": false, "tier": 7, "sources": [], "hint": "Mỗi nước có điều kiện, nhiệm vụ riêng: tổ chức lãnh đạo cần thích hợp với điều đó."}, {"chapter": 2, "number": 55, "id": "415507671", "question": "Nhiệm vụ hàng đầu của cách mạng Việt Nam được xác định trong Chính Cương Đảng Lao động Việt Nam là gì?", "options": ["Đánh đuổi bọn đế quốc xâm lược, giành độc lập và thống nhất thật sự cho dân tộc", "Xóa bỏ những di tích phong kiến và nửa phong kiến, làm cho người cày có ruộng", "Phát triển chế độ dân chủ nhân dân, gây cơ sở cho chủ nghĩa xã hội", "Xây dựng đời sống văn hóa mới"], "answer": "A", "key": "2.55", "explanation": "Chính cương 1951 → đánh đuổi xâm lược, giành độc lập và thống nhất.", "topic": "1950–1954 · Kháng chiến chống Pháp", "extra": false, "review": false, "tier": 7, "sources": [], "hint": "Đề hỏi nhiệm vụ hàng đầu khi đất nước vẫn đang bị xâm lược và chưa thống nhất."}, {"chapter": 2, "number": 56, "id": "415507672", "question": "Chính cương Đảng Lao động Việt Nam xác định tính chất của xã hội Việt Nam là?", "options": ["Tính dân chủ nhân dân, một phần thuộc địa và nửa phong kiến", "Tính dân chủ nhân dân, một phần thuộc địa và nửa dân chủ tư sản", "Một phần thuộc địa, nửa phong kiến và nửa dân chủ tư sản", "Một phần thuộc địa, nửa dân chủ nhân dân và nửa dân chủ tư sản"], "answer": "A", "key": "2.56", "explanation": "Ba tính chất → dân chủ nhân dân – một phần thuộc địa – nửa phong kiến.", "topic": "1950–1954 · Kháng chiến chống Pháp", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Tìm phương án phản ánh đồng thời chế độ mới, phần đất bị chiếm và tàn dư xã hội cũ."}, {"chapter": 2, "number": 57, "id": "415507673", "question": "Chính cương Đảng Lao động Việt Nam xác định động lực của cách mạng Việt Nam có nền tảng là?", "options": ["Công nhân và nông dân", "Công nhân, nông dân và lao động trí óc", "Công nhân và lao động trí óc", "Nông dân và lao động trí óc"], "answer": "B", "key": "2.57", "explanation": "Nền tảng động lực → công nhân + nông dân + lao động trí óc.", "topic": "1950–1954 · Kháng chiến chống Pháp", "extra": false, "review": false, "tier": 7, "sources": [], "hint": "Phân biệt toàn bộ lực lượng tham gia với ba thành phần tạo nền tảng động lực."}, {"chapter": 2, "number": 58, "id": "415507674", "question": "Mục tiêu của Trung ương Đảng khi phát động quần chúng nông dân triệt để giảm tô, giảm tức tiến tới cải cách ruộng đất vào năm 1953 là gì?", "options": ["Làm động lực chiến đấu cho toàn quân đánh giặc", "Nhanh chóng kết thúc chiến tranh, tiến tới giành thắng lợi trong chiến dịch Điên Biên Phủ", "Nhằm thực hiện giảm tô, giảm thuế cho nông dân", "Để bồi dưỡng nông dân, củng cố khối liên minh công nông, đẩy mạnh kháng chiến"], "answer": "D", "key": "2.58", "explanation": "Giảm tô, cải cách ruộng đất → bồi dưỡng nông dân, củng cố công–nông, phục vụ kháng chiến.", "topic": "1950–1954 · Kháng chiến chống Pháp", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Chính sách với nông dân vừa đáp ứng quyền lợi vừa tăng nguồn lực cho kháng chiến."}, {"chapter": 2, "number": 59, "id": "415507675", "question": "Đâu không phải là ý nghĩa của việc thực hiện cải cách ruộng đất cuối năm 1953 đầu năm 1954?", "options": ["Tạo sự chuyển biến lớn về kinh tế, chính trị ở nông thôn, thúc đẩy sức sản xuất", "Cải thiện đời sống vật chất và tinh thần của người nông dân trên cả nước", "Làm nức lòng bộ đội nơi tiền tuyến, tăng thêm quyết tâm giết giặc, lập công", "Góp phần tích cực động viên sức người, sức của cho Chiến dịch Điện Biên Phủ"], "answer": "B", "key": "2.59", "explanation": "Câu phủ định: cải cách chưa triển khai trên CẢ NƯỚC trong điều kiện chiến tranh chia cắt.", "topic": "1950–1954 · Kháng chiến chống Pháp", "extra": false, "review": false, "tier": 8, "sources": [], "hint": "Chú ý phạm vi CẢ NƯỚC trong khi chiến tranh và vùng kiểm soát còn khác nhau."}, {"chapter": 2, "number": 60, "id": "415507676", "question": "Những kết quả đạt được trong thực hiện cách ruộng đất từ cuối năm 1953 đến cuối năm 1954 là gì?", "options": ["Hàng ngàn hécta ruộng đất và các loại nông cụ, trâu bò đã được chia cho nông dân nghèo, nhất là bần, cố nông", "Hàng ngàn hécta ruộng đất và các loại nông cụ, trâu bò đã được trả lại cho các gia đình địa chủ yêu nước", "Hàng ngàn hécta ruộng đất và các loại nông cụ, trâu bò đã được trả lại cho các gia đình phú nông", "Tất cả các đáp án trên"], "answer": "A", "key": "2.60", "explanation": "Kết quả theo nguồn → chia ruộng, nông cụ, trâu bò cho nông dân nghèo.", "topic": "1950–1954 · Kháng chiến chống Pháp", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Xét những tư liệu sản xuất cụ thể được phân chia, không nhầm mục tiêu với kết quả."}, {"chapter": 2, "number": 61, "id": "415507677", "question": "Tháng 4/1952, Hội nghị Ban Chấp hành Trung ương lần thứ ba của Đảng đề ra những quyết sách lớn về công tác “chỉnh Đảng, chỉnh quân” và coi đây là nhiệm vụ trung tâm của giai đoạn này. Nội dung nào dưới đây không là quyết sách của Hội nghị?", "options": ["Phát động cuộc vận động tăng gia sản xuất, thực hành tiết kiệm, khắc phục khó khăn, hăng hái lao động tự túc một phần lương thực, thực phẩm", "Bảo đảm đạn dược, thuốc men, quân trang, quân dụng cung cấp đủ cho bộ đội", "Thực hiện từng bước chính sách ruộng đất, chính sách thuế nông nghiệp, chính sách địa tô", "Củng cố Mặt trận dân tộc bằng việc thành lập mặt trận Tổ quốc Việt Nam"], "answer": "D", "key": "2.61", "explanation": "Mặt trận Tổ quốc thành lập 1955 → không thuộc quyết sách hội nghị 1952.", "topic": "1950–1954 · Kháng chiến chống Pháp", "extra": false, "review": false, "tier": 8, "sources": [], "hint": "So năm hội nghị với năm ra đời của tổ chức mặt trận được nêu trong phương án."}, {"chapter": 2, "number": 62, "id": "415507678", "question": "Nguyên nhân của việc Pháp chấp nhận đàm phán với ta tại Hội nghị Giơnevơ?", "options": ["Pháp thất bại liên tiếp trên chiến trường, đặc biệt là ở Điện Biên Phủ", "Sức ép từ Liên Xô và các nước Đông Âu", "Pháp bị cô lập ở Điện Biên Phủ", "Dư luận thế giới phản đối cuộc chiến tranh ở Đông Dương của Pháp"], "answer": "A", "key": "2.62", "explanation": "Thất bại quân sự, nhất là Điện Biên Phủ → buộc Pháp đàm phán.", "topic": "1950–1954 · Kháng chiến chống Pháp", "extra": false, "review": false, "tier": 7, "sources": [], "hint": "Tìm nguyên nhân bắt nguồn từ thất bại quân sự quyết định trên chiến trường."}, {"chapter": 2, "number": 63, "id": "415507679", "question": "Trong quá trình diễn ra Hội nghị Giơnevơ, Mỹ đã gây sức ép buộc Pháp chấp nhận điều gì?", "options": ["Thành lập một chính quyền mới thay cho chính quyền thân Pháp", "Chấp nhận đưa Ngô Đình Diệm về nước làm Thủ trướng trong chính quyền Bảo Đại", "Trao toàn bộ quyền lợi của Pháp ở Đông Dương cho Mỹ", "Pháp phải lệ thuộc và chịu sự can thiệp của Mỹ về vấn đề Đông Dương"], "answer": "B", "key": "2.63", "explanation": "Mỹ thúc ép đưa Ngô Đình Diệm → chuẩn bị can thiệp, thay chân Pháp.", "topic": "1950–1954 · Kháng chiến chống Pháp", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Mỹ tìm cách đưa một nhân vật thân Mỹ vào chính quyền ở miền Nam."}, {"chapter": 2, "number": 64, "id": "415507680", "question": "Luận điểm nào dưới đây là ý nghĩa thắng lợi của chiến dịch Điện Biên Phủ (5/1954)?", "options": ["Chấm dứt gần100 năm đô hộ của thực dân Pháp", "Mở ra kỷ nguyên mới: kỷ nguyên của độc lập dân tộc và tự do của nhân dân", "Là thắng lợi của ý chí và khát vọng độc lập, tự do của nhân dân Việt Nam", "Tất cả các đáp án trên"], "answer": "C", "key": "2.64", "explanation": "Điện Biên Phủ → thắng lợi của ý chí độc lập, tự do.", "topic": "1950–1954 · Kháng chiến chống Pháp", "extra": false, "review": false, "tier": 7, "sources": [], "hint": "Chọn ý nghĩa gắn với khát vọng cơ bản của một dân tộc đang đấu tranh giành độc lập."}, {"chapter": 2, "number": 65, "id": "415507681", "question": "Thắng lợi của chiến dịch Điện Biên Phủ đã tạo ra cơn chấn động đối với nước Pháp như thế nào?", "options": ["Là thảm hoạ lớn nhất của nước Pháp", "Là sự thất bại thảm hại lớn nhất trong lịch sử của nước Pháp", "Là nỗi thất vọng to lớn của nước Pháp", "Là nỗi kinh hoàng khủng khiếp của nước Pháp"], "answer": "D", "key": "2.65", "explanation": "Theo cách diễn đạt nguồn → Điện Biên Phủ gây chấn động, kinh hoàng cho phía Pháp.", "topic": "1950–1954 · Kháng chiến chống Pháp", "extra": false, "review": false, "tier": 7, "sources": [], "hint": "Cách diễn đạt trong nguồn nhấn mạnh cú sốc rất lớn đối với phía Pháp."}, {"chapter": 2, "number": 66, "id": "415507682", "question": "Hiệp định Giơnevơ về chấm dứt chiến tranh lập lại Hòa bình ở Đông Dương đã quyết định lấy vĩ tuyến bao nhiêu làm giới tuyến quân sự tạm thời?", "options": ["Vĩ tuyến 17", "Vĩ tuyến 18", "Vĩ tuyến 19", "Vĩ tuyến 20"], "answer": "A", "key": "2.66", "explanation": "Giơnevơ 1954 → vĩ tuyến 17 là giới tuyến quân sự TẠM THỜI.", "topic": "1950–1954 · Kháng chiến chống Pháp", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Phân biệt giới tuyến quân sự tạm thời năm 1954 với ranh giới giải giáp Nhật năm 1945."}, {"chapter": 2, "number": 67, "id": "415507683", "question": "Hội nghị quốc tế Giơnevơ về chấm dứt chiến tranh, lập lại hòa bình ở Đông Dương chính thức khai mạc ngày nào?", "options": ["13/3/1954", "7/5/1954", "8/5/1954", "7/5/1955"], "answer": "C", "key": "2.67", "explanation": "8/5/1954 → bắt đầu bàn vấn đề Đông Dương; hội nghị Giơnevơ chung khai mạc 26/4, cần phân biệt.", "topic": "1950–1954 · Kháng chiến chống Pháp", "extra": false, "review": true, "tier": 8, "sources": [], "hint": "Đề nói về phần hội nghị bàn Đông Dương: nhớ thời điểm ngay sau chiến thắng Điện Biên Phủ."}, {"chapter": 2, "number": 68, "id": "415507684", "question": "Tình hình Việt Nam sau Hiệp định Giơnevơ năm 1954?", "options": ["Đất nước hòa bình, thống nhất", "Cả nước tiến lên xây dựng chủ nghĩa xã hội", "Tạm thời bị chia cắt thành 2 miền với 2 chế độ chính trị khác nhau", "Kinh tế miền Bắc phát triển, đời sống nhân dân được cải thiện đáng kể"], "answer": "C", "key": "2.68", "explanation": "Sau 1954 → hai miền, hai chế độ; chia cắt tạm thời.", "topic": "1954–1960 · Hai miền & Đồng Khởi", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Hiệp định chưa đưa tới thống nhất ngay; hai miền có điều kiện chính trị khác nhau."}, {"chapter": 2, "number": 69, "id": "415507685", "question": "Nhiệm vụ cơ bản nhất của cách mạng Việt Nam sau 1954 là gì?", "options": ["Xây dựng CNXH ở miền Bắc, hỗ trợ cho cách mạng miền Nam", "Tiến hành cách mạng dân tộc dân chủ ở miền Nam chống Mỹ - Ngụy", "Miền Bắc xây dựng CNXH, miền Nam hoàn thành cách mạng dân tộc dân chủ nhân dân, tiến tới thống nhất nước nhà", "Miền Bắc xây dựng CNXH, chi viện cho miền Nam, miền Nam tiến hành cách mạng dân tộc dân chủ nhân dân, bảo vệ miền Bắc, thực hiện thống nhất nước nhà."], "answer": "D", "key": "2.69", "explanation": "Bắc xây CNXH, Nam cách mạng dân tộc dân chủ → cùng mục tiêu thống nhất.", "topic": "1954–1960 · Hai miền & Đồng Khởi", "extra": false, "review": false, "tier": 7, "sources": [], "hint": "Hai miền có nhiệm vụ khác nhau nhưng cùng phục vụ mục tiêu chung của cả nước."}, {"chapter": 2, "number": 70, "id": "415507686", "question": "Nhiệm vụ chủ yếu nhất của cách mạng miền Bắc sau 1954 là tiến hành?", "options": ["Khắc phục hậu quả chiến tranh", "Cách mạng xã hội chủ nghĩa", "Đấu tranh đòi Mỹ rút quân về nước", "Cách mạng dân chủ tư sản"], "answer": "B", "key": "2.70", "explanation": "Miền Bắc sau 1954 → cách mạng xã hội chủ nghĩa, xây hậu phương.", "topic": "1954–1960 · Hai miền & Đồng Khởi", "extra": false, "review": false, "tier": 7, "sources": [], "hint": "Miền Bắc đã được giải phóng: nhiệm vụ khác miền Nam còn chịu thống trị ngoại bang."}, {"chapter": 2, "number": 71, "id": "415507687", "question": "Tình hình miền Nam sau hiệp định Giơnevơ được ký kết (tháng 7/1954)?", "options": ["Xây dựng CNXH", "Khôi phục kinh tế, hàn gắn vết thương chiến tranh", "Tập trung cho phát triển công nghiệp nặng", "Vẫn chịu ách thống trị của đế quốc và tay sai"], "answer": "D", "key": "2.71", "explanation": "Miền Nam → tiếp tục chịu thống trị của đế quốc và tay sai.", "topic": "1954–1960 · Hai miền & Đồng Khởi", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Đừng suy ra từ hòa bình ở miền Bắc rằng cả nước đã thoát mọi ách thống trị."}, {"chapter": 2, "number": 72, "id": "415507688", "question": "Kẻ thù trực tiếp của nhân dân miền Nam sau hiệp định Giơnevơ năm 1954 là?", "options": ["Đế quốc Mỹ", "Thực dân Pháp", "Chính quyền tay sai Ngô Đình Diệm", "Mỹ và chính quyền Ngô Đình Diệm"], "answer": "D", "key": "2.72", "explanation": "Sau Giơnevơ → Mỹ và chính quyền Ngô Đình Diệm là kẻ thù trực tiếp ở miền Nam.", "topic": "1954–1960 · Hai miền & Đồng Khởi", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Chú ý thế lực thay chân Pháp và bộ máy chính quyền do thế lực đó hậu thuẫn."}, {"chapter": 2, "number": 73, "id": "415507689", "question": "Nội dung nào dưới đây không đúng về thuận lợi của cách mạng miền Nam ngay sau tháng 7/1954?", "options": ["Lực lượng quần chúng nhân dân đông đảo", "Lực lượng vũ trang lớn mạnh", "Tinh thần đấu tranh của nhân dân lên cao", "Có sự lãnh đạo của Đảng"], "answer": "B", "key": "2.73", "explanation": "Câu phủ định: phần lớn bộ đội tập kết ra Bắc → không thể coi vũ trang miền Nam đã lớn mạnh ngay.", "topic": "1954–1960 · Hai miền & Đồng Khởi", "extra": false, "review": false, "tier": 8, "sources": [], "hint": "Câu phủ định: xét tác động của việc tập kết bộ đội sau hiệp định đối với miền Nam."}, {"chapter": 2, "number": 74, "id": "415507690", "question": "Việc kí kết và thi hành Hiệp định Giơnevơ đã tạo ra sự chuyển biến như thế nào đối với cách mạng Việt Nam?", "options": ["Chuyển từ thế giữ gìn lực lượng sang thế tiến công về chiến lược.", "Chuyển từ thế bị động phòng ngự sang thế tiến công về chiến lược.", "Chuyển từ thế tiến công sang thế giữ gìn lực lượng.", "Chuyển từ thế bị động sang thế chủ động"], "answer": "C", "key": "2.74", "explanation": "Nguồn mô tả thế giữ gìn lực lượng của MIỀN NAM sau 1954; câu hỏi ghi chung Việt Nam chưa chặt.", "topic": "1954–1960 · Hai miền & Đồng Khởi", "extra": false, "review": true, "tier": 8, "sources": [], "hint": "Câu hỏi ghi Việt Nam quá rộng; hãy xét sự chuyển thế của cách mạng miền Nam sau tập kết."}, {"chapter": 2, "number": 75, "id": "415507691", "question": "Đặc điểm lớn nhất, độc đáo nhất của cách mạng Việt Nam thời kỳ 1954-1975 là", "options": ["Một Đảng lãnh đạo nhân dân tiến hành đồng thời hai chiến lược cách mạng ở hai miền Nam - Bắc", "Đảng lãnh đạo cả nước đi lên xây dựng chủ nghĩa xã hội", "Đảng lãnh đạo nhân dân hoàn thành cách mạng dân chủ và xã hội chủ nghĩa trong cả nước", "Đảng lãnh đạo nhân dân hoàn thành cuộc cách mạng dân chủ nhân dân trong cả nước"], "answer": "A", "key": "2.75", "explanation": "Một Đảng → đồng thời hai chiến lược cách mạng ở hai miền.", "topic": "1954–1960 · Hai miền & Đồng Khởi", "extra": false, "review": false, "tier": 7, "sources": [], "hint": "Đặc điểm độc đáo nằm ở sự lãnh đạo thống nhất đối với hai nhiệm vụ khác nhau theo vùng."}, {"chapter": 2, "number": 76, "id": "415507692", "question": "Thực tiễn lịch sử nào là yếu tố quyết định nhân dân Việt Nam phải tiến hành đồng thời hai nhiệm vụ cách mạng trong thời kỳ 1954-1975?", "options": ["Đất nước tạm thời bị chia cắt thành hai miền với hai chế độ chính trị khác nhau.", "Đất nước hoàn toàn được giải phóng.", "Đất nước bị chia cắt thành hai miền với hai chế độ chính trị khác nhau.", "Thực hiện chủ trương của Đảng đã được đề ra trong Cương lĩnh chính trị đầu tiên."], "answer": "A", "key": "2.76", "explanation": "Hai miền có chế độ khác nhau → cần hai nhiệm vụ phù hợp.", "topic": "1954–1960 · Hai miền & Đồng Khởi", "extra": false, "review": false, "tier": 7, "sources": [], "hint": "Nguyên nhân thực tiễn là tình trạng chia cắt cùng sự khác biệt chế độ ở hai miền."}, {"chapter": 2, "number": 77, "id": "415507693", "question": "Đường lối thể hiện sự lãnh đạo sáng suốt, độc đáo của Đảng ta ngay sau khi hiệp định Giơnevơ được kí kết là:", "options": ["Tiến hành cách mạng dân tộc dân chủ nhân dân ở miền Nam", "Hoàn thành cuộc cách mạng dân tộc dân chủ nhân dân trong cả nước, thống nhất nước nhà", "Tiến hành đồng thời cách mạng dân tộc dân chủ nhân dân ở miền Nam và cách mạng XHCN ở miền Bắc", "Tiến hành cách mạng XHCN ở miền Bắc."], "answer": "C", "key": "2.77", "explanation": "Bắc XHCN + Nam dân tộc dân chủ → đường lối kết hợp hai chiến lược.", "topic": "1954–1960 · Hai miền & Đồng Khởi", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Đường lối phù hợp phải giải quyết đồng thời yêu cầu phát triển miền Bắc và giải phóng miền Nam."}, {"chapter": 2, "number": 78, "id": "415507694", "question": "Chuyển cách mạng miền Nam từ thế giữ gìn lực lượng sang thế tiến công là nội dung của giai đoạn nào?", "options": ["1954 - 1960", "1961 - 1965", "1965 - 1968", "1969 - 1975"], "answer": "A", "key": "2.78", "explanation": "1954–1960 → cuối giai đoạn chuyển sang tiến công qua Đồng Khởi.", "topic": "1954–1960 · Hai miền & Đồng Khởi", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Tìm giai đoạn kết thúc bằng cao trào Đồng Khởi, trước thời kỳ Chiến tranh đặc biệt."}, {"chapter": 2, "number": 79, "id": "415507695", "question": "Đồng chí nào là người dự thảo Đường lối cách mạng miền Nam (8/1956)?", "options": ["Đ/c Phạm Hùng", "Đ/c Lê Đức Thọ", "Đ/c Phạm Văn Đồng", "Đ/c Lê Duẩn"], "answer": "D", "key": "2.79", "explanation": "Đề cương cách mạng miền Nam năm 1956 → Lê Duẩn.", "topic": "1954–1960 · Hai miền & Đồng Khởi", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Nhớ người từng trực tiếp hoạt động, lãnh đạo cách mạng miền Nam rồi trở thành Bí thư thứ nhất."}, {"chapter": 2, "number": 80, "id": "415507696", "question": "Hội nghị Trung ương nào đã ra nghị quyết về tình hình cách mạng miền Nam?", "options": ["Hội nghị Trung ương 12 khóa II (3/1957)", "Hội nghị Trung ương 13 khóa II (12/1957)", "Hội nghị Trung ương 14 khóa II (11/1958)", "Hội nghị Trung ương 15 khóa II (1/1959)"], "answer": "D", "key": "2.80", "explanation": "Trung ương 15, tháng 1/1959 → chủ trương cho cách mạng miền Nam.", "topic": "1954–1960 · Hai miền & Đồng Khởi", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Hội nghị diễn ra đầu năm 1959, trước bước ngoặt Đồng Khởi."}, {"chapter": 2, "number": 81, "id": "415507697", "question": "Sự kiện nào dưới đây của quân và dân miền Nam trong cuộc kháng chiến chống Mỹ (1954-1975) đã đánh dấu cách mạng miền Nam chuyển từ thế giữ gìn lực lượng sang thế tiến công?", "options": ["Chiến thắng Bình Giã", "Chiến thắng Ấp Bắc", "Phong trào “Đồng Khởi”", "Chiến thắng Vạn Tường"], "answer": "C", "key": "2.81", "explanation": "Đồng Khởi → từ giữ gìn lực lượng sang thế tiến công.", "topic": "1954–1960 · Hai miền & Đồng Khởi", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Sự kiện có khởi nghĩa lan rộng ở nông thôn cuối thập niên 1950, đầu 1960."}, {"chapter": 2, "number": 82, "id": "415507698", "question": "Với thắng lợi của phong trào “Đồng Khởi”, quân và dân miền Nam đã làm phá sản chiến lược chiến tranh nào của Mỹ?", "options": ["Chiến tranh cục bộ", "Chiến tranh đặc biệt", "Việt Nam hóa chiến tranh", "Chiến tranh đơn phương"], "answer": "D", "key": "2.82", "explanation": "Đồng Khởi → phá sản chiến lược chiến tranh đơn phương theo phân kỳ của nguồn.", "topic": "1954–1960 · Hai miền & Đồng Khởi", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Xem chiến lược mà Mỹ thực hiện trước khi chuyển sang Chiến tranh đặc biệt."}, {"chapter": 2, "number": 83, "id": "415507699", "question": "Kết quả lớn nhất của phong trào “Đồng Khởi” (1959-1960) là?", "options": ["Làm tan rã cơ cấu chính quyền cơ sở địch ở nhiều vùng nông thôn", "Có 1.383 xã/2.627 xã nhân dân lập chính quyền tự quản", "Vùng giải phóng ra đời trên phạm vi rộng lớn, nối liền từ Tây Nguyên đến miền Tây Nam Bộ và đồng bằng Liên khu V", "Sự ra đời của Mặt trận Dân tộc giải phóng miền Nam Việt Nam (20/12/1960), tại xã Tân Lập (Tây Ninh), do Luật sư Nguyễn Hữu Thọ làm Chủ tịch"], "answer": "D", "key": "2.83", "explanation": "20/12/1960 → Mặt trận Dân tộc giải phóng miền Nam ra đời; Nguyễn Hữu Thọ làm Chủ tịch.", "topic": "1954–1960 · Hai miền & Đồng Khởi", "extra": false, "review": false, "tier": 7, "sources": [], "hint": "Kết quả về tổ chức chính trị toàn miền Nam được hình thành cuối năm 1960."}, {"chapter": 2, "number": 84, "id": "415507700", "question": "Đại hội ĐBTQ lần thứ III (9/1960) của Đảng diễn ra trong bối cảnh lịch sử nào?", "options": ["Cách mạng hai miền Nam - Bắc có những bước tiến quan trọng", "Cách mạng miền Nam gặp khó khăn, cách mạng miền Bắc thành công", "Mỹ thực hiện chiến lược chiến tranh mới ở miền Nam", "Miền Bắc xây dựng CNXH đạt được những thành tựu quan trọng"], "answer": "A", "key": "2.84", "explanation": "Đại hội III → cách mạng hai miền đã có bước tiến, cần xác định đường lối chung.", "topic": "1954–1960 · Hai miền & Đồng Khởi", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Đại hội diễn ra sau những chuyển biến quan trọng ở cả miền Bắc và miền Nam cuối thập niên 1950."}, {"chapter": 2, "number": 85, "id": "415507701", "question": "Đại hội đại biểu lần thứ mấy của Đảng là “Đại hội xây dựng chủ nghĩa xã hội ở miền Bắc và đấu tranh hòa bình thống nhất nước nhà”?", "options": ["Đại hội đại biểu lần thứ II (2/1951)", "Đại hội đại biểu lần thứ III (9/1960)", "Đại hội đại biểu lần thứ IV (12/1976)", "Đại hội đại biểu lần thứ V (3/1982)"], "answer": "B", "key": "2.85", "explanation": "Đại hội III năm 1960 → xây CNXH miền Bắc, đấu tranh thống nhất.", "topic": "1954–1960 · Hai miền & Đồng Khởi", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Tìm đại hội tổ chức khi hai chiến lược cách mạng ở hai miền được xác định rõ."}, {"chapter": 2, "number": 86, "id": "415507702", "question": "Khi đánh giá về mối quan hệ giữa cách mạng hai miền Nam - Bắc, Nghị quyết Đại hội ĐBTQ lần thứ III của Đảng (9/1960) khẳng định: “Do cùng thực hiện một mục tiêu chung nên “Hai nhiệm vụ chiến lược ấy có quan hệ (… ) với nhau và có tác dụng (…) lẫn nhau”. ”. Điền từ vào dấu (…)", "options": ["Khăng khít - thúc đẩy", "Gắn bó - bổ trợ", "Biện chứng - bổ trợ", "Mật thiết - thúc đẩy"], "answer": "D", "key": "2.86", "explanation": "Hai nhiệm vụ → quan hệ mật thiết, thúc đẩy lẫn nhau.", "topic": "1954–1960 · Hai miền & Đồng Khởi", "extra": false, "review": false, "tier": 7, "sources": [], "hint": "Hai nhiệm vụ không tách rời hay cản trở; chúng liên hệ và hỗ trợ phát triển nhau."}, {"chapter": 2, "number": 87, "id": "415507703", "question": "Nghị quyết của Đại hội ĐBTQ lần thứ III của Đảng (9/1960) xác định cách mạng XHCN ở Miền Bắc có vai trò gì trong sự nghiệp thống nhất nước nhà?", "options": ["Quyết định", "Quyết định trực tiếp", "Quyết định nhất", "Quyết định quan trọng"], "answer": "C", "key": "2.87", "explanation": "Miền Bắc → QUYẾT ĐỊNH NHẤT; miền Nam → QUYẾT ĐỊNH TRỰC TIẾP.", "topic": "1954–1960 · Hai miền & Đồng Khởi", "extra": false, "review": false, "tier": 7, "sources": [], "hint": "So vai trò hậu phương đối với toàn bộ cách mạng với vai trò trực tiếp giải phóng miền Nam."}, {"chapter": 2, "number": 88, "id": "415507704", "question": "Đường lối tiến hành đồng thời và kết hợp chặt chẽ hai chiến lược cách mạng khác nhau ở hai miền: Cách mạng XHCN ở miền Bắc và cách mạng dân tộc dân chủ nhân dân ở miền Nam được khẳng định tại đại hội mấy?", "options": ["Đại hội ĐBTQ lần thứ II của Đảng (2/1951)", "Hội nghị Trung ương 13 khóa II (12-1957)", "Hội nghị Trung ương 14 khóa II (11-1958)", "ĐH ĐBTQ lần thứ III của Đảng (9/1960)"], "answer": "D", "key": "2.88", "explanation": "Hai chiến lược hai miền → Đại hội III, tháng 9/1960.", "topic": "1954–1960 · Hai miền & Đồng Khởi", "extra": false, "review": false, "tier": 8, "sources": [], "hint": "Gắn đường lối hai chiến lược với đại hội đầu tiên trong thời kỳ đất nước chia cắt sau 1954."}, {"chapter": 2, "number": 89, "id": "415507705", "question": "Đồng chí nào là Chủ tịch đầu tiên của Mặt trận Dân tộc giải phóng miền Nam Việt Nam?", "options": ["Đ/c Lê Duẩn", "Đ/c Nguyễn Văn Linh", "Đ/c Phạm Văn Đồng", "Đ/c Nguyễn Hữu Thọ"], "answer": "D", "key": "2.89", "explanation": "Chủ tịch đầu tiên Mặt trận giải phóng miền Nam → Nguyễn Hữu Thọ.", "topic": "1954–1960 · Hai miền & Đồng Khởi", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Nhớ vị luật sư yêu nước từng lãnh đạo Mặt trận giải phóng miền Nam."}, {"chapter": 2, "number": 90, "id": "415507706", "question": "Giai đoạn nào dưới đây, cách mạng miền Nam thực hiện đưa đấu tranh vũ trang phát triển song song với đấu tranh chính trị, tiến công địch trên cả ba vùng chiến lược: đô thị, nông thôn đồng bằng và nông thôn rừng núi?", "options": ["1954 - 1960", "1961 - 1965", "1965 - 1968", "1969 - 1973"], "answer": "B", "key": "2.90", "explanation": "1961–1965 → chính trị song song vũ trang, tiến công trên ba vùng.", "topic": "1961–1968 · Đặc biệt & cục bộ", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Xác định thời kỳ chống Chiến tranh đặc biệt, trước khi quân Mỹ trực tiếp vào chiến đấu quy mô lớn."}, {"chapter": 2, "number": 91, "id": "415507707", "question": "Giai đoạn nào dưới đây, cuộc đấu tranh của nhân dân miền Nam chuyển từ khởi nghĩa từng phần sang chiến tranh cách mạng?", "options": ["1954 - 1960", "1961 - 1965", "1965 - 1968", "1969 - 1973"], "answer": "B", "key": "2.91", "explanation": "1961–1965 → từ khởi nghĩa từng phần lên chiến tranh cách mạng.", "topic": "1961–1968 · Đặc biệt & cục bộ", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Đây là bước phát triển sau Đồng Khởi, gắn giai đoạn chống Chiến tranh đặc biệt."}, {"chapter": 2, "number": 92, "id": "415507708", "question": "Âm mưu của Mỹ trong chiến lược “chiến tranh đặc biệt” giống với âm mưu trong chiến lược nào sau đây?", "options": ["Chiến tranh đơn phương", "Chiến tranh cục bộ", "Việt Nam hóa chiến tranh", "Đông Dương hóa chiến tranh"], "answer": "B", "key": "2.92", "explanation": "Nguồn chọn B; câu hỏi âm mưu quá rộng. Dùng người Việt đánh người Việt thường gắn Đặc biệt và Việt Nam hóa, cần đối chiếu.", "topic": "1961–1968 · Đặc biệt & cục bộ", "extra": false, "review": true, "tier": 8, "sources": [], "hint": "Câu hỏi rộng: phân biệt mục tiêu thuộc địa kiểu mới với thủ đoạn dùng người Việt đánh người Việt."}, {"chapter": 2, "number": 93, "id": "415507709", "question": "Ý nghĩa quan trọng nhất của việc thực hiện kế hoạch 5 năm lần thứ nhất (1961-1965) của nhân dân miền Bắc là gì?", "options": ["Làm cho bộ mặt miền Bắc thay đổi khác trước rất nhiều", "Miền Bắc đủ sức để tự bảo vệ sự nghiệp xây dựng CNXH", "Nền kinh tế của miền Bắc đủ sức chi viện cho miền Nam", "Miền Bắc được củng cố vững mạnh, có khả năng tự bảo vệ và thực hiện đầy đủ nghĩa vụ hậu phương."], "answer": "D", "key": "2.93", "explanation": "Kế hoạch 1961–1965 → củng cố miền Bắc, tăng sức tự vệ và chi viện.", "topic": "1961–1968 · Đặc biệt & cục bộ", "extra": false, "review": false, "tier": 7, "sources": [], "hint": "Xét năng lực làm hậu phương, không chỉ số nhà máy hay sản lượng từng ngành riêng lẻ."}, {"chapter": 2, "number": 94, "id": "415507710", "question": "Vì sao kế hoạch 5 năm (1961-1965) ở miền Bắc đang thực hiện lại bị gián đoạn?", "options": ["Do có hạn chế nên bị đình chỉ thực hiện", "Do kế hoạch không đạt hiệu quả trong thực tế", "Do Mỹ tiến hành chiến tranh phá hoại miền Bắc", "Do cơ sở vật chất để thực hiện kế hoạch không đủ"], "answer": "C", "key": "2.94", "explanation": "Mỹ đánh phá miền Bắc → gián đoạn thực hiện kế hoạch 5 năm.", "topic": "1961–1968 · Đặc biệt & cục bộ", "extra": false, "review": false, "tier": 7, "sources": [], "hint": "Kế hoạch bị tác động bởi hoạt động quân sự của Mỹ lan ra phía Bắc."}, {"chapter": 2, "number": 95, "id": "415507711", "question": "Các lực lượng vũ trang ở miền Nam được thống nhất với tên gọi Quân giải phóng miền Nam Việt Nam vào thời gian nào?", "options": ["15/2/1954", "15/2/1958", "15/2/1956", "15/2/1961"], "answer": "D", "key": "2.95", "explanation": "15/2/1961 → thống nhất các lực lượng thành Quân giải phóng miền Nam.", "topic": "1961–1968 · Đặc biệt & cục bộ", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Mốc thành lập lực lượng thống nhất diễn ra đầu thời kỳ chống Chiến tranh đặc biệt."}, {"chapter": 2, "number": 96, "id": "415507712", "question": "Hội nghị Ban Chấp hành Trung ương Đảng lần thứ 11 (3/1965) và lần thứ 12 (12/1965) khẳng định vai trò của miền Bắc là:", "options": ["Hậu phương", "Hậu phương lớn", "Hậu phương vững chắc", "Hậu phương quan trọng"], "answer": "B", "key": "2.96", "explanation": "1965 → miền Bắc là hậu phương lớn, miền Nam là tiền tuyến lớn.", "topic": "1961–1968 · Đặc biệt & cục bộ", "extra": false, "review": false, "tier": 7, "sources": [], "hint": "Trong quan hệ hai miền, miền Bắc là nơi xây dựng tiềm lực và chi viện cho tiền tuyến."}, {"chapter": 2, "number": 97, "id": "415507713", "question": "Trong thời kỳ kháng chiến chống Mỹ, cứu nước, “Ba sẵn sàng” là phong trào của lực lượng nào?", "options": ["Thanh niên", "Phụ nữ", "Công nhân", "Học sinh"], "answer": "A", "key": "2.97", "explanation": "Ba sẵn sàng → phong trào thanh niên thời chống Mỹ.", "topic": "1961–1968 · Đặc biệt & cục bộ", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Đừng nhầm với phong trào Ba đảm đang của phụ nữ."}, {"chapter": 2, "number": 98, "id": "415507714", "question": "Sau chiến thắng nào dưới đây, một cao trào đánh Mỹ, diệt ngụy được dấy lên mạnh mẽ khắp chiến trường miền Nam?", "options": ["Chiến thắng Ấp Bắc (1/1963)", "Chiến thắng Bình Giã (12/1964)", "Chiến thắng Vạn Tường (8/1965)", "Tổng tiến công và nổi dậy tết Mậu thân 1968"], "answer": "C", "key": "2.98", "explanation": "Vạn Tường 8/1965 → khẳng định khả năng đánh Mỹ, cổ vũ cao trào.", "topic": "1961–1968 · Đặc biệt & cục bộ", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Tìm trận đánh lớn tại Quảng Ngãi, ngay sau khi Mỹ đưa quân chiến đấu vào miền Nam."}, {"chapter": 2, "number": 99, "id": "415507715", "question": "Cuộc Tổng tiến công và nổi dậy Tết Mậu Thân 1968 là một đòn tiến công chiến lược làm thất bại chiến lược chiến tranh nào của Mỹ ở Việt Nam?", "options": ["Chiến tranh đơn phương", "Chiến tranh đặc biệt", "Chiến tranh cục bộ", "Việt Nam hóa chiến tranh"], "answer": "C", "key": "2.99", "explanation": "Mậu Thân 1968 → làm phá sản chiến lược Chiến tranh cục bộ.", "topic": "1961–1968 · Đặc biệt & cục bộ", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Mậu Thân nằm cuối giai đoạn Mỹ trực tiếp đưa quân chiến đấu ồ ạt, chưa phải thời Việt Nam hóa."}, {"chapter": 2, "number": 100, "id": "415507716", "question": "Trong cuộc kháng chiến chống Mỹ, cứu nước, giai đoạn nào dưới đây cả nước có chiến tranh?", "options": ["1954 - 1960", "1954 - 1964", "1965 - 1968", "1965 – 1975"], "answer": "D", "key": "2.100", "explanation": "Theo phân kỳ nguồn → 1965–1975, chiến tranh diễn ra ở cả hai miền.", "topic": "1961–1968 · Đặc biệt & cục bộ", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Chú ý giai đoạn chiến tranh lan rộng ra miền Bắc, không chỉ xảy ra ở miền Nam."}, {"chapter": 2, "number": 101, "id": "415507717", "question": "Điểm khác biệt về tình hình kinh tế miền Bắc Việt Nam trong giai đoạn 1961-1965 so với các giai đoạn trước là?", "options": ["Công nghiệp hóa quy mô lớn", "Nhà nước nắm quyền chỉ huy nền kinh tế", "Phát triển nhỏ lẻ, manh mún", "Thành phần kinh tế tư nhân phát triển mạnh"], "answer": "A", "key": "2.101", "explanation": "1961–1965 → bắt đầu xây dựng công nghiệp theo kế hoạch 5 năm; cụm quy mô lớn trong nguồn cần đọc theo bối cảnh.", "topic": "1961–1968 · Đặc biệt & cục bộ", "extra": false, "review": true, "tier": 8, "sources": [], "hint": "So kế hoạch 5 năm đầu tiên với các giai đoạn chủ yếu khôi phục kinh tế trước đó."}, {"chapter": 2, "number": 102, "id": "415507718", "question": "Chiến lược Chiến tranh cục bộ của Mỹ ở miền Nam Việt Nam được tiến hành bằng lực lượng?", "options": ["Quân đội Mỹ và quân đồng minh", "Quân đội Mỹ và quân đội Sài Gòn", "Quân đội Mỹ, quân đồng minh và quân đội Sài Gòn", "Quân đội Sài Gòn do cố vấn Mỹ chỉ huy"], "answer": "C", "key": "2.102", "explanation": "Cục bộ → quân Mỹ + đồng minh + quân đội Sài Gòn.", "topic": "1961–1968 · Đặc biệt & cục bộ", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Chiến lược này đưa quân chiến đấu Mỹ trực tiếp tham chiến, đồng thời dùng các lực lượng khác."}, {"chapter": 2, "number": 103, "id": "415507719", "question": "Điểm khác nhau cơ bản của chiến lược Chiến tranh cục bộ (1965-1968) so với chiến lược Chiến tranh đặc biệt (1961-1965) là?", "options": ["Mỹ chỉ huy bằng lực lượng cố vấn", "Tiến hành chiến tranh phá hoại ở miền Bắc", "Dùng người Việt đánh người Việt", "Biến miền Nam Việt Nam thành thuộc địa kiểu mới"], "answer": "B", "key": "2.103", "explanation": "Nguồn chọn B; đừng hiểu Đặc biệt không có phá hoại miền Bắc: Mỹ đã đánh phá từ 1964–1965, mốc chiến lược có giao thoa.", "topic": "1961–1968 · Đặc biệt & cục bộ", "extra": false, "review": true, "tier": 8, "sources": [], "hint": "Đọc theo khóa nguồn và lưu ý sự giao thoa mốc; xét việc mở rộng phạm vi chiến tranh ra miền Bắc."}, {"chapter": 2, "number": 104, "id": "415507720", "question": "Điểm giống nhau cơ bản giữa chiến lược Chiến tranh đặc biệt (1961-1965) và chiến lược Chiến tranh cục bộ (1965-1968) của Mỹ ở miền Nam Việt Nam là?", "options": ["Đều được tiến hành bằng lực lượng chủ lực là quân viễn chinh Mỹ và quân đội các nước đồng minh", "Đều lấy dồn dân, lập ấp chiến lược là xương sống của chiến lược", "Cùng chung mục đích biến miền Nam Việt Nam thành thuộc địa kiểu mới", "Đều mở các cuộc hành quân “tìm diệt”, “bình định” ở miền Nam"], "answer": "C", "key": "2.104", "explanation": "Điểm chung → mục tiêu biến miền Nam thành thuộc địa kiểu mới.", "topic": "1961–1968 · Đặc biệt & cục bộ", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Đề hỏi mục đích chung, không phải lực lượng trực tiếp hay quy mô chiến tranh."}, {"chapter": 2, "number": 105, "id": "415507721", "question": "Cuộc chiến đấu nào của quân và dân miền Nam được đánh giá là một chủ trương táo bạo và sáng tạo của Đảng, đánh thẳng vào ý chí xâm lược của giới cầm quyền Mỹ?", "options": ["Trận chiến ở Núi Thành - Quảng Nam (1965)", "Trận chiến ở Vạn Tường - Quảng Ngãi (1965)", "Chiến dịch Đường 9 - Khe Sanh (1968)", "Tổng tiến công và nổi dậy Tết Mậu Thân (1968)"], "answer": "D", "key": "2.105", "explanation": "Mậu Thân 1968 → đánh vào ý chí xâm lược của Mỹ.", "topic": "1961–1968 · Đặc biệt & cục bộ", "extra": false, "review": false, "tier": 7, "sources": [], "hint": "Đòn tiến công đồng loạt đúng dịp Tết gây chấn động lớn về chính trị tại Mỹ."}, {"chapter": 2, "number": 106, "id": "415507722", "question": "Chiến lược Việt Nam hóa chiến tranh (1969-1973) được Mỹ đề ra ngay khi?", "options": ["Chiến lược Chiến tranh cục bộ bị phá sản", "Chiến lược Chiến tranh đặc biệt bị phá sản", "Nhân dân miền Nam giành thắng lợi trong phong trào Đồng khởi", "Nhân dân miền Bắc giành thắng lợi trong trận Điện Biên Phủ trên không"], "answer": "A", "key": "2.106", "explanation": "Cục bộ thất bại → Mỹ chuyển Việt Nam hóa chiến tranh từ 1969.", "topic": "1969–1973 · Việt Nam hóa & Paris", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Mỹ thay đổi chiến lược sau thất bại của phương án trực tiếp dùng quân chiến đấu quy mô lớn."}, {"chapter": 2, "number": 107, "id": "415507723", "question": "Cuộc chiến đấu của Quân giải phóng ở thành cổ Quảng trị diễn ra trong thời gian bao lâu?", "options": ["51 ngày đêm", "61 ngày đêm", "71 ngày đêm", "81 ngày đêm"], "answer": "D", "key": "2.107", "explanation": "Thành cổ Quảng Trị 1972 → 81 ngày đêm.", "topic": "1969–1973 · Việt Nam hóa & Paris", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Nhớ cuộc chiến đấu ở thành cổ kéo dài gần ba tháng trong mùa hè năm 1972."}, {"chapter": 2, "number": 108, "id": "415507724", "question": "Trận “Điện Biên Phủ trên không” đánh bại hoàn toàn cuộc chiến tranh phá hoại lần thứ 2 của Mỹ đối với miền Bắc diễn ra vào thời gian nào?", "options": ["Từ 18 đến 30/12/1960", "Từ 18 đến 30/12/1965", "Từ 18 đến 30/12/1972", "Từ 18 đến 30/12/1973"], "answer": "C", "key": "2.108", "explanation": "18–30/12/1972 → Điện Biên Phủ trên không, 12 ngày đêm.", "topic": "1969–1973 · Việt Nam hóa & Paris", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Đây là đợt tập kích cuối tháng 12, trước khi Hiệp định Paris được ký đầu năm sau."}, {"chapter": 2, "number": 109, "id": "415507725", "question": "Biện pháp tìm mọi cách thỏa hiệp với Trung Quốc, hòa hoãn với Liên Xô hòng cắt giảm nguồn viện trợ chủ yếu của Việt Nam được Mỹ thực hiện trong chiến lược chiến tranh nào?", "options": ["Chiến tranh đơn phương", "Chiến tranh đặc biệt", "Chiến tranh cục bộ", "Việt Nam hóa chiến tranh"], "answer": "D", "key": "2.109", "explanation": "Việt Nam hóa → vừa quân sự vừa ngoại giao, tìm cách cô lập Việt Nam.", "topic": "1969–1973 · Việt Nam hóa & Paris", "extra": false, "review": false, "tier": 7, "sources": [], "hint": "Thủ đoạn ngoại giao này nằm trong giai đoạn Mỹ tìm cách rút quân nhưng giữ chính quyền Sài Gòn."}, {"chapter": 2, "number": 110, "id": "415507726", "question": "“Xương sống” của chiến lược “Việt Nam hóa chiến tranh” là:", "options": ["Ngụy quân", "Vũ khí", "Đô la", "Cố vấn quân sự Mỹ"], "answer": "A", "key": "2.110", "explanation": "Việt Nam hóa → dựa chủ yếu quân đội Sài Gòn; nguồn dùng từ ngụy quân.", "topic": "1969–1973 · Việt Nam hóa & Paris", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Việt Nam hóa nhằm chuyển gánh nặng chiến đấu sang lực lượng quân sự tại chỗ."}, {"chapter": 2, "number": 111, "id": "415507727", "question": "Hiệp định Pari về Việt Nam (27/01/1973) được ký kết có ý nghĩa gì?", "options": ["Đánh dấu hoàn thành cuộc cách mạng dân tộc dân chủ nhân dân ở Việt Nam", "Giải phóng hoàn toàn miền Nam, thống nhất đất nước", "Kết thúc thắng lợi cuộc kháng chiến chống Mỹ, cứu nước", "Góp phần làm thay đổi so sánh lực lượng ở miền Nam có lợi cho CM"], "answer": "D", "key": "2.111", "explanation": "Paris 1973 → so sánh lực lượng chuyển có lợi cho cách mạng.", "topic": "1969–1973 · Việt Nam hóa & Paris", "extra": false, "review": false, "tier": 7, "sources": [], "hint": "Xem tác động của việc Mỹ rút quân đối với tương quan lực lượng tại miền Nam."}, {"chapter": 2, "number": 112, "id": "415507728", "question": "Thắng lợi nào của quân dân ta đã buộc Mỹ phải ký Hiệp định Pari về Việt Nam?", "options": ["Đồng khởi", "Ấp Bắc - Mỹ Tho (nay là Tiền Giang)", "Vạn Tường - Quảng Ngãi", "Điện Biên Phủ trên không (1972)"], "answer": "D", "key": "2.112", "explanation": "Điện Biên Phủ trên không → đòn quyết định buộc Mỹ trở lại ký Paris.", "topic": "1969–1973 · Việt Nam hóa & Paris", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Tìm thắng lợi cuối năm 1972 ở miền Bắc, tác động trực tiếp bàn đàm phán."}, {"chapter": 2, "number": 113, "id": "415507729", "question": "Thắng lợi nào đã chuyển sự nghiệp cách mạng của nhân dân Việt Nam từ “đánh cho Mỹ cút” tiến lên “đánh cho ngụy nhào”?", "options": ["Tổng tiến công nổi dậy Tết Mậu Thân (1968)", "Cuộc chiến đấu 81 ngày đêm ở thành cổ Quảng Trị (1972)", "Trận Điện Biên Phủ trên không (1972)", "Hiệp định Paris về chấm dứt chiến tranh, lập lại hòa bình ở Việt Nam (1973)"], "answer": "D", "key": "2.113", "explanation": "Paris 1973 → Mỹ rút, chuyển từ đánh cho Mỹ cút sang đánh cho ngụy nhào.", "topic": "1969–1973 · Việt Nam hóa & Paris", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Mốc chuyển tiếp gắn thỏa thuận buộc Mỹ rút quân, trước chiến dịch giải phóng năm 1975."}, {"chapter": 2, "number": 114, "id": "415507730", "question": "Điều khoản nào của Hiệp định Pari năm 1973 có ý nghĩa quyết định đối với sự phát triển của cuộc kháng chiến chống Mỹ, cứu nước?", "options": ["Hai bên ngừng bắn và giữ nguyên vị trí ở miền Nam.", "Nhân dân miền Nam tự quyết định tương lai chính trị.", "Các bên thừa nhận thực tế ở miền Nam có hai chính quyền.", "Hoa Kỳ rút hết quân viễn chinh và quân các nước đồng minh"], "answer": "D", "key": "2.114", "explanation": "Mỹ và đồng minh rút quân → thay đổi lớn tương quan lực lượng.", "topic": "1969–1973 · Việt Nam hóa & Paris", "extra": false, "review": false, "tier": 7, "sources": [], "hint": "Điều khoản làm mất chỗ dựa quân sự trực tiếp từ bên ngoài của chính quyền Sài Gòn."}, {"chapter": 2, "number": 115, "id": "415507731", "question": "Ban Chấp hành Trung ương Đảng họp Hội nghị lần thứ 21 (7/1973) đã nhận định kẻ thù của cách mạng miền Nam là?", "options": ["Chính quyền Sài Gòn", "Mỹ và đồng minh của Mỹ", "Đồng minh của Mỹ và chính quyền Sài Gòn", "Đế quốc Mỹ và tập đoàn Nguyễn Văn Thiệu"], "answer": "D", "key": "2.115", "explanation": "Trung ương 21 năm 1973 → Mỹ và chính quyền Nguyễn Văn Thiệu vẫn là kẻ thù.", "topic": "1969–1973 · Việt Nam hóa & Paris", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Dù có hiệp định, Mỹ còn can dự và chính quyền Sài Gòn vẫn tiếp tục chiến tranh."}, {"chapter": 2, "number": 116, "id": "415507732", "question": "Thắng lợi nào có ý nghĩa: “Đòn trinh sát chiến lược” giải phóng hoàn toàn miền Nam thống nhất đất nước ngay trong năm 1975?", "options": ["Giải phóng hoàn toàn tỉnh Phước Long (6/1/1975)", "Giải phóng hoàn toàn thị xã Buôn Ma Thuột (11/3/1975)", "Giải phóng hoàn toàn tỉnh Quảng Trị (19/3/1975)", "Giải phóng hoàn toàn thành phố Huế (26/3/1975)"], "answer": "A", "key": "2.116", "explanation": "Phước Long 6/1/1975 → đòn trinh sát chiến lược, thử phản ứng của Mỹ.", "topic": "1975 · Giải phóng miền Nam", "extra": false, "review": false, "tier": 7, "sources": [], "hint": "Tìm chiến thắng đầu năm 1975 giúp kiểm nghiệm khả năng Mỹ quay lại can thiệp."}, {"chapter": 2, "number": 117, "id": "415507733", "question": "Chiến dịch nào làm đảo lộn thế trận phòng thủ của Mỹ - Ngụy?", "options": ["Chiến dịch Tây Nguyên", "Chiến dịch Huế - Đà Nẵng", "Chiến dịch Hồ Chí Minh", "Tất cả các đáp án trên"], "answer": "A", "key": "2.117", "explanation": "Tây Nguyên → làm đảo lộn thế trận phòng thủ đối phương.", "topic": "1975 · Giải phóng miền Nam", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Chiến dịch đầu mùa Xuân 1975 mở đột biến ở vùng cao nguyên chiến lược."}, {"chapter": 2, "number": 118, "id": "415507734", "question": "Thắng lợi của chiến dịch Tây Nguyên có ý nghĩa lớn nhất là:", "options": ["Tạo thêm cơ sở để Bộ Chính trị quyết định giải phóng miền Nam trong năm 1975", "Nguồn cổ vũ mạnh mẽ đến quân dân ta tiến lên giải phóng hoàn toàn miền Nam", "Làm cho địch mất tinh thần, mất khả năng chiến đấu", "Chuyển cuộc kháng chiến chống Mỹ cứu nước sang giai đoạn mới, từ tiến công chiến lược sang tổng tiến công chiến lược trên toàn miền Nam"], "answer": "D", "key": "2.118", "explanation": "Tây Nguyên thắng → từ tiến công chiến lược sang tổng tiến công toàn miền Nam.", "topic": "1975 · Giải phóng miền Nam", "extra": false, "review": false, "tier": 7, "sources": [], "hint": "Xem thay đổi quy mô: từ hướng tiến công trọng điểm sang tiến công trên toàn chiến trường miền Nam."}, {"chapter": 2, "number": 119, "id": "415507735", "question": "Đúng 11 giờ 30 phút ngày 30/4/1975 ở Việt Nam đã diễn ra sự kiện lịch sử quan trọng nào?", "options": ["Toàn bộ nội các Sài Gòn bị bắt sống", "Tổng thống Dương Văn Minh tuyên bố từ chức", "Toàn bộ miền Nam được giải phóng", "Chiến dịch Hồ Chí Minh toàn thắng"], "answer": "D", "key": "2.119", "explanation": "11 giờ 30, 30/4/1975 → Chiến dịch Hồ Chí Minh toàn thắng.", "topic": "1975 · Giải phóng miền Nam", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Mốc này gắn việc kết thúc chiến dịch cuối cùng giải phóng Sài Gòn."}, {"chapter": 2, "number": 120, "id": "415507736", "question": "Cuộc tổng tiến công và nổi dậy mùa Xuân 1975 bắt đầu bằng cuộc tiến công nào?", "options": ["Tiến công thị xã Phước Long (6/1/1975)", "Tiến công thị xã Buôn Ma Thuột (10/3/1975)", "Tiến công giải phóng thành phố Huế (21/3/1975)", "Tiến công giải phóng thành phố Đà Nẵng (26/3/1975)"], "answer": "B", "key": "2.120", "explanation": "Buôn Ma Thuột 10/3/1975 → trận then chốt mở bước ngoặt Tây Nguyên; hoạt động chiến dịch bắt đầu trước đó.", "topic": "1975 · Giải phóng miền Nam", "extra": false, "review": true, "tier": 8, "sources": [], "hint": "Tìm trận then chốt đánh vào vị trí bất ngờ ở Tây Nguyên đầu tháng 3; đọc lưu ý về ngày mở chiến dịch."}, {"chapter": 2, "number": 121, "id": "415507737", "question": "Ý nghĩa lịch sử quan trọng nhất của cuộc kháng chiến chống Mỹ cứu nước (1954-1975) đối với nhân dân Việt Nam là?", "options": ["Hoàn thành cuộc cách mạng dân tộc dân chủ nhân dân trong cả nước", "Tạo điều kiện để cả nước đi lên CNXH", "Là nguồn cổ vũ với phong trào cách mạng thế giới", "Làm đảo lộn chiến lược toàn cầu của Mỹ"], "answer": "A", "key": "2.121", "explanation": "1975 → hoàn thành cách mạng dân tộc dân chủ nhân dân trong cả nước.", "topic": "1975 · Giải phóng miền Nam", "extra": false, "review": false, "tier": 7, "sources": [], "hint": "Chọn kết quả tổng quát cho dân tộc, vượt lên ý nghĩa của một chiến dịch riêng lẻ."}, {"chapter": 2, "number": 122, "id": "415507738", "question": "Nguyên nhân quyết định tới thắng lợi của cuộc kháng chiến chống Mỹ cứu nước (1954-1975) là?", "options": ["Sự chi viện của hậu phương miền Bắc", "Sự đoàn kết của nhân dân ba nước Đông Dương và sự giúp đỡ của các nước xã hội chủ nghĩa", "Sự lãnh đạo đúng đắn của Đảng Lao động Việt Nam", "Truyền thống yêu nước của nhân dân Việt Nam"], "answer": "C", "key": "2.122", "explanation": "Nhân tố quyết định → sự lãnh đạo đúng đắn của Đảng.", "topic": "1975 · Giải phóng miền Nam", "extra": false, "review": false, "tier": 7, "sources": [], "hint": "Phân biệt vai trò lãnh đạo quyết định với các nguồn sức mạnh và sự hỗ trợ khác."}, {"chapter": 2, "number": 123, "id": "415507739", "question": "Điểm giống nhau giữa chiến dịch Điện Biên Phủ (1954) và chiến dịch Hồ Chí Minh (1975) là?", "options": ["Có sự kết hợp với nổi dậy của quần chúng", "Có sự điều chỉnh phương châm tác chiếc", "Địa bàn diễn ra ở vùng rừng núi", "Là những trận quyết chiến chiến lược"], "answer": "D", "key": "2.123", "explanation": "Điện Biên Phủ và Hồ Chí Minh → đều là quyết chiến chiến lược.", "topic": "1975 · Giải phóng miền Nam", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Hai chiến dịch đều tạo kết quả quyết định vào giai đoạn cuối mỗi cuộc kháng chiến."}, {"chapter": 2, "number": 124, "id": "415507740", "question": "Điểm khác biệt lớn nhất của chiến dịch Hồ Chí Minh 1975 so với chiến dịch Điện Biên Phủ 1954 là?", "options": ["Giải phóng vùng đất đai rộng lớn", "Buộc địch phải đầu hàng không điều kiện", "Sử dụng chiến thuật đánh nhanh thắng nhanh", "Có ảnh hưởng quốc tế to lớn"], "answer": "C", "key": "2.124", "explanation": "Hồ Chí Minh 1975 → thần tốc; Điện Biên Phủ 1954 → đánh chắc, tiến chắc.", "topic": "1975 · Giải phóng miền Nam", "extra": false, "review": false, "tier": 8, "sources": [], "hint": "So tốc độ tác chiến năm 1975 với phương châm đánh chắc, tiến chắc năm 1954."}, {"chapter": 2, "number": 125, "id": "415507741", "question": "Trong 21 năm thực hiện chiến tranh ở Việt Nam (1954-1975), Mỹ đã sử dụng mấy chiến lược chiến tranh?", "options": ["2", "3", "4", "5"], "answer": "C", "key": "2.125", "explanation": "Nguồn chia 4 chiến lược → đơn phương – đặc biệt – cục bộ – Việt Nam hóa.", "topic": "1975 · Giải phóng miền Nam", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Nhớ phân kỳ của tài liệu gồm cả chiến lược trước Chiến tranh đặc biệt."}, {"chapter": 3, "number": 1, "id": "415540107", "question": "Tại kì họp đầu tiên (6/1976) của Quốc hội nước Việt Nam thống nhất đã quyết định vấn đề quan trọng gì?", "options": ["Đặt tên nước là Cộng hòa xã hội chủ nghĩa Việt Nam", "Cải cách ruộng đất trong cả nước", "Thành lập Mặt trận Việt Nam độc lập đồng minh", "Tiến hành đổi mới toàn diện đất nước"], "answer": "A", "key": "3.1", "explanation": "Quốc hội thống nhất 1976 → tên nước Cộng hòa xã hội chủ nghĩa Việt Nam.", "topic": "1975–1979 · Thống nhất & bảo vệ Tổ quốc", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Quốc hội chung quyết định danh xưng nhà nước mới, khác tên nước từ năm 1945."}, {"chapter": 3, "number": 2, "id": "415540108", "question": "Việt Nam thực hiện thống nhất đất nước về mặt nhà nước ngay sau đại thắng mùa xuân năm 1975 vì:", "options": ["Đó là ý chí và nguyện vọng thiết tha của toàn dân tộc", "Muốn tạo sức mạnh tổng hợp để tham gia xu thế toàn cầu hóa", "Đó là một điều khoản phải thi hành của Hiệp định Pari năm 1973", "Phải hoàn thành triệt để cuộc cách mạng giải phóng dân tộc"], "answer": "A", "key": "3.2", "explanation": "Thống nhất nhà nước → nguyện vọng chung sau khi lãnh thổ thống nhất.", "topic": "1975–1979 · Thống nhất & bảo vệ Tổ quốc", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Sau thống nhất lãnh thổ, cần thực hiện nguyện vọng chung về một bộ máy nhà nước thống nhất."}, {"chapter": 3, "number": 3, "id": "415540109", "question": "Nội dung nào dưới đây là điều kiện thuận lợi của Việt Nam ngay sau đại thắng mùa Xuân 1975?", "options": ["Đất nước đã thống nhất về mặt lãnh thổ", "Hậu quả chiến tranh đã khắc phục xong", "Mỹ đã bình thường hóa quan hệ với Việt Nam", "Nền kinh tế bước đầu có tích lũy nội bộ"], "answer": "A", "key": "3.3", "explanation": "Sau 30/4/1975 → đã thống nhất lãnh thổ, tạo thuận lợi cơ bản.", "topic": "1975–1979 · Thống nhất & bảo vệ Tổ quốc", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Phân biệt điều kiện thuận lợi sẵn có sau chiến thắng với khó khăn kinh tế để lại."}, {"chapter": 3, "number": 4, "id": "415540110", "question": "Hoàn cảnh lịch sử Việt Nam sau ngày 30/4/1975?", "options": ["Đất nước hòa bình, độc lập", "Đất nước thống nhất", "Cả nước quá độ lên CNXH", "Tất cả các đáp án trên"], "answer": "D", "key": "3.4", "explanation": "1975 → hòa bình, độc lập, thống nhất lãnh thổ và điều kiện cả nước quá độ lên CNXH.", "topic": "1975–1979 · Thống nhất & bảo vệ Tổ quốc", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Xem các phương án có cùng phản ánh bước chuyển chung của đất nước sau chiến thắng không."}, {"chapter": 3, "number": 5, "id": "415540111", "question": "Sau đại thắng mùa xuân năm 1975, Đảng CSVN xác định nhiệm vụ đầu tiên, bức thiết nhất lúc này cần phải làm là gì?", "options": ["Xây dựng kinh tế", "Thống nhất nước nhà về mặt nhà nước", "Phát triển văn hóa - xã hội", "Củng cố quốc phòng - an ninh"], "answer": "B", "key": "3.5", "explanation": "Việc cấp thiết → thống nhất về mặt nhà nước, hoàn thiện sự thống nhất.", "topic": "1975–1979 · Thống nhất & bảo vệ Tổ quốc", "extra": false, "review": false, "tier": 7, "sources": [], "hint": "Phân biệt đã thống nhất lãnh thổ với còn cần hoàn tất thống nhất bộ máy quyền lực."}, {"chapter": 3, "number": 6, "id": "415540112", "question": "Khó khăn cơ bản nhất của Việt Nam sau năm 1975 là gì?", "options": ["Mù chữ và thất nghiệp chiếm tỷ lệ cao", "Phản động trong nước vẫn còn", "Nông nghiệp lạc hậu", "Hậu quả nặng nề của chiến tranh"], "answer": "D", "key": "3.6", "explanation": "Hậu quả chiến tranh → khó khăn lớn về con người, cơ sở vật chất và kinh tế.", "topic": "1975–1979 · Thống nhất & bảo vệ Tổ quốc", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Chiến tranh kéo dài để lại thiệt hại lớn về con người, hạ tầng và nền kinh tế."}, {"chapter": 3, "number": 7, "id": "415540113", "question": "Nhiệm vụ trọng tâm của miền Bắc ngay sau năm 1975 là?", "options": ["Hàn gắn vết thương chiến tranh", "Khắc phục hậu quả chiến tranh, khôi phục và phát triển kinh tế, văn hóa", "Tiếp tục làm nhiệm vụ căn cứ địa của cách mạng cả nước", "Tiếp tục làm nghĩa vụ quốc tế với Lào và Campuchia"], "answer": "B", "key": "3.7", "explanation": "Miền Bắc → khắc phục hậu quả chiến tranh, khôi phục kinh tế và văn hóa.", "topic": "1975–1979 · Thống nhất & bảo vệ Tổ quốc", "extra": false, "review": false, "tier": 7, "sources": [], "hint": "Miền Bắc vừa trải qua chiến tranh phá hoại, nên cần ưu tiên phục hồi đời sống và sản xuất."}, {"chapter": 3, "number": 8, "id": "415540114", "question": "Ngày 25/4/1976 ở Việt Nam diễn ra sự kiện quan trọng gì?", "options": ["Tổng tuyển cử trên toàn lãnh thổ miền Nam", "Bầu Quốc hội chung của cả nước", "Tổng tuyển cử trên toàn lãnh thổ Việt Nam, bầu Quốc hội chung của cả nước", "Ban hành Hiến pháp"], "answer": "C", "key": "3.8", "explanation": "25/4/1976 → bầu Quốc hội chung trên cả nước.", "topic": "1975–1979 · Thống nhất & bảo vệ Tổ quốc", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Mốc tháng 4 gắn với lá phiếu của người dân, trước kỳ họp Quốc hội chung."}, {"chapter": 3, "number": 9, "id": "415540115", "question": "Cuộc Tổng tuyển cử bầu Quốc hội chung trong cả nước (25/4/1976) có ý nghĩa nghĩa như thế nào đối với nước ta?", "options": ["Lần thứ 2 cuộc tổng tuyển cử được tổ chức trong cả nước", "Kết quả thắng lợi của 30 năm chiến tranh giữ nước (1945-1975)", "Là một bước quan trọng cho sự thống nhất đất nước về mặt Nhà nước", "Tất cả các đáp án trên"], "answer": "D", "key": "3.9", "explanation": "Tổng tuyển cử chung → kết quả của đấu tranh thống nhất, bước lớn thống nhất nhà nước.", "topic": "1975–1979 · Thống nhất & bảo vệ Tổ quốc", "extra": false, "review": false, "tier": 7, "sources": [], "hint": "Xét cả tính kế thừa, thành quả đấu tranh và bước tiến về thống nhất nhà nước."}, {"chapter": 3, "number": 10, "id": "415540116", "question": "Thành phố Sài Gòn được Quốc hội đặt tên là Thành phố Hồ Chí Minh từ năm nào?", "options": ["Năm 1974", "Năm 1975", "Năm 1976", "Năm 1977"], "answer": "C", "key": "3.10", "explanation": "1976 → Sài Gòn mang tên Thành phố Hồ Chí Minh.", "topic": "1975–1979 · Thống nhất & bảo vệ Tổ quốc", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Đổi tên thành phố được quyết định cùng thời kỳ hoàn tất thống nhất nhà nước."}, {"chapter": 3, "number": 11, "id": "415540117", "question": "Tại kỳ họp thứ nhất của Quốc hội nước Việt Nam thống nhất đã có những quyết định quan trọng nào liên quan với việc thống nhất đất nước về mặt Nhà nước?", "options": ["Thống nhất tên nước, xác định Hà Nội là thủ đô của cả nước", "Bầu các cơ quan lãnh đạo cao nhất của cả nước", "Đổi tên thành phố Sài Gòn - Gia Định là Thành phố Hồ Chí Minh", "Thống nhất tên nước, xác định Hà Nội là thủ đô của cả nước và bầu các chức danh lãnh đạo cấp cao của Nhà nước"], "answer": "D", "key": "3.11", "explanation": "Quốc hội chung → quyết tên nước, thủ đô, các chức danh lãnh đạo.", "topic": "1975–1979 · Thống nhất & bảo vệ Tổ quốc", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Tìm nhóm quyết định thể hiện biểu tượng và tổ chức của một quốc gia thống nhất."}, {"chapter": 3, "number": 12, "id": "415540118", "question": "Người được bầu làm Chủ tịch đầu tiên của nước Cộng hòa xã hội chủ nghĩa Việt Nam là ai?", "options": ["Hồ Chí Minh", "Tôn Đức Thắng", "Nguyễn Lương Bằng", "Trần Đức Lương"], "answer": "B", "key": "3.12", "explanation": "Chủ tịch nước CHXHCN Việt Nam đầu tiên → Tôn Đức Thắng.", "topic": "1975–1979 · Thống nhất & bảo vệ Tổ quốc", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Nhớ vị lãnh đạo kế nhiệm Chủ tịch Hồ Chí Minh từ năm 1969."}, {"chapter": 3, "number": 13, "id": "415540119", "question": "Đại hội ĐBTQ lần thứ IV của Đảng được họp vào thời gian nào?", "options": ["Tháng 5/1974", "Tháng 10/1975", "Tháng 12/1976", "Tháng 12/1986"], "answer": "C", "key": "3.13", "explanation": "Đại hội IV → tháng 12/1976, sau thống nhất.", "topic": "1975–1979 · Thống nhất & bảo vệ Tổ quốc", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Đại hội diễn ra cuối năm hoàn tất thống nhất nhà nước, không phải ngay sau 30/4/1975."}, {"chapter": 3, "number": 14, "id": "415540120", "question": "Đại hội lần thứ IV của Đảng (1976) đã nêu ra đặc điểm nổi bật của cách mạng Việt Nam trong giai đoạn mới là?", "options": ["Nước ta đang trong quá trình phát triển kinh tế một cách bền vững, đa nghề", "Nước ta đang trong quá trình hoàn thành giai đoạn quá độ, chuẩn bị tiến lên CNXH", "Nước ta đã hoàn thành giai đoạn xây dựng chủ nghĩa xã hội, chuẩn bị tiến lên chủ nghĩa cộng sản", "Nước ta đang trong quá trình từ sản xuất nhỏ tiến thẳng lên CNXH, bỏ qua giai đoạn phát triển tư bản chủ nghĩa"], "answer": "D", "key": "3.14", "explanation": "Đại hội IV → xuất phát sản xuất nhỏ, tiến lên CNXH bỏ qua giai đoạn phát triển TBCN.", "topic": "1975–1979 · Thống nhất & bảo vệ Tổ quốc", "extra": false, "review": false, "tier": 7, "sources": [], "hint": "Chú ý trình độ xuất phát thấp của nền sản xuất và con đường quá độ được xác định."}, {"chapter": 3, "number": 15, "id": "415540121", "question": "Nội dung nào không phản ánh đúng quyết định của Đại hội toàn quốc lần thứ IV của Đảng (1976)?", "options": ["Đổi tên Đảng Lao động Việt Nam thành Đảng Cộng sản Việt Nam", "Đề ra đường lối xây dựng chủ nghĩa xã hội trong cả nước", "Đề ra kế hoạch phát triển kinh tế và văn hóa (1976-1980)", "Thực hiện đường lối đổi mới toàn diện đất nước đi lên CNXH"], "answer": "D", "key": "3.15", "explanation": "Câu phủ định: đổi mới toàn diện thuộc Đại hội VI năm 1986, không phải IV.", "topic": "1975–1979 · Thống nhất & bảo vệ Tổ quốc", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Câu phủ định: đừng đưa đường lối được khởi xướng mười năm sau vào đại hội này."}, {"chapter": 3, "number": 16, "id": "415540122", "question": "Trong giai đoạn 10 năm (1976-1986) Việt Nam vừa xây dựng chủ nghĩa xã hội vừa thực hiện những cuộc đấu tranh nào?", "options": ["Bảo vệ Tổ Quốc ở biên giới Đông Nam và Tây Nam", "Bảo vệ Tổ Quốc ở biên giới phía Bắc và Tây Nam", "Chống lại sự xâm nhập của tập đoàn Khơ me đỏ ở phía Bắc", "Chống lại sự tấn công của Trung Quốc ở phía Tây Nam"], "answer": "B", "key": "3.16", "explanation": "1976–1986 → vừa xây dựng vừa bảo vệ biên giới Bắc và Tây Nam.", "topic": "1975–1979 · Thống nhất & bảo vệ Tổ quốc", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Trong thời kỳ hòa bình xây dựng, đất nước vẫn phải đối phó chiến tranh ở hai hướng biên giới."}, {"chapter": 3, "number": 17, "id": "415540123", "question": "Theo Hiệp ước Hòa bình, hữu nghị và hợp tác giữa Việt Nam và Campuchia (18/2/1979), quân đội Việt Nam có mặt ở Campuchia giúp bạn bảo vệ độc lập và hồi sinh đất nước. Hành động đó được coi là?", "options": ["Hành động xâm lược Campuchia", "Hành động chống phá nước bạn", "Hành động chính nghĩa và xuất phát từ nhu cầu tự vệ chính đáng của nước bạn", "Hành động nhằm tàn sát, phá hoại nước bạn"], "answer": "C", "key": "3.17", "explanation": "Theo giáo trình → giúp Campuchia bảo vệ độc lập, thực hiện nghĩa vụ quốc tế.", "topic": "1975–1979 · Thống nhất & bảo vệ Tổ quốc", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Đặt hành động trong quan hệ tương trợ và yêu cầu bảo vệ đất nước của Campuchia theo giáo trình."}, {"chapter": 3, "number": 18, "id": "415540124", "question": "Nội dung nào sau đây không phải là hành động của Trung Quốc trong quan hệ ngoại giao với Việt Nam vào cuối năm 1978 đầu năm 1979?", "options": ["Cho quân khiêu khích dọc biên giới phía Bắc của Việt Nam", "Dựng lên sự kiện “nạn kiều”", "Cắt viện trợ, rút hết các chuyên gia về nước", "Giúp đỡ Việt Nam trong cuộc đấu tranh bảo vệ biên giới Tây Nam"], "answer": "D", "key": "3.18", "explanation": "Câu phủ định: không coi Trung Quốc giúp Việt Nam bảo vệ biên giới Tây Nam thời điểm này.", "topic": "1975–1979 · Thống nhất & bảo vệ Tổ quốc", "extra": false, "review": false, "tier": 8, "sources": [], "hint": "Câu phủ định: loại phương án trái với tình hình xung đột khu vực cuối thập niên 1970."}, {"chapter": 3, "number": 19, "id": "415540125", "question": "Thắng lợi của cuộc chiến đấu bảo vệ biên giới phía Bắc (1979) có ý nghĩa như thế nào đối với Việt Nam?", "options": ["Tạo ra bước ngoặt để cả nước tiến hành đổi mới toàn diện đất nước", "Bảo vệ vững chắc vùng biên giới phía Bắc của nhân dân ta", "Hoàn thành cuộc cách mạng xã hội chủ nghĩa trên cả nước", "Đưa đất nước vào thời kỳ bình ổn, tăng trưởng nhanh về kinh tế"], "answer": "B", "key": "3.19", "explanation": "1979 → bảo vệ chủ quyền và vùng biên giới phía Bắc.", "topic": "1975–1979 · Thống nhất & bảo vệ Tổ quốc", "extra": false, "review": false, "tier": 7, "sources": [], "hint": "Ý nghĩa trước hết nằm ở việc giữ gìn lãnh thổ và cuộc sống của nhân dân vùng bị tấn công."}, {"chapter": 3, "number": 20, "id": "415540126", "question": "Bước đột phá đầu tiên trong đổi mới kinh tế của Đảng với chủ trương phá bỏ những rào cản để cho “sản xuất bung ra” được đề ra tại Hội nghị Trung ương nào?", "options": ["Hội nghị Trung ương 6 (1979)", "Hội nghị Trung ương 6 (1984)", "Hội nghị Trung ương 6 (1989)", "Hội nghị Trung ương 6 (1994)"], "answer": "A", "key": "3.20", "explanation": "Trung ương 6 năm 1979 → đột phá thứ nhất, sản xuất bung ra.", "topic": "1979–1986 · Tìm tòi đổi mới", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Nhớ bước tìm tòi đổi mới đầu tiên trước Khoán 100 và cải cách giá–lương–tiền."}, {"chapter": 3, "number": 21, "id": "415540127", "question": "Chỉ thị 100 CT/TW của Ban Bí thư Trung ương Đảng (1/1981) đã đưa ra chủ trương nào sau đây?", "options": ["Khoán sản phẩm đến nhóm và người lao động trong hợp tác xã nông nghiệp", "Cải cách ruộng đất", "Đổi mới toàn diện đất nước", "Tất cả các đáp án trên"], "answer": "A", "key": "3.21", "explanation": "Chỉ thị 100 → khoán đến nhóm và người lao động trong hợp tác xã.", "topic": "1979–1986 · Tìm tòi đổi mới", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Phân biệt đơn vị nhận khoán trong Chỉ thị 100 với bước phát triển tới hộ của Khoán 10."}, {"chapter": 3, "number": 22, "id": "415540128", "question": "Chiến thắng chiến tranh biên giới Tây Nam (1978) của quân dân ta có ý nghĩa như thế nào?", "options": ["Tạo thời cơ thuận lợi cho cách mạng Campuchia giành thắng lợi", "Tăng cường tính đoàn kết của nhân dân 3 nước Đông Dương", "Tạo nên sức mạnh tổng hợp của nhân dân hai nước Việt Nam và Campuchia", "Đánh vào âm mưu chống phá của quân Trung Quốc"], "answer": "A", "key": "3.22", "explanation": "Tây Nam → tạo điều kiện cho cách mạng Campuchia lật đổ chế độ diệt chủng.", "topic": "1979–1986 · Tìm tòi đổi mới", "extra": false, "review": false, "tier": 7, "sources": [], "hint": "Xét tác động tới khả năng nhân dân Campuchia thoát khỏi chế độ diệt chủng."}, {"chapter": 3, "number": 23, "id": "415540129", "question": "Chỉ thị 100 CT/TW của Ban Bí thư Trung ương Đảng về khoán sản phẩm đến nhóm và người lao động trong hợp tác xã được ban hành vào năm nào?", "options": ["1980", "1981", "1988", "1989"], "answer": "B", "key": "3.23", "explanation": "Khoán 100 → năm 1981; đừng nhầm Khoán 10 năm 1988.", "topic": "1979–1986 · Tìm tòi đổi mới", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Chỉ thị này xuất hiện trước Đại hội V một năm, không phải năm ban hành Khoán 10."}, {"chapter": 3, "number": 24, "id": "415540130", "question": "Những khó khăn, thách thức mới trong công cuộc xây dựng CNXH và bảo vệ Tổ quốc 1976-1981 là gì?", "options": ["Tiến hành CNH, HĐH trên phạm vi miền Bắc", "Tiến hành CNH, HĐH trên phạm vi cả nước", "Các thế lực thù địch bao vây cấm vận và phá hoại sự phát triển của Việt Nam", "Tất cả các đáp án trên"], "answer": "C", "key": "3.24", "explanation": "Bao vây, cấm vận → trở ngại từ bên ngoài khi xây dựng đất nước.", "topic": "1979–1986 · Tìm tòi đổi mới", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Tìm trở ngại từ chính sách đối ngoại, kinh tế của các thế lực bên ngoài."}, {"chapter": 3, "number": 25, "id": "415540131", "question": "Giai đoạn 1976-1981, quân và dân cả nước đã giành được những thành tựu nổi bật nào?", "options": ["Hoàn thành thống nhất đất nước về mặt nhà nước", "Chiến thắng trong hai cuộc chiến tranh biên giới", "Đã khắc phục được một phần hậu quả chiến tranh và thiên tai", "Tất cả các đáp án trên"], "answer": "D", "key": "3.25", "explanation": "Ba thành tựu → thống nhất nhà nước, bảo vệ biên giới, khắc phục một phần hậu quả.", "topic": "1979–1986 · Tìm tòi đổi mới", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Xem đủ ba mặt: thống nhất nhà nước, bảo vệ chủ quyền và khắc phục thiệt hại."}, {"chapter": 3, "number": 26, "id": "415540132", "question": "Những khó khăn, thách thức của Việt Nam trong giai đoạn 1975- 1981 là do?", "options": ["Do chiến tranh kéo dài", "Do tiến hành quá lâu nền kinh tế kế hoạch hóa tập trung quan liêu bao cấp", "Do Mỹ bao vây, cô lập và cấm vận kinh tế Việt Nam", "Tất cả các đáp án trên"], "answer": "D", "key": "3.26", "explanation": "Ba sức ép → hậu quả chiến tranh, cơ chế bao cấp, bao vây cấm vận.", "topic": "1979–1986 · Tìm tòi đổi mới", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Khó khăn có cả di sản chiến tranh, cơ chế quản lý và sức ép quốc tế."}, {"chapter": 3, "number": 27, "id": "415540133", "question": "Đại hội ĐBTQ lần thứ V của Đảng (1982) đã họp trong hoàn cảnh thế giới và trong nước có những khó khăn, thách thức gì?", "options": ["Hoa Kỳ tiếp tục thực hiện chính sách bao vây cấm vận và “kế hoạch hậu chiến”", "Chủ nghĩa đế quốc và các thế lực phản động quốc tế ra sức tuyên truyền xuyên tạc việc quân tình nguyện Việt Nam làm nghĩa vụ quốc tế ở Campuchia", "Trong nước tình trạng khủng hoảng kinh tế - xã hội ở nước ta ngày càng trầm trọng", "Tất cả các đáp án trên"], "answer": "D", "key": "3.27", "explanation": "Đại hội V → cấm vận và chống phá từ ngoài, khủng hoảng kinh tế trong nước.", "topic": "1979–1986 · Tìm tòi đổi mới", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Đại hội diễn ra khi khủng hoảng trong nước chồng lên cấm vận và bất lợi đối ngoại."}, {"chapter": 3, "number": 28, "id": "415540134", "question": "Đại hội ĐBTQ lần thứ V của Đảng (1982) đã thống nhất bầu ai là Tổng Bí thư của Đảng?", "options": ["Đ/c Lê Duẩn", "Đ/c Nguyễn Văn Linh", "Đ/c Lê Khả Phiêu", "Đ/c Trường Chinh"], "answer": "A", "key": "3.28", "explanation": "Đại hội V năm 1982 → Tổng Bí thư Lê Duẩn.", "topic": "1979–1986 · Tìm tòi đổi mới", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Nhớ vị lãnh đạo tiếp tục giữ chức sau Đại hội IV, trước thời đổi mới."}, {"chapter": 3, "number": 29, "id": "415540135", "question": "Đại hội ĐBTQ lần thứ V của Đảng (1982) đã xác định mặt trận hàng đầu trong chặng đường đầu tiên của thời kỳ quá độ lên CNXH là gì?", "options": ["Công nghiệp", "Nông nghiệp", "Công nghiệp nhẹ", "Tất cả các đáp án trên"], "answer": "B", "key": "3.29", "explanation": "Đại hội V → nông nghiệp là mặt trận hàng đầu.", "topic": "1979–1986 · Tìm tòi đổi mới", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Chọn lĩnh vực bảo đảm lương thực và sinh kế cho phần đông dân cư."}, {"chapter": 3, "number": 30, "id": "415540136", "question": "Đại hội ĐBTQ lần thứ V của Đảng (1982) xác định: Nội dung, bước đi, cách làm để thực hiện công nghiệp hóa XHCN trong chặng đường đầu tiên là gì?", "options": ["Tập trung sức phát triển mạnh nông nghiệp, coi nông nghiệp là mặt trận hàng đầu, đưa nông nghiệp một bước lên sản xuất lớn XHCN", "Ra sức đẩy mạnh sản xuất hàng tiêu dùng; tiếp tục xây dựng một số ngành công nghiệp nặng quan trọng", "Kết hợp nông nghiệp với công nghiệp (công nghiệp hàng tiêu dùng và công nghiệp nặng) thành cơ cấu công - nông nghiệp hợp lý", "Tất cả các đáp án trên"], "answer": "D", "key": "3.30", "explanation": "Cơ cấu công–nông nghiệp → nông nghiệp + hàng tiêu dùng + công nghiệp nặng phù hợp.", "topic": "1979–1986 · Tìm tòi đổi mới", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Đại hội chủ trương kết hợp các ngành phù hợp điều kiện chặng đường đầu, không tuyệt đối một ngành."}, {"chapter": 3, "number": 31, "id": "415540137", "question": "Đại hội ĐBTQ lần thứ V của Đảng (1982) khẳng định: Chặng đường trước mắt trong những năm 80 là gì?", "options": ["Ổn định và cải thiện một bước đời sống vật chất, văn hóa của nhân dân", "Tiếp tục xây dựng cơ sở vật chất - kỹ thuật của CNXH. Thúc đẩy sản xuất nông nghiệp, hàng tiêu dùng và hàng xuất khẩu", "Đáp ứng nhu cầu quốc phòng, giữ vững an ninh, trật tự xã hội", "Tất cả các đáp án trên"], "answer": "D", "key": "3.31", "explanation": "Nhiệm vụ những năm 80 → đời sống, cơ sở vật chất, quốc phòng và an ninh.", "topic": "1979–1986 · Tìm tòi đổi mới", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Nhiệm vụ bao gồm đời sống nhân dân, cơ sở vật chất và bảo đảm quốc phòng, an ninh."}, {"chapter": 3, "number": 32, "id": "415540138", "question": "Đại hội ĐBTQ lần thứ V của Đảng (1982) đã có những bước phát triển trong nhận thức mới, trước hết là trong lĩnh vực gì?", "options": ["Văn hóa - Xã hội", "Chính trị, An ninh quốc phòng", "Kinh tế", "Tất cả các đáp án trên"], "answer": "C", "key": "3.32", "explanation": "Nhận thức mới tại Đại hội V → trước hết trong lĩnh vực kinh tế.", "topic": "1979–1986 · Tìm tòi đổi mới", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Bước phát triển nhận thức trước hết gắn với tổ chức sản xuất và quản lý nguồn lực."}, {"chapter": 3, "number": 33, "id": "415540139", "question": "Hội nghị Trung ương 8 (6/1985) được coi là bước đột phá thứ hai trong quá trình tìm tòi, đổi mới kinh tế của Đảng. Tại hội nghị này, Trung ương Đảng đã đưa ra quyết định quan trọng gì?", "options": ["Đổi mới toàn diện đất nước trong các ngành, lĩnh vực", "Xóa bỏ cơ chế tập trung quan liêu, bao cấp chuyển sang cơ chế hạch toán kinh doanh", "Đề ra mục tiêu đến năm 2020 nước ta trở thành nước công nghiệp hiện đại", "Chủ trương chuyển dùng tem phiếu sang dùng tiền mặt"], "answer": "B", "key": "3.33", "explanation": "Trung ương 8 năm 1985 → đột phá thứ hai, xóa tập trung bao cấp, chuyển hạch toán.", "topic": "1979–1986 · Tìm tòi đổi mới", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Bước đột phá thứ hai nhắm vào thay đổi cơ chế quản lý bao cấp, không chỉ một ngành sản xuất."}, {"chapter": 3, "number": 34, "id": "415540140", "question": "Hội nghị Bộ Chính trị khóa V (8/1986) được coi như bước đột phá thứ 3 về đổi mới kinh tế của Đảng. Hội nghị đã nhận định đặc trưng của thời kì quá độ lên CNXH ở nước ta là:", "options": ["Nền kinh tế có cơ cấu nhiều thành phần", "Nền kinh tế chủ yếu dựa vào các doanh nghiệp nhà nước", "Nền kinh tế lấy tự cung, tự cấp làm nền tảng", "Nền kinh tế sản xuất hàng hóa nhỏ"], "answer": "A", "key": "3.34", "explanation": "Bộ Chính trị tháng 8/1986 → đột phá thứ ba, thừa nhận cơ cấu nhiều thành phần.", "topic": "1979–1986 · Tìm tòi đổi mới", "extra": false, "review": false, "tier": 7, "sources": [], "hint": "Nhận định về cơ cấu sở hữu, thành phần kinh tế trước thềm Đại hội VI."}, {"chapter": 3, "number": 35, "id": "415540141", "question": "Tổng kết 10 năm xây dựng CNXH trên phạm vi cả nước (1976-1986), cách mạng Việt Nam đã đạt một số thành tựu nổi bật, một trong số đó là?", "options": ["Nền kinh tế có bước đột phá vượt bậc, đời sống nhân dân ngày càng được cải thiện", "Đưa tỷ lệ lạm phát xuống thấp kỉ lục", "Dành thắng lợi to lớn trong sự nghiệp bảo vệ Tổ quốc và làm nghĩa vụ quốc tế", "Có mối quan hệ ngoại giao với hầu hết các quốc gia trên thế giới"], "answer": "C", "key": "3.35", "explanation": "1976–1986 → thành tựu nổi bật là bảo vệ Tổ quốc, làm nghĩa vụ quốc tế.", "topic": "1979–1986 · Tìm tòi đổi mới", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Tìm thành tựu dù kinh tế còn khủng hoảng: bảo vệ chủ quyền và thực hiện nghĩa vụ quốc tế."}, {"chapter": 3, "number": 36, "id": "415540142", "question": "Nguyên nhân khách quan dẫn đến những khủng hoảng kinh tế - xã hội giai đoạn 1976-1986 là do?", "options": ["Sai lầm của Đảng trong đánh giá tình hình, mục tiêu và bước đi", "Xây dựng đất nước từ một nền kinh tế nghèo nàn, lạc hậu, bị bao vây, cấm vận nhiều năm", "Đảng duy trì quá lâu cơ chế quản lý tập trung quan liêu bao cấp", "Cả ba đáp án trên"], "answer": "B", "key": "3.36", "explanation": "Nguyên nhân KHÁCH QUAN → điểm xuất phát nghèo, lạc hậu và bị cấm vận.", "topic": "1979–1986 · Tìm tòi đổi mới", "extra": false, "review": false, "tier": 7, "sources": [], "hint": "Đề hỏi KHÁCH QUAN; loại những sai lầm lãnh đạo hoặc quản lý thuộc yếu tố chủ quan."}, {"chapter": 3, "number": 37, "id": "415540143", "question": "Bối cảnh nào tác động mạnh mẽ nhất tới quyết định tiến hành công cuộc đổi mới toàn diện đất nước mà Đại hội lần thứ VI của Đảng (1986) đã thông qua?", "options": ["Cuộc cách mạng khoa học - kỹ thuật đang phát triển mạnh mẽ trên thế giới", "Trên thế giới, xu thế đối thoại đang dần thay cho xu thế đối đầu", "Liên Xô và các nước xã hội chủ nghĩa đều tiến hành cải tổ sự nghiệp xây dựng chủ nghĩa xã hội", "Những khủng hoảng trầm trọng về kinh tế - xã hội ở Việt Nam"], "answer": "D", "key": "3.37", "explanation": "Khủng hoảng kinh tế–xã hội → yêu cầu cấp thiết phải đổi mới toàn diện.", "topic": "1986–1990 · Đại hội VI & đổi mới", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Động lực cấp bách nhất xuất phát từ tình trạng trong nước, không chỉ từ xu thế quốc tế."}, {"chapter": 3, "number": 38, "id": "415540144", "question": "Tinh thần “Nhìn thẳng vào sự thật, đánh giá đúng sự thật, nói rõ sự thật” là của Đại hội lần thứ mấy?", "options": ["Đại hội lần thứ III (1960)", ". Đại hội lần thứ V (1982)", "Đại hội lần thứ VI (1986)", "Đại hội lần thứ XII (2016)"], "answer": "C", "key": "3.38", "explanation": "Nhìn thẳng sự thật → tinh thần Đại hội VI năm 1986.", "topic": "1986–1990 · Đại hội VI & đổi mới", "extra": false, "review": false, "tier": 7, "sources": [], "hint": "Khẩu hiệu gắn với đại hội khởi xướng đổi mới, thẳng thắn nhìn nhận khuyết điểm."}, {"chapter": 3, "number": 39, "id": "415540145", "question": "Tại Đại hội lần thứ VI (1986), Đảng Cộng sản Việt Nam đã chỉ ra những sai lầm, khuyết điểm trong lãnh đạo, chỉ đạo ở thời kỳ 1975-1986, đâu là khuyết điểm quyết định nhất?", "options": ["Những sai lầm nghiêm trọng và kéo dài về chủ trương, chính sách lớn", "Những sai lầm nghiêm trọng về chỉ đạo chiến lược và tổ chức thực hiện", "Do chủ quan duy ý chí, suy nghĩ và hành động giản đơn, nóng vội, chạy theo nguyện vọng chủ quan", "Những khuyết điểm trong hoạt động tư tưởng, tổ chức và công tác cán bộ của Đảng"], "answer": "D", "key": "3.39", "explanation": "Đại hội VI chỉ ra hạn chế quyết định ở tư tưởng, tổ chức và cán bộ.", "topic": "1986–1990 · Đại hội VI & đổi mới", "extra": false, "review": false, "tier": 7, "sources": [], "hint": "Đề hỏi khuyết điểm quyết định: xét mặt tư tưởng, tổ chức và đội ngũ chịu trách nhiệm lãnh đạo."}, {"chapter": 3, "number": 40, "id": "415540146", "question": "Đường lối đổi mới toàn diện, đưa đất nước ra khỏi khủng hoảng kinh tế - xã hội được đưa ra tại Đại hội lần thứ mấy?", "options": ["Đại hội lần thứ V (1982)", "Đại hội lần thứ VI (1986)", "Đại hội lần thứ VII (1991)", "Đại hội lần thứ VIII (1996)"], "answer": "B", "key": "3.40", "explanation": "Đại hội VI năm 1986 → khởi xướng đường lối đổi mới toàn diện.", "topic": "1986–1990 · Đại hội VI & đổi mới", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Nhớ mốc mở đầu đổi mới toàn diện, khác các bước tìm tòi trước đó."}, {"chapter": 3, "number": 41, "id": "415540147", "question": "Đại hội đại biểu toàn quốc lần thứ VI của Đảng (1986) bầu đồng chí nào làm     Tổng Bí thư?", "options": ["Đ/c Lê Duẩn", "Đ/c Trường Chinh", "Đ/c Võ Văn Kiệt", "Đ/c Nguyễn Văn Linh"], "answer": "D", "key": "3.41", "explanation": "Đại hội VI → Nguyễn Văn Linh làm Tổng Bí thư.", "topic": "1986–1990 · Đại hội VI & đổi mới", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Nhớ nhà lãnh đạo gắn với Đại hội mở đầu đổi mới và Những việc cần làm ngay."}, {"chapter": 3, "number": 42, "id": "415540148", "question": "Đại hội đại biểu toàn quốc lần thứ VI của Đảng (1986) là Đại hội của …?", "options": ["Công cuộc xây dựng CNXH", "Xây dựng và phát triển kinh tế", "Công cuộc đổi mới toàn diện đất nước", "Xây dựng và chỉnh đốn Đảng"], "answer": "C", "key": "3.42", "explanation": "Đại hội VI → đại hội mở đầu công cuộc đổi mới toàn diện.", "topic": "1986–1990 · Đại hội VI & đổi mới", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Tìm tính chất nổi bật của đại hội năm 1986, không nhầm với công nghiệp hóa hay thống nhất."}, {"chapter": 3, "number": 43, "id": "415540149", "question": "Đại hội lần thứ VI của Đảng (1986) đã xác định rõ quan điểm đổi mới của Đảng Cộng sản Việt Nam là đổi mới toàn diện và đồng bộ, nhưng quan trọng nhất là gì?", "options": ["Đổi mới về chính trị", "Đổi mới về kinh tế và chính trị", "Đổi mới về kinh tế", "Đổi mới về văn hóa"], "answer": "C", "key": "3.43", "explanation": "Đổi mới đồng bộ → lấy đổi mới kinh tế làm trọng tâm.", "topic": "1986–1990 · Đại hội VI & đổi mới", "extra": false, "review": false, "tier": 7, "sources": [], "hint": "Chú ý trọng tâm đổi mới trong điều kiện khủng hoảng sản xuất, phân phối và đời sống."}, {"chapter": 3, "number": 44, "id": "415540150", "question": "Đại hội lần thứ VI của Đảng (1986) đã xác định nhiệm vụ bao trùm, mục tiêu tổng quát cho chặng đường đầu tiên của thời kỳ quá độ lên chủ nghĩa xã hội ở Việt Nam. Theo đó, nhiệm vụ nào được chú trọng đặc biệt ?", "options": ["Sản xuất đủ tiêu dùng và có tích lũy", "Bước đầu tạo ra một cơ cấu kinh tế hợp lý", "Thực hiện ba chương trình kinh tế lớn là lương thực - thực phẩm, hàng tiêu dùng và hàng xuất khẩu", "Đổi mới cơ chế quản lý, xóa bỏ cơ chế tập trung quan liêu hành chính bao cấp, chuyển sang hạch toán kinh doanh, kết hợp kế hoạch với thị trường"], "answer": "C", "key": "3.44", "explanation": "Ba chương trình → lương thực–thực phẩm, hàng tiêu dùng, hàng xuất khẩu.", "topic": "1986–1990 · Đại hội VI & đổi mới", "extra": false, "review": false, "tier": 7, "sources": [], "hint": "Nhớ bộ ba chương trình đáp ứng ăn, dùng và tạo nguồn thu ngoại tệ."}, {"chapter": 3, "number": 45, "id": "415540151", "question": "Đại hội lần thứ VI của Đảng (1986) đã xác định việc đổi mới cơ chế quản lý kinh tế là để giải quyết cho được vấn đề nào dưới đây?", "options": ["Tình trạng khan hiếm trầm trọng về lương thực - thực phẩm và hàng tiêu dùng", "Những vấn đề cấp bách trong phân phối và lưu thông", "Tình trạng “xin - cho” đang diễn ra phổ biến trong nền kinh tế Việt Nam", "Đảm bảo nhu cầu củng cố quốc phòng và an ninh"], "answer": "B", "key": "3.45", "explanation": "Phân phối và lưu thông → vấn đề kinh tế cấp bách cần tháo gỡ.", "topic": "1986–1990 · Đại hội VI & đổi mới", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Xét khâu đưa sản phẩm tới người tiêu dùng và phân chia nguồn lực trong nền kinh tế."}, {"chapter": 3, "number": 46, "id": "415540152", "question": "Đại hội lần thứ VI của Đảng (1986) đã xác định việc thực hiện cải tạo xã hội chủ nghĩa thường xuyên với hình thức, bước đi thích hợp nhằm?", "options": ["Làm cho lực lượng sản xuất ở Việt Nam phát triển một cách nhanh chóng", "Làm cho quan hệ sản xuất trở lên ưu việt", "Làm cho quan hệ sản xuất phù hợp và lực lượng sản xuất phát triển", "Làm cho các chính sách xã hội được thực hiện một cách thiết thực và hiệu quả"], "answer": "C", "key": "3.46", "explanation": "Quan hệ sản xuất phải phù hợp trình độ phát triển của lực lượng sản xuất.", "topic": "1986–1990 · Đại hội VI & đổi mới", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Nguyên tắc là điều chỉnh quan hệ tổ chức sản xuất theo trình độ phát triển thực tế."}, {"chapter": 3, "number": 47, "id": "415540153", "question": "Nội dung nào sau đây không phải là một trong năm phương hướng lớn phát triển kinh tế được Đại hội lần thứ VI của Đảng (1986) thông qua?", "options": ["Bố trí lại cơ cấu sản xuất", "Điều chỉnh cơ cấu đầu tư xây dựng và củng cố quan hệ sản xuất xã hội chủ nghĩa", "Sử dụng và cải tạo đúng đắn các thành phần kinh tế", "Cẩn trọng trong mở rộng và nâng cao hiệu quả kinh tế đối ngoại với các nước tư bản chủ nghĩa"], "answer": "D", "key": "3.47", "explanation": "Câu phủ định: chủ trương là mở rộng, nâng hiệu quả đối ngoại kinh tế; nguồn không chọn cách diễn đạt cẩn trọng.", "topic": "1986–1990 · Đại hội VI & đổi mới", "extra": false, "review": false, "tier": 8, "sources": [], "hint": "Câu phủ định: tìm cách diễn đạt làm thu hẹp tinh thần mở rộng kinh tế đối ngoại."}, {"chapter": 3, "number": 48, "id": "415540154", "question": "Đường lối đối ngoại của Đảng được đề ra tại Đại hội lần thứ VI (1986) là gì?", "options": ["Bình thường hóa quan hệ với Trung Quốc vì lợi ích của Việt Nam", "Bình thường hóa với các nước XHCN và tăng cường tình hữu nghị, hợp tác toàn diện với Liên Xô", "Bình thường hóa quan hệ với Mỹ vì lợi ích kinh tế", "Quan hệ hữu nghị và hợp tác toàn diện với Liên Xô và các nước XHCN"], "answer": "D", "key": "3.48", "explanation": "Đại hội VI → ưu tiên quan hệ Liên Xô và các nước XHCN theo bối cảnh 1986.", "topic": "1986–1990 · Đại hội VI & đổi mới", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Đọc theo bối cảnh năm 1986, trước thời kỳ đa phương hóa quan hệ sâu rộng sau đó."}, {"chapter": 3, "number": 49, "id": "415540155", "question": "Đại hội lần thứ VI của Đảng (1986) thông qua đường lối đối ngoại, trong đó nhấn mạnh tăng cường quan hệ đặc biệt với:", "options": ["Liên Xô và các nước xã hội chủ nghĩa", "Trung Quốc", "Lào và Cămpuchia", "Các nước thuộc phong trào không liên kết"], "answer": "C", "key": "3.49", "explanation": "Quan hệ đặc biệt → Lào và Campuchia.", "topic": "1986–1990 · Đại hội VI & đổi mới", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Chú ý các nước láng giềng Đông Dương có quan hệ gắn bó đặc biệt."}, {"chapter": 3, "number": 50, "id": "415540156", "question": "Đại hội lần thứ VI của Đảng (1986) xác định đổi mới sự lãnh đạo của Đảng cần phải đổi mới tư duy, trước hết là:", "options": ["Tư duy kinh tế", "Tư duy về công tác cán bộ", "Tư duy về quan hệ đối ngoại của Việt Nam", "Tư duy về an sinh xã hội"], "answer": "A", "key": "3.50", "explanation": "Đổi mới tư duy → trước hết tư duy kinh tế.", "topic": "1986–1990 · Đại hội VI & đổi mới", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Đổi mới tư duy trước hết để giải quyết những bế tắc về sản xuất và quản lý."}, {"chapter": 3, "number": 51, "id": "415540157", "question": "Nội dung nào dưới đây không phải là thành công của Đại hội lần thứ VI (1986)?", "options": ["Đại hội đã khởi xướng đường lối đổi mới toàn diện đất nước", "Đại hội đã đánh dấu bước phát triển mới trong thời kỳ quá độ lên chủ nghĩa xã hội", "Đại hội đã đề ra các giải pháp hiệu quả tháo gỡ tình trạng rối ren trong phân phối và lưu thông", "Đại hội đã thông qua các văn kiện mang tính chất khoa học và cách mạng"], "answer": "C", "key": "3.51", "explanation": "Nguồn nhấn mạnh: Đại hội VI còn hạn chế trong giải pháp phân phối, lưu thông.", "topic": "1986–1990 · Đại hội VI & đổi mới", "extra": false, "review": false, "tier": 8, "sources": [], "hint": "Đề hỏi điều CHƯA giải quyết tốt tại đại hội, không phải mọi chủ trương đều có hiệu quả ngay."}, {"chapter": 3, "number": 52, "id": "415540158", "question": "Trong quá trình thực hiện Nghị quyết Đại hội lần thứ VI của Đảng (1986), khó khăn lớn nhất là?", "options": ["Liên Xô và các nước xã hội chủ nghĩa Đông Âu ngày càng rơi vào khủng hoảng toàn diện", "Viện trợ và quan hệ kinh tế giữa Liên Xô, các nước xã hội chủ nghĩa Đông Âu với Việt Nam bị thu hẹp nhanh chóng", "Mỹ và các thế lực thù địch tiếp tục bao vây, cấm vận, cô lập, tuyên truyền chống phá Việt Nam", "Sự dao động về tư tưởng chính trị, giảm sút niềm tin vào con đường xã hội chủ nghĩa ngày càng lan rộng trong xã hội Việt Nam"], "answer": "D", "key": "3.52", "explanation": "Biến động hệ thống XHCN → xuất hiện dao động tư tưởng và giảm niềm tin.", "topic": "1986–1990 · Đại hội VI & đổi mới", "extra": false, "review": false, "tier": 7, "sources": [], "hint": "Khó khăn này liên quan niềm tin và tư tưởng trong bối cảnh hệ thống XHCN biến động."}, {"chapter": 3, "number": 53, "id": "415540159", "question": "Việc Hội nghị Trung ương 2 (04/1987) đề ra một số biện pháp cấp bách về phân phối, lưu thông đã giải quyết được hạn chế còn tồn tại của Đại hội nào dưới đây?", "options": ["Đại hội V (1982)", "Đại hội VI (1986)", "Đại hội VII (1991)", "Đại hội VIII (1996)"], "answer": "B", "key": "3.53", "explanation": "Trung ương 2 năm 1987 → xử lý phân phối, lưu thông còn tồn tại sau Đại hội VI.", "topic": "1986–1990 · Đại hội VI & đổi mới", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Hội nghị năm 1987 tiếp tục xử lý điểm còn hạn chế của đại hội ngay trước đó."}, {"chapter": 3, "number": 54, "id": "415540160", "question": "Triển khai Nghị quyết Đại hội lần thứ VI của Đảng (1986) vào cuộc sống, nội dung nào dưới đây là không đúng về việc thực hiện cải tạo xã hội chủ nghĩa?", "options": ["Nhà nước công nhận sự tồn tại lâu dài của nhiều thành phần kinh tế", "Nâng cao vai trò chủ đạo của nền kinh tế tập thể", "Phát huy khả năng tích cực của các thành phần kinh tế", "Các thành phần kinh tế bình đẳng về quyền lợi, nghĩa vụ trước pháp luật"], "answer": "B", "key": "3.54", "explanation": "Vai trò CHỦ ĐẠO thuộc kinh tế nhà nước; không chuyển thành kinh tế tập thể.", "topic": "1986–1990 · Đại hội VI & đổi mới", "extra": false, "review": false, "tier": 8, "sources": [], "hint": "Phân biệt thành phần kinh tế giữ vai trò chủ đạo với thành phần kinh tế tập thể."}, {"chapter": 3, "number": 55, "id": "415540161", "question": "Nghị quyết 10 của Bộ Chính trị (4/1988) về khoán sản phẩm cuối cùng đến nhóm hộ và hộ xã viên (gọi tắt là khoán 10) được diễn ra trong lĩnh vực nào?", "options": ["Công nghiệp", "Thương nghiệp", "Nông nghiệp", "Lâm nghiệp"], "answer": "C", "key": "3.55", "explanation": "Khoán 10 năm 1988 → nông nghiệp, phát huy vai trò hộ nông dân.", "topic": "1986–1990 · Đại hội VI & đổi mới", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Khoán sản phẩm cuối cùng gắn hoạt động của hộ xã viên trong lĩnh vực trồng trọt, chăn nuôi."}, {"chapter": 3, "number": 56, "id": "415540162", "question": "Hội nghị Trung ương 6 (3/1989) đề ra sáu nguyên tắc chỉ đạo công cuộc đổi mới. Nguyên tắc nào dưới đây được coi là điều kiện quyết định thắng lợi sự nghiệp xây dựng và bảo vệ Tổ quốc xã hội chủ nghĩa của nhân dân ta?", "options": ["Kiên định con đường đi lên chủ nghĩa xã hội", "Sự lãnh đạo của Đảng Cộng sản Việt Nam", "Xây dựng nền dân chủ xã hội chủ nghĩa", "Kết hợp sức mạnh dân tộc với sức mạnh thời đại"], "answer": "B", "key": "3.56", "explanation": "Nguyên tắc đổi mới 1989 → giữ vai trò lãnh đạo của Đảng.", "topic": "1986–1990 · Đại hội VI & đổi mới", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Tìm nguyên tắc bảo đảm vai trò định hướng và tổ chức của lực lượng lãnh đạo cách mạng."}, {"chapter": 3, "number": 57, "id": "415540163", "question": "Hội nghị Trung ương 6 (3/1989) đề ra sáu nguyên tắc chỉ đạo công cuộc đổi mới. Nội dung nào dưới đây không phải là một trong sáu nguyên tắc đó?", "options": ["Đi lên CNXH là con đường tất yếu của nước ta", "Chủ nghĩa Mác - Lênin cùng với tư tưởng Hồ Chí Minh là nền tảng tư tưởng của Đảng", "Xây dựng nền dân chủ xã hội chủ nghĩa là mục tiêu, động lực của sự nghiệp xây dựng chủ nghĩa xã hội", "Kết hợp sức mạnh dân tộc với sức mạnh thời đại"], "answer": "B", "key": "3.57", "explanation": "Nguồn hỏi ĐÚNG NGUYÊN VĂN mốc 1989; ghi nhận đầy đủ Mác–Lênin và tư tưởng Hồ Chí Minh gắn Đại hội VII năm 1991.", "topic": "1986–1990 · Đại hội VI & đổi mới", "extra": false, "review": true, "tier": 8, "sources": [], "hint": "Chú ý ĐÚNG MỐC 1989: không tự đưa cách diễn đạt đầy đủ được khẳng định năm 1991 vào đây."}, {"chapter": 3, "number": 58, "id": "415540164", "question": "Nội dung nào dưới đây không phải là mục tiêu của việc đổi mới tổ chức và phương thức hoạt động của hệ thống chính trị mà Hội nghị Trung ương 6 (3/1989) đề ra?", "options": ["Tăng cường vai trò lãnh đạo của Đảng", "Nâng cao hiệu quả quản lý của Nhà nước", "Phát huy quyền làm chủ của nhân dân", "Nâng cao hơn nữa hiệu quả của công tác kết hợp sức mạnh dân tộc với sức mạnh thời đại"], "answer": "D", "key": "3.58", "explanation": "Đổi mới hệ thống chính trị → dân chủ, quyền làm chủ, hiệu lực; phương án D lệch trọng tâm.", "topic": "1986–1990 · Đại hội VI & đổi mới", "extra": false, "review": false, "tier": 8, "sources": [], "hint": "Đề hỏi mục tiêu trực tiếp đổi mới hệ thống chính trị; loại nội dung lệch sang kết hợp các nguồn sức mạnh."}, {"chapter": 3, "number": 59, "id": "415540165", "question": "Tại sao vào tháng 9 năm 1989 (sớm hơn một năm theo kế hoạch), Việt Nam rút hết quân tình nguyện ở Campuchia về nước?", "options": ["Do tình hình ở Campuchia đã hoàn toàn ổn định", "Do Việt Nam cần lực lượng để ổn định biên giới phía Bắc với Trung Quốc", "Do Việt Nam chịu sức ép từ các nước trên thế giới", "Do thực hiện chủ trương đổi mới về quan hệ đối ngoại của Đảng"], "answer": "D", "key": "3.59", "explanation": "Rút quân Campuchia năm 1989 → gắn đổi mới đối ngoại và giải pháp chính trị khu vực.", "topic": "1986–1990 · Đại hội VI & đổi mới", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Xét thay đổi định hướng giải quyết vấn đề khu vực và quan hệ đối ngoại cuối thập niên 1980."}, {"chapter": 3, "number": 60, "id": "415540166", "question": "Hội nghị Trung ương 8 (3/1990) đã chỉ ra nguyên nhân sâu xa dẫn đến khủng hoảng ở Liên Xô và các nước xã hội chủ nghĩa Đông Âu là:", "options": ["Những quan điểm, khuynh hướng sai lầm, hữu khuynh của một số người lãnh đạo", "Các thế lực thù địch tăng cường can thiệp, phá hoại, thực hiện “diễn biến hòa bình”", "Việc xây dựng mô hình chủ nghĩa xã hội còn một số nhược điểm và khuyết điểm kéo dài quá lâu, ngày càng nặng nề", "Nhân dân hoài nghi với chủ nghĩa xã hội, giảm lòng tin đối với sự lãnh đạo của Đảng và quản lý của Nhà nước"], "answer": "C", "key": "3.60", "explanation": "Khủng hoảng Liên Xô–Đông Âu → khuyết điểm mô hình kéo dài, chậm sửa chữa.", "topic": "1986–1990 · Đại hội VI & đổi mới", "extra": false, "review": false, "tier": 7, "sources": [], "hint": "Đề hỏi nguyên nhân SÂU XA: xét hạn chế nội tại của mô hình kéo dài, không chỉ sự chống phá bên ngoài."}, {"chapter": 3, "number": 61, "id": "415540167", "question": "Hội nghị Trung ương 8 (3/1990) đã kịp thời phân tích tình hình các nước xã hội chủ nghĩa, sự phá hoại của chủ nghĩa đế quốc. Bài học rút ra cho những người cộng sản Việt Nam là?", "options": ["Đổi mới nhận thức về mô hình và con đường xây dựng chủ nghĩa xã hội", "Đổi mới nhận thức về tình hình thế giới và khu vực", "Đổi mới nhận thức về sức mạnh trong nước kết hợp với sức mạnh thời đại", "Đổi mới nhận thức về mối quan hệ giữa Việt Nam với Liên Xô và các nước xã hội chủ nghĩa Đông Âu"], "answer": "A", "key": "3.61", "explanation": "Bài học → đổi mới nhận thức mô hình, con đường xây dựng CNXH.", "topic": "1986–1990 · Đại hội VI & đổi mới", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Bài học tập trung điều chỉnh nhận thức mô hình và cách đi lên, không phải từ bỏ mục tiêu."}, {"chapter": 3, "number": 62, "id": "415540168", "question": "Bắt đầu từ năm 1990, Đảng và Nhà nước Việt Nam đưa ra chủ trương bình thường hóa quan hệ với những nước nào trên thế giới?", "options": ["Trung Quốc, Hoa Kỳ", "Các nước thuộc khối Liên minh Châu Âu EU", "Pháp, Hoa Kỳ", "Trung Quốc, Pháp"], "answer": "A", "key": "3.62", "explanation": "Từ 1990 → chủ trương bình thường hóa với Trung Quốc và Hoa Kỳ; khác thời điểm hoàn tất.", "topic": "1986–1990 · Đại hội VI & đổi mới", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Phân biệt chủ trương bắt đầu bình thường hóa với thời điểm chính thức hoàn tất quan hệ."}, {"chapter": 3, "number": 63, "id": "415540169", "question": "Hội nghị Trung ương 6 (3/1989) và Hội nghị Trung ương 8 (3/1990) tập trung giải quyết những vấn đề cấp bách trong công tác xây dựng Đảng có điểm nổi bật là đổi mới tư duy, nhất là:", "options": ["Tư duy kinh tế", "Tư duy về chất lượng đội ngũ đảng viên", "Tư duy về mối quan hệ giữa Đảng với nhân dân", "Tư duy về công tác giáo dục chính trị, tư tưởng"], "answer": "A", "key": "3.63", "explanation": "Đổi mới tư duy → nhấn mạnh tư duy kinh tế trong xây dựng Đảng.", "topic": "1986–1990 · Đại hội VI & đổi mới", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Đổi mới cách suy nghĩ phải ưu tiên lĩnh vực đang gây khủng hoảng đời sống và sản xuất."}, {"chapter": 3, "number": 64, "id": "415540170", "question": "Đại hội lần thứ mấy của Đảng được gọi là Đại hội “Trí tuệ, đổi mới, dân chủ, kỷ cương và đoàn kết”?", "options": ["Đại hội lần thứ V (1982)", "Đại hội lần thứ VI (1986)", "Đại hội lần thứ VII (1991)", "Đại hội lần thứ VIII (1996)"], "answer": "C", "key": "3.64", "explanation": "Đại hội VII năm 1991 → Trí tuệ, đổi mới, dân chủ, kỷ cương và đoàn kết.", "topic": "1991–1994 · Đại hội VII & Cương lĩnh", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Đây là đại hội thông qua Cương lĩnh thời kỳ quá độ đầu thập niên 1990."}, {"chapter": 3, "number": 65, "id": "415540171", "question": "Đại hội đại biểu toàn quốc lần thứ VII của Đảng (1991) đã bầu đồng chí nào làm Tổng Bí thư?", "options": ["Đ/c Đỗ Mười", "Đ/c Nông Đức Mạnh", "Đ/c Lê Khả Khiêu", "Đ/c Nguyễn Văn Linh"], "answer": "A", "key": "3.65", "explanation": "Đại hội VII → Đỗ Mười làm Tổng Bí thư.", "topic": "1991–1994 · Đại hội VII & Cương lĩnh", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Nhớ người kế nhiệm Nguyễn Văn Linh và tiếp tục giữ chức ở Đại hội VIII."}, {"chapter": 3, "number": 66, "id": "415540172", "question": "Đại hội nào của Đảng khẳng định: “Đảng Cộng sản Việt Nam lấy chủ nghĩa Mác - Lênin và tư tưởng Hồ Chí Minh là nền tảng tư tưởng và kim chỉ nam cho hành động….”?", "options": ["Đại hội lần thứ VI (1986)", "Đại hội lần thứ VII (1991)", "Đại hội lần thứ VIII (1996)", "Đại hội lần thứ IX (2001)"], "answer": "B", "key": "3.66", "explanation": "Đại hội VII → khẳng định Mác–Lênin và tư tưởng Hồ Chí Minh là nền tảng.", "topic": "1991–1994 · Đại hội VII & Cương lĩnh", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Mốc khẳng định nền tảng tư tưởng đầy đủ gắn với Cương lĩnh năm 1991."}, {"chapter": 3, "number": 67, "id": "415540173", "question": "Cương lĩnh xây dựng đất nước trong thời kỳ quá độ lên chủ nghĩa xã hội được thông qua trong Đại hội lần thứ mấy của Đảng?", "options": ["Đại hội lần thứ VI (1986)", "Đại hội lần thứ VII (1991)", "Đại hội lần thứ VIII (1996)", "Đại hội lần thứ IX (2001)"], "answer": "B", "key": "3.67", "explanation": "Cương lĩnh thời kỳ quá độ năm 1991 → Đại hội VII.", "topic": "1991–1994 · Đại hội VII & Cương lĩnh", "extra": false, "review": false, "tier": 8, "sources": [], "hint": "Đừng nhầm lần thông qua ban đầu với lần bổ sung, phát triển hai mươi năm sau."}, {"chapter": 3, "number": 68, "id": "415540174", "question": "Cương lĩnh xây dựng đất nước trong thời kỳ quá độ lên chủ nghĩa xã hội được thông qua tại Đại hội lần thứ IX (1991) là Cương lĩnh thứ mấy của Đảng Cộng sản Việt Nam kể từ khi ra đời?", "options": ["Cương lĩnh thứ nhất", "Cương lĩnh thứ hai", "Cương lĩnh thứ ba", "Cương lĩnh thứ tư"], "answer": "D", "key": "3.68", "explanation": "Nguồn tính Cương lĩnh 1991 là thứ tư; đề ghi IX (1991) là lỗi, đúng mốc VII.", "topic": "1991–1994 · Đại hội VII & Cương lĩnh", "extra": false, "review": true, "tier": 8, "sources": [], "hint": "Đề có lỗi số đại hội: đọc theo mốc 1991 và thứ tự Cương lĩnh mà tài liệu sử dụng."}, {"chapter": 3, "number": 69, "id": "415540175", "question": "Luận điểm nào dưới đây không phải là một trong sáu đặc trưng của xã hội XHCN mà Cương lĩnh xây dựng đất nước trong thời kỳ quá độ lên chủ nghĩa xã hội (năm 1991) đã xác định?", "options": ["Do nhân dân lao động làm chủ", "Có nền văn hóa tiên tiến, đậm đà bản sắc dân tộc", "Con người được giải phóng khỏi áp bức, bóc lột, bất công, làm theo năng lực, hưởng theo nhu cầu", "Các dân tộc trong nước bình đẳng, đoàn kết và giúp đỡ lẫn nhau cùng tiến bộ"], "answer": "C", "key": "3.69", "explanation": "Câu phủ định: làm theo năng lực, hưởng theo nhu cầu không phải mô tả trong Cương lĩnh 1991.", "topic": "1991–1994 · Đại hội VII & Cương lĩnh", "extra": false, "review": false, "tier": 8, "sources": [], "hint": "Câu phủ định: phân biệt nguyên tắc phân phối trong quá độ với mô tả giai đoạn cộng sản phát triển cao."}, {"chapter": 3, "number": 70, "id": "415540176", "question": "Theo Cương lĩnh xây dựng đất nước trong thời kỳ quá độ lên chủ nghĩa xã hội (năm 1991), thành tố nào dưới đây được xác định có vai trò lãnh đạo hệ thống chính trị?", "options": ["Đảng Cộng sản Việt Nam", "Nhà nước xã hội chủ nghĩa Việt Nam", "Mặt trận Tổ quốc và các đoàn thể nhân dân", "Tất cả các đáp án"], "answer": "A", "key": "3.70", "explanation": "Hệ thống chính trị → Đảng lãnh đạo, Nhà nước quản lý, nhân dân làm chủ.", "topic": "1991–1994 · Đại hội VII & Cương lĩnh", "extra": false, "review": false, "tier": 8, "sources": [], "hint": "Phân biệt ba vai trò: lãnh đạo, quản lý và làm chủ trong hệ thống chính trị."}, {"chapter": 3, "number": 71, "id": "415540177", "question": "Theo Cương lĩnh xây dựng đất nước trong thời kỳ quá độ lên chủ nghĩa xã hội (năm 1991), nền tảng tư tưởng và kim chỉ nam cho hành động của Đảng Cộng sản Việt Nam là?", "options": ["Chủ nghĩa Mác - Lênin", "Chủ nghĩa Mác - Lênin và tư tưởng Hồ Chí Minh", "Tư tưởng tập trung dân chủ", "Tư tưởng đi lên chủ nghĩa xã hội là yêu cầu khách quan, là con đường tất yếu của cách mạng Việt Nam"], "answer": "B", "key": "3.71", "explanation": "Nền tảng tư tưởng → chủ nghĩa Mác–Lênin và tư tưởng Hồ Chí Minh.", "topic": "1991–1994 · Đại hội VII & Cương lĩnh", "extra": false, "review": false, "tier": 8, "sources": [], "hint": "Cương lĩnh kết hợp học thuyết cách mạng quốc tế với tư tưởng lãnh tụ cách mạng Việt Nam."}, {"chapter": 3, "number": 72, "id": "415540178", "question": "Việt Nam và Trung Quốc bình thường hóa quan hệ và từng bước khôi phục, mở rộng quan hệ hữu nghị, hợp tác nhiều mặt vào tháng/năm nào?", "options": ["11/1990", "11/1991", "11/1992", "11/1993"], "answer": "B", "key": "3.72", "explanation": "Bình thường hóa Việt–Trung → tháng 11/1991.", "topic": "1991–1994 · Đại hội VII & Cương lĩnh", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Nhớ sự kiện diễn ra vào cuối năm thông qua Cương lĩnh thời kỳ quá độ."}, {"chapter": 3, "number": 73, "id": "415540179", "question": "Luận điểm nào dưới đây là một trong sáu đặc trưng của xã hội XHCN mà Cương lĩnh xây dựng đất nước trong thời kỳ quá độ lên chủ nghĩa xã hội (năm 1991) đã xác định?", "options": ["Có một nền kinh tế phát triển cao dựa trên lực lượng sản xuất hiện đại và chế độ tư hữu về tư liệu sản xuất", "Có một nền kinh tế phát triển cao dựa trên lực lượng sản xuất hiện đại và chế độ công hữu về tư liệu sản xuất chủ yếu", "Có một nền văn hóa tiên tiến, giao lưu và hội nhập quốc tế", "Có quan hệ hữu nghị và hợp tác với nhân dân các nước xã hội chủ nghĩa trên thế giới"], "answer": "B", "key": "3.73", "explanation": "1991 → lực lượng sản xuất hiện đại và công hữu tư liệu sản xuất chủ yếu.", "topic": "1991–1994 · Đại hội VII & Cương lĩnh", "extra": false, "review": false, "tier": 8, "sources": [], "hint": "Đọc đúng mô tả quan hệ sở hữu trong bản 1991, không thay bằng công thức năm 2011."}, {"chapter": 3, "number": 74, "id": "415540180", "question": "Theo Cương lĩnh xây dựng đất nước trong thời kỳ quá độ lên chủ nghĩa xã hội (năm 1991), nội dung nào dưới đây giữ vị trí chủ đạo trong đời sống tinh thần xã hội?", "options": ["Thế giới quan Mác - Lênin", "Thế giới quan Mác - Lênin, tư tưởng, đạo đức Hồ Chí Minh", "Thế giới quan Mác - Lênin, tư tưởng, đạo đức, phong cách Hồ Chí Minh", "Thế giới quan Mác - Lênin, tư tưởng, đạo đức, phong cách Hồ Chí Minh và truyền thống văn hóa dân tộc"], "answer": "B", "key": "3.74", "explanation": "Đời sống tinh thần → thế giới quan Mác–Lênin, tư tưởng và đạo đức Hồ Chí Minh.", "topic": "1991–1994 · Đại hội VII & Cương lĩnh", "extra": false, "review": false, "tier": 8, "sources": [], "hint": "Đề hỏi yếu tố giữ vị trí định hướng đời sống tinh thần, không phải một thiết chế văn hóa riêng."}, {"chapter": 3, "number": 75, "id": "415540181", "question": "Đại hội lần thứ VII của Đảng (1991) đã xác định mục tiêu tổng quát đến năm 2000 của Việt Nam là phấn đấu vượt qua tình trạng nước nghèo và kém phát triển. Theo đó, mục tiêu và động lực chính của sự phát triển là?", "options": ["Vị trí của Việt Nam trên trường quốc tế", "Vì sự tồn tại và lãnh đạo của Đảng Cộng sản Việt Nam trong bối cảnh Liên Xô và các nước xã hội chủ nghĩa Đông Âu khủng hoảng trầm trọng", "Vì con người, do con người, giải phóng sức sản xuất, khơi gợi mọi tiềm năng của cá nhân, tập thể và cả cộng đồng dân tộc", "Sự tin tưởng và ủng hộ tuyệt đối của nhân dân với Đảng"], "answer": "C", "key": "3.75", "explanation": "Phát triển → vì con người, do con người; giải phóng sức sản xuất và tiềm năng.", "topic": "1991–1994 · Đại hội VII & Cương lĩnh", "extra": false, "review": false, "tier": 7, "sources": [], "hint": "Xét chủ thể vừa hưởng thành quả vừa tạo động lực cho sự phát triển, không chỉ vốn hay kỹ thuật."}, {"chapter": 3, "number": 76, "id": "415540182", "question": "Hội nghị Trung ương 3 (6/1992) lần đầu tiên đưa ra chủ trương tự đổi mới, tự chỉnh đốn Đảng, mục tiêu được xác định là gì?", "options": ["Nâng cao năng lực lãnh đạo và sức chiến đấu của Đảng, phù hợp với yêu cầu khách quan của cách mạng Việt Nam trong tình hình mới", "Củng cố, bảo vệ vai trò lãnh đạo duy nhất của Đảng Cộng sản Việt Nam trước sự chống phá của các thế lực thù địch", "Củng cố, tăng cường niềm tin của nhân dân vào sự lãnh đạo của Đảng Cộng sản Việt Nam trong khi Liên Xô và các nước xã hội chủ nghĩa Đông Âu vừa sụp đổ", "Nâng cao năng lực lãnh đạo của Đảng để thực hiện thắng lợi công cuộc đổi mới đất nước"], "answer": "A", "key": "3.76", "explanation": "Tự đổi mới, chỉnh đốn → nâng năng lực lãnh đạo và sức chiến đấu của Đảng.", "topic": "1991–1994 · Đại hội VII & Cương lĩnh", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Tự đổi mới, chỉnh đốn nhằm cải thiện khả năng lãnh đạo và năng lực thực hiện nhiệm vụ của Đảng."}, {"chapter": 3, "number": 77, "id": "415540183", "question": "Điểm mới của Nghị quyết số 05-NQ/TƯ ngày 10/6/1993 về tiếp tục đổi mới và phát triển kinh tế - xã hội nông thôn là?", "options": ["Đề ra các chính sách làm cho sản xuất trong nông nghiệp được “bung ra”", "Chủ trương coi nông nghiệp là mặt trận hàng đầu", "Đổi mới quản lý kinh tế nông nghiệp, nông dân được nhận khoán và canh tác trên diện tích ổn định trong 15 năm", "Đề ra các quan điểm, nhiệm vụ xây dựng, phát triển nông nghiệp, nông thôn toàn diện, khơi dậy mọi tiềm năng, nội lực của nông dân"], "answer": "D", "key": "3.77", "explanation": "Nông thôn 1993 → phát triển toàn diện, khơi dậy nội lực nông dân.", "topic": "1991–1994 · Đại hội VII & Cương lĩnh", "extra": false, "review": false, "tier": 8, "sources": [], "hint": "Điểm mới nằm ở cách phát triển nông thôn toàn diện và khơi dậy nguồn lực tại chỗ."}, {"chapter": 3, "number": 78, "id": "415540184", "question": "Nội dung nào dưới đây là không đúng về Hội nghị đại biểu toàn quốc giữa nhiệm kỳ khóa VII của Đảng (1/1994)?", "options": ["Là Hội nghị đại biểu toàn quốc giữa nhiệm kỳ lần đầu tiên Đảng tổ chức", "Là Hội nghị lần đầu tiên khẳng định Đảng Cộng sản Việt Nam lấy chủ nghĩa Mác - Lênin, tư tưởng Hồ Chí Minh làm nền tảng tư tưởng, kim chỉ nam cho hành động", "Là Hội nghị lần đầu tiên khẳng định xây dựng Nhà nước pháp quyền Việt Nam của nhân dân, do nhân dân, vì nhân dân", "Là Hội nghị lần đầu tiên chỉ rõ 4 nguy cơ của cách mạng Việt Nam"], "answer": "B", "key": "3.78", "explanation": "Câu phủ định: nền tảng tư tưởng đã được khẳng định năm 1991, không phải lần đầu ở 1994.", "topic": "1991–1994 · Đại hội VII & Cương lĩnh", "extra": false, "review": false, "tier": 8, "sources": [], "hint": "Câu phủ định: nền tảng tư tưởng đã nêu ở đại hội năm 1991, không đợi hội nghị giữa nhiệm kỳ."}, {"chapter": 3, "number": 79, "id": "415540185", "question": "“Nước ta đã ra khỏi khủng hoảng kinh tế - xã hội, nhưng một số mặt còn chưa vững chắc” là đánh giá tổng quát của Đại hội lần thứ mấy ?", "options": ["Đại hội lần thứ VI (1986)", "Đại hội lần thứ VII (1991)", "Đại hội lần thứ VIII (1996)", "Đại hội lần thứ IX (2001)"], "answer": "C", "key": "3.79", "explanation": "Đại hội VIII năm 1996 → đánh giá ra khỏi khủng hoảng, còn mặt chưa vững chắc.", "topic": "1996–1998 · Đại hội VIII", "extra": false, "review": false, "tier": 7, "sources": [], "hint": "Nhớ đại hội tổng kết mười năm đổi mới kể từ năm 1986."}, {"chapter": 3, "number": 80, "id": "415540186", "question": "Tổng kết 10 năm đổi mới đất nước (1986-1996), Đại hội lần thứ VIII của Đảng (1996) khẳng định đất nước đã thu được những thành tựu to lớn, có ý nghĩa rất quan trọng, một trong những thành tựu đó là?", "options": ["Nước ta đã ra khỏi khủng hoảng kinh tế - xã hội, nhưng một số mặt còn chưa vững chắc", "Nước ta đã ra khỏi khủng hoảng kinh tế - xã hội, có sự thay đổi cơ bản và toàn diện", "Công nghiệp hóa, hiện đại hóa đất nước bước đầu tạo ra những kết quả tốt đẹp tạo nền tảng cho Việt Nam tiếp tục phát triển", "Vị thế nước ta trên trường quốc tế không ngừng được nâng cao"], "answer": "A", "key": "3.80", "explanation": "10 năm đổi mới → ra khỏi khủng hoảng kinh tế–xã hội, vẫn còn hạn chế.", "topic": "1996–1998 · Đại hội VIII", "extra": false, "review": false, "tier": 7, "sources": [], "hint": "Chú ý thành tựu kinh tế–xã hội tổng quát, đồng thời vẫn có lời đánh giá chưa vững chắc."}, {"chapter": 3, "number": 81, "id": "415540187", "question": "Đại hội đại biểu toàn quốc lần thứ VIII của Đảng (1996) đã bầu đồng chí nào làm Tổng Bí thư?", "options": ["Đ/c Lê Duẩn", "Đ/c Trường Chinh", "Đ/c Đỗ Mười", "Đ/c Lê Khả Khiêu"], "answer": "C", "key": "3.81", "explanation": "Đại hội VIII → Đỗ Mười tiếp tục làm Tổng Bí thư.", "topic": "1996–1998 · Đại hội VIII", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Đại hội này tiếp tục bầu người đã được bầu tại Đại hội VII."}, {"chapter": 3, "number": 82, "id": "415540188", "question": "Trong thời kỳ quá độ lên CNXH ở Việt Nam, công nghiệp hóa được Đảng xác định là?", "options": ["Nhiệm vụ quan trọng", "B. Mục tiêu chiến lược", "Nhiệm vụ trung tâm", "Mục tiêu quan trọng"], "answer": "C", "key": "3.82", "explanation": "Công nghiệp hóa → nhiệm vụ trung tâm trong thời kỳ quá độ.", "topic": "1996–1998 · Đại hội VIII", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Đề hỏi vị trí trong phát triển kinh tế thời kỳ quá độ, không nhầm với vai trò xây dựng Đảng."}, {"chapter": 3, "number": 83, "id": "415540189", "question": "Đại hội lần thứ VIII của Đảng (1996) khẳng định nhiệm vụ đề ra cho chặng đường đầu của thời kỳ quá độ là chuẩn bị tiền đề cho công nghiệp hóa đã cơ bản hoàn thành, cho phép chuyển sang thời kỳ mới là?", "options": ["Tiếp tục đẩy mạnh công nghiệp hóa đất nước", "Đẩy mạnh công nghiệp hóa, hiện đại hóa đất nước", "Đẩy mạnh hội nhập kinh tế quốc tế", "Đẩy mạnh hội nhập quốc tế"], "answer": "B", "key": "3.83", "explanation": "1996 → chuyển sang thời kỳ đẩy mạnh công nghiệp hóa, hiện đại hóa.", "topic": "1996–1998 · Đại hội VIII", "extra": false, "review": false, "tier": 7, "sources": [], "hint": "Hoàn thành chuẩn bị tiền đề cho phép bước sang giai đoạn thực hiện mạnh hơn nhiệm vụ công nghiệp hóa."}, {"chapter": 3, "number": 84, "id": "415540190", "question": "Nội dung nào dưới đây không phải là quan điểm của Đảng về công nghiệp hóa được nêu trong nghị quyết Đại hội lần thứ VIII của Đảng (1996)?", "options": ["Công nghiệp hóa gắn với hiện đại hóa và công nghiệp hóa, hiện đại hóa gắn với phát triển nền kinh tế tri thức, bảo vệ tài nguyên, môi trường", "Lấy việc phát huy nguồn lực con người là yếu tố cơ bản cho sự phát triển nhanh và bền vững", "Kết hợp kinh tế với quốc phòng an ninh", "Khoa học và công nghệ là động lực của công nghiệp hóa, hiện đại hóa"], "answer": "A", "key": "3.84", "explanation": "Câu phủ định: công thức gắn kinh tế tri thức, bảo vệ môi trường thuộc bước phát triển sau, không nguyên văn quan điểm 1996.", "topic": "1996–1998 · Đại hội VIII", "extra": false, "review": false, "tier": 8, "sources": [], "hint": "Câu phủ định về mốc: tìm công thức xuất hiện ở bước phát triển nhận thức muộn hơn năm 1996."}, {"chapter": 3, "number": 85, "id": "415540191", "question": "Chỉ ra một trong những quan điểm công nghiệp hóa thời kỳ đổi mới được trình bày tại Đại hội lần thứ VIII của Đảng (1996)?", "options": ["Coi phát triển Giáo dục và Đào tạo, Khoa học và Công nghệ là quốc sách hàng đầu", "Phát triển mạnh tiềm lực quân sự để bảo vệ đất nước", "Lấy việc phát huy nguồn lực con người cho sự phát triển nhanh và bền vững", "Phát triển văn hóa, giao lưu và hội nhập với khu vực và thế giới"], "answer": "C", "key": "3.85", "explanation": "Phát huy nguồn lực con người → nền tảng cho phát triển nhanh, bền vững.", "topic": "1996–1998 · Đại hội VIII", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Nghĩ tới chủ thể sáng tạo, tiếp thu công nghệ và tổ chức sản xuất, không chỉ tài nguyên hay vốn."}, {"chapter": 3, "number": 86, "id": "415540192", "question": "Đại hội lần thứ VIII của Đảng (1996) đã bổ sung đặc trưng tổng quát về mục tiêu xây dựng chủ nghĩa xã hội ở Việt Nam là?", "options": ["Dân giàu, nước mạnh, xã hội công bằng, văn minh", "Dân giàu, nước mạnh, xã hội công bằng, dân chủ, văn minh", "Các dân tộc trong nước bình đẳng, đoàn kết và giúp đỡ nhau cùng tiến bộ", "Có quan hệ hữu nghị và hợp tác với nhân dân tất cả các nước trên thế giới"], "answer": "A", "key": "3.86", "explanation": "Theo nguồn năm 1996 → dân giàu, nước mạnh, xã hội công bằng, văn minh.", "topic": "1996–1998 · Đại hội VIII", "extra": false, "review": false, "tier": 8, "sources": [], "hint": "Chú ý công thức mục tiêu tại mốc 1996, tránh thêm những từ được bổ sung ở giai đoạn sau."}, {"chapter": 3, "number": 87, "id": "415540193", "question": "Trong các nguồn lực để thực hiện công nghiệp hóa, hiện đại hóa ở nước ta đến năm 2020, Đại hội lần thứ VIII của Đảng (1996) đã xác định nguồn lực nào là yếu tố cơ bản cho sự phát triển nhanh và bền vững?", "options": ["Khoa học công nghệ", "Tài nguyên đất đai", "Con người", "Vốn"], "answer": "C", "key": "3.87", "explanation": "Con người → nguồn lực cơ bản của công nghiệp hóa, hiện đại hóa.", "topic": "1996–1998 · Đại hội VIII", "extra": false, "review": false, "tier": 7, "sources": [], "hint": "Nguồn lực này vừa tạo ra vừa sử dụng mọi nguồn lực khác trong quá trình phát triển."}, {"chapter": 3, "number": 88, "id": "415540194", "question": "Theo quan điểm của Đảng thể hiện trong Nghị quyết số 03-NQ/TW ngày 16/7/1998 về xây dựng và phát triển nền văn hóa Việt Nam tiên tiến, đậm đà bản sắc dân tộc, giải thích nào dưới đây là không đúng về tính tiên tiến của nền văn hóa?", "options": ["Tiên tiến là yêu nước và tiến bộ mà nội dung cốt lõi là lý tưởng độc lập dân tộc và chủ nghĩa xã hội theo chủ nghĩa Mác - Lênin, tư tưởng Hồ Chí Minh", "Tiên tiến là tiếp thu có chọn lọc văn hóa các dân tộc khác", "Tiên tiến cả trong các phương tiện chuyển tải nội dung", "Tiên tiến cả trong hình thức biểu hiện"], "answer": "B", "key": "3.88", "explanation": "Nguồn phân biệt: tiên tiến gắn yêu nước, tiến bộ; tiếp thu có chọn lọc không phải định nghĩa đầy đủ tính tiên tiến.", "topic": "1996–1998 · Đại hội VIII", "extra": false, "review": false, "tier": 8, "sources": [], "hint": "Phân biệt nội hàm tính tiên tiến với nguyên tắc giao lưu, tiếp thu văn hóa bên ngoài."}, {"chapter": 3, "number": 89, "id": "415540195", "question": "Nghị quyết số 03-NQ/TW ngày 16/7/1998 về xây dựng và phát triển nền văn hóa Việt Nam tiên tiến, đậm đà bản sắc dân tộc khẳng định xây dựng và phát triển văn hóa là sự nghiệp của toàn dân do Đảng lãnh đạo, trong đó giữ vai trò quan trọng là?", "options": ["Đội ngũ văn nghệ sĩ", "Đội ngũ trí thức", "Đội ngũ cán bộ quản lý văn hóa", "Bộ Văn hóa - thể thao và Du lịch"], "answer": "B", "key": "3.89", "explanation": "Văn hóa là sự nghiệp toàn dân; đội ngũ trí thức giữ vai trò quan trọng.", "topic": "1996–1998 · Đại hội VIII", "extra": false, "review": false, "tier": 8, "sources": [], "hint": "Xây dựng văn hóa là việc toàn dân nhưng cần lực lượng chuyên làm lao động sáng tạo, nghiên cứu."}, {"chapter": 3, "number": 90, "id": "415540196", "question": "Nghị quyết số 03 - NQ/TW ngày 16/7/1998 về xây dựng và phát triển nền văn hóa Việt Nam tiên tiến, đậm đà bản sắc dân tộc được coi là?", "options": ["Chiến lược xây dựng, phát triển văn hóa trong thời kỳ thực hiện công nghiệp hóa, hiện đại hóa đất nước", "Tuyên ngôn văn hóa của Đảng trong thời kỳ thực hiện công nghiệp hóa, hiện đại hóa", "Kế sách lâu dài để xây dựng, phát triển nền văn hóa", "Giải pháp trước mắt để giải quyết những khó khăn trong xây dựng, phát triển nền văn hóa Việt Nam"], "answer": "B", "key": "3.90", "explanation": "Nghị quyết văn hóa 1998 → Tuyên ngôn văn hóa thời kỳ công nghiệp hóa.", "topic": "1996–1998 · Đại hội VIII", "extra": false, "review": false, "tier": 8, "sources": [], "hint": "Tên gọi ví von nhấn mạnh tầm định hướng của nghị quyết đối với văn hóa thời kỳ mới."}, {"chapter": 3, "number": 91, "id": "415540197", "question": "Nghị quyết số 03 - NQ/TW ngày 16/7/1998 về xây dựng và phát triển nền văn hóa Việt Nam tiên tiến, đậm đà bản sắc dân tộc khẳng định văn hóa là một mặt trận, xây dựng và phát triển văn hóa là một sự nghiệp cách mạng lâu dài, đòi hỏi phải có?", "options": ["Sự đồng lòng, quyết tâm thực hiện của toàn Đảng, toàn dân", "Quyết tâm chính trị cao của toàn bộ hệ thống chính trị", "Có ý chí cách mạng và sự kiên trì, thận trọng", "Sự linh hoạt, mềm dẻo phù hợp với tình hình kinh tế - chính trị trong nước và quốc tế"], "answer": "C", "key": "3.91", "explanation": "Xây dựng văn hóa lâu dài → ý chí cách mạng, kiên trì, thận trọng.", "topic": "1996–1998 · Đại hội VIII", "extra": false, "review": false, "tier": 8, "sources": [], "hint": "Sự nghiệp văn hóa lâu dài cần thái độ bền bỉ và cách làm cân nhắc, không nóng vội."}, {"chapter": 3, "number": 92, "id": "415540198", "question": "Đại hội đại biểu toàn quốc lần thứ IX của Đảng (2001) bầu đồng chí nào làm Tổng Bí thư?", "options": ["Đ/c Trường Chinh", "Đ/c Đỗ Mười", "Đ/c Lê Khả Khiêu", "Đ/c Nông Đức Mạnh"], "answer": "D", "key": "3.92", "explanation": "Đại hội IX năm 2001 → Nông Đức Mạnh làm Tổng Bí thư.", "topic": "2001 · Đại hội IX", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Nhớ vị lãnh đạo đảm nhiệm hai nhiệm kỳ từ Đại hội IX tới Đại hội X."}, {"chapter": 3, "number": 93, "id": "415540199", "question": "Bối cảnh lịch sử nào sau đây có sự ảnh hưởng lớn nhất tới việc hoạch định đường lối của Đảng tại Đại hội lần thứ IX (2001)?", "options": ["Cách mạng khoa học và công nghệ, kinh tế tri thức, toàn cầu hóa diễn ra mạnh mẽ", "Lợi dụng cuộc chiến chống khủng bố, một số nước lớn tăng cường can thiệp vào công việc nội bộ của nhiều nước", "Khu vực Đông Nam Á, châu Á - Thái Bình Dương trở thành khu vực phát triển kinh tế năng động nhưng tiềm ẩn nhiều nhân tố gây mất ổn định", "Việt Nam đã tạo được thế và lực mới nhưng nền kinh tế phát triển chưa vững chắc, hiệu quả và sức cạnh tranh thấp"], "answer": "D", "key": "3.93", "explanation": "2001 → thế và lực mới nhưng chất lượng, sức cạnh tranh kinh tế còn thấp.", "topic": "2001 · Đại hội IX", "extra": false, "review": false, "tier": 7, "sources": [], "hint": "Xét cả thành quả sau đổi mới và hạn chế về chất lượng, hiệu quả của nền kinh tế."}, {"chapter": 3, "number": 94, "id": "415540200", "question": "Đường lối đối ngoại “Việt Nam sẵn sàng là bạn, là đối tác tin cậy của các nước trong cộng đồng quốc tế, phấn đấu vì hòa bình, độc lập và phát triển” được đưa ra tại Đại hội lần thứ mấy của Đảng?", "options": ["Đại hội lần thứ VI (1986)", "Đại hội lần thứ VII (1991)", "Đại hội lần thứ VIII (1996)", "Đại hội lần thứ IX (2001)"], "answer": "D", "key": "3.94", "explanation": "Đại hội IX → sẵn sàng là bạn, là đối tác tin cậy.", "topic": "2001 · Đại hội IX", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Phân biệt các nấc diễn đạt đối ngoại: muốn là bạn → sẵn sàng là bạn, đối tác → thành viên có trách nhiệm."}, {"chapter": 3, "number": 95, "id": "415540201", "question": "Đại hội đại biểu toàn quốc lần thứ IX của Đảng (2001) khẳng định đối với nước ta, thế kỷ XX là thế kỷ của những chiến công và thắng lợi có ý nghĩa lịch sử và thời đại. Thắng lợi nào sau đây đã mở ra bước ngoặt cho cách mạng Việt Nam?", "options": ["Đảng Cộng sản Việt Nam ra đời", "Thắng lợi của Cách mạng Tháng Tám năm 1945 và việc thành lập nước Việt Nam Dân chủ Cộng hòa", "Thắng lợi của các cuộc kháng chiến oanh liệt để giải phóng dân tộc, bảo vệ Tổ quốc", "Thắng lợi của sự nghiệp đổi mới, từng bước đưa đất nước quá độ lên chủ nghĩa xã hội"], "answer": "A", "key": "3.95", "explanation": "Đảng ra đời năm 1930 → bước ngoặt về đường lối và lãnh đạo cách mạng.", "topic": "2001 · Đại hội IX", "extra": false, "review": false, "tier": 7, "sources": [], "hint": "Tìm sự kiện chấm dứt khủng hoảng đường lối và lực lượng lãnh đạo đầu thế kỷ XX."}, {"chapter": 3, "number": 96, "id": "415540202", "question": "Đại hội đại biểu toàn quốc lần thứ IX của Đảng (2001) khẳng định bước phát triển quan trọng trong nhận thức và tư duy lý luận của Đảng là?", "options": ["Khẳng định lấy chủ nghĩa Mác - Lênin, tư tưởng Hồ Chí Minh làm nền tảng tư tưởng, kim chỉ nam cho hành động", "Khẳng định con đường quá độ lên chủ nghĩa xã hội ở Việt Nam là bỏ qua chế độ tư bản chủ nghĩa", "Khẳng định động lực chủ yếu để phát triển đất nước là đại đoàn kết toàn dân trên cơ sở liên minh công nhân với nông dân và trí thức do Đảng lãnh đạo", "Khẳng định vai trò lãnh đạo duy nhất của Đảng"], "answer": "A", "key": "3.96", "explanation": "Nguồn chọn A; cần phân biệt khẳng định lại năm 2001 với lần đầu ghi rõ tư tưởng Hồ Chí Minh năm 1991.", "topic": "2001 · Đại hội IX", "extra": false, "review": true, "tier": 8, "sources": [], "hint": "Đề hỏi KHẲNG ĐỊNH ở năm 2001; đừng tự hiểu thành lần đầu đề cập nội dung này."}, {"chapter": 3, "number": 97, "id": "415540203", "question": "Đại hội đại biểu toàn quốc lần thứ IX của Đảng (2001) đã làm rõ nội dung con đường quá độ lên chủ nghĩa xã hội bỏ qua chế độ tư bản chủ nghĩa ở Việt Nam. Theo đó, nội dung nào sau đây là không đúng?", "options": ["Bỏ qua việc xác lập vị trí thống trị của quan hệ sản xuất và kiến trúc thượng tầng tư bản chủ nghĩa", "Tiếp thu, kế thừa những thành tựu mà nhân loại đạt được dưới chế độ tư bản chủ nghĩa, đặc biệt là cách thức quản lý nền kinh tế", "Có nhiều hình thức sở hữu về tư liệu sản xuất, nhiều thành phần kinh tế", "Động lực chủ yếu để phát triển đất nước là đại đoàn kết toàn dân trên cơ sở liên minh công nhân với nông dân và trí thức do Đảng lãnh đạo"], "answer": "B", "key": "3.97", "explanation": "Nguồn chọn B; văn kiện nhấn mạnh tiếp thu thành tựu, đặc biệt khoa học và công nghệ, không phải riêng cách quản lý.", "topic": "2001 · Đại hội IX", "extra": false, "review": true, "tier": 8, "sources": [], "hint": "Nguồn dùng câu chữ văn kiện: chú ý thành tựu khoa học, công nghệ khi kế thừa từ nhân loại."}, {"chapter": 3, "number": 98, "id": "415540204", "question": "Đại hội đại biểu toàn quốc lần thứ IX của Đảng (2001) khẳng định mô hình kinh tế tổng quát ở Việt Nam là?", "options": ["Kinh tế hàng hóa nhiều thành phần", "Kinh tế thị trường", "Kinh tế thị trường xã hội chủ nghĩa", "Kinh tế thị trường định hướng xã hội chủ nghĩa"], "answer": "D", "key": "3.98", "explanation": "Đại hội IX → mô hình tổng quát là kinh tế thị trường định hướng XHCN.", "topic": "2001 · Đại hội IX", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Tìm mô hình kết hợp cơ chế thị trường với mục tiêu, định hướng xã hội chủ nghĩa."}, {"chapter": 3, "number": 99, "id": "415540205", "question": "Nền kinh tế hàng hóa nhiều thành phần vận động theo cơ chế thị trường có sự quản lý của nhà nước theo định hướng xã hội chủ nghĩa là nội dung của mô hình kinh tế nào sau đây?", "options": ["Kinh tế hàng hóa nhiều thành phần", "Kinh tế thị trường", "Kinh tế thị trường xã hội chủ nghĩa", "Kinh tế thị trường định hướng xã hội chủ nghĩa"], "answer": "D", "key": "3.99", "explanation": "Nhiều thành phần + cơ chế thị trường + quản lý nhà nước → thị trường định hướng XHCN.", "topic": "2001 · Đại hội IX", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Đọc đủ các yếu tố của định nghĩa: nhiều thành phần, thị trường, quản lý nhà nước và định hướng."}, {"chapter": 3, "number": 100, "id": "415540206", "question": "Theo quan điểm của Đại hội đại biểu toàn quốc lần thứ IX (2001) về mô hình kinh tế thị trường định hướng xã hội chủ nghĩa, nội dung nào dưới đây là không đúng về vấn đề phân phối?", "options": ["Phân phối theo kết quả lao động và hiệu quả kinh tế", "Phân phối theo mức đóng góp vốn và các nguồn lực khác vào sản xuất, kinh doanh", "Phân phối thông qua phúc lợi xã hội", "Phân phối theo hình thức bình quân cho mọi người"], "answer": "D", "key": "3.100", "explanation": "Câu phủ định: không phân phối bình quân; gắn lao động, hiệu quả và các nguồn đóng góp.", "topic": "2001 · Đại hội IX", "extra": false, "review": false, "tier": 8, "sources": [], "hint": "Câu phủ định: chính sách phân phối không xóa mọi khác biệt về lao động và đóng góp."}, {"chapter": 3, "number": 101, "id": "415540207", "question": "Đại hội đại biểu toàn quốc lần thứ X của Đảng (2006) khẳng định xây dựng, chỉnh đốn Đảng là nhiệm vụ?", "options": ["Trung tâm", "Then chốt", "Trọng yếu", "Quyết định"], "answer": "B", "key": "3.101", "explanation": "Xây dựng, chỉnh đốn Đảng → nhiệm vụ THEN CHỐT.", "topic": "2006–2008 · Đại hội X", "extra": false, "review": false, "tier": 7, "sources": [], "hint": "Phân biệt xây dựng Đảng với phát triển kinh tế: hai lĩnh vực có cách xác định vị trí khác nhau."}, {"chapter": 3, "number": 102, "id": "415540208", "question": "Đại hội lần thứ X của Đảng (2006) khẳng định mọi thành tựu và khuyết điểm của công cuộc đổi mới, xây dựng và bảo vệ Tổ quốc đều gắn liền với?", "options": ["Trách nhiệm lãnh đạo và hoạt động của Đảng", "Trách nhiệm quản lý và hoạt động của Nhà nước", "Trách nhiệm kiểm tra, giám sát của Mặt trận Tổ quốc", "Trách nhiệm của cả hệ thống chính trị"], "answer": "A", "key": "3.102", "explanation": "Thành tựu và khuyết điểm → gắn trách nhiệm lãnh đạo, hoạt động của Đảng.", "topic": "2006–2008 · Đại hội X", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Xét trách nhiệm của lực lượng trực tiếp hoạch định và lãnh đạo thực hiện đường lối đổi mới."}, {"chapter": 3, "number": 103, "id": "415540209", "question": "Theo văn kiện Đại hội đại biểu toàn quốc lần thứ X của Đảng (2006), nội dung nào sau đây là không đúng về cách thức Đảng phải thực hiện nhằm nâng cao năng lực lãnh đạo?", "options": ["Nâng cao năng lực hoạch định đường lối, chính sách", "Nâng cao năng lực tổ chức chỉ đạo thực hiện, tổng kết lý luận thực tiễn", "Lãnh đạo Mặt trận và các đoàn thể quần chúng, tăng cường mối quan hệ gắn bó mật thiết với nhân dân", "Mở rộng quan hệ đối ngoại và không ngừng học hỏi kinh nghiệm lãnh đạo từ các Đảng Cộng sản trên thế giới"], "answer": "D", "key": "3.103", "explanation": "Nguồn hỏi nội dung văn kiện cụ thể; phương án đối ngoại Đảng không nằm trong nhóm cách thức đang xét.", "topic": "2006–2008 · Đại hội X", "extra": false, "review": false, "tier": 8, "sources": [], "hint": "Đây là câu về danh mục cách thức trong văn kiện; tìm nội dung nằm ngoài nhóm đang hỏi."}, {"chapter": 3, "number": 104, "id": "415540210", "question": "Nội dung nào dưới đây không phải là điểm mới của Đại hội đại biểu toàn quốc lần thứ X của Đảng (2006)?", "options": ["Cho phép đảng viên được làm kinh tế tư nhân, kể cả tư bản tư nhân", "Làm sáng tỏ bản chất của Đảng", "Bổ sung hai đặc trưng mới của chủ nghĩa xã hội mà nhân dân ta xây dựng so với Cương lĩnh năm 1991", "Khẳng định mô hình quản lý kinh tế ở Việt Nam là kinh tế thị trường định hướng xã hội chủ nghĩa"], "answer": "D", "key": "3.104", "explanation": "Kinh tế thị trường định hướng XHCN đã xác định ở Đại hội IX → không mới tại X.", "topic": "2006–2008 · Đại hội X", "extra": false, "review": false, "tier": 8, "sources": [], "hint": "Câu phủ định về điểm mới: mô hình kinh tế tổng quát đã được nêu ở đại hội năm 2001."}, {"chapter": 3, "number": 105, "id": "415540211", "question": "Theo văn kiện Đại hội đại biểu toàn quốc lần thứ X của Đảng (2006), nội dung nào dưới đây là điểm mới trong chủ trương phát huy sức mạnh toàn dân tộc?", "options": ["Lấy mục tiêu chung của toàn dân tộc là giữ vững độc lập, thống nhất của Tổ quốc, vì dân giàu, nước mạnh, xã hội công bằng, dân chủ, văn minh để đoàn kết toàn dân", "Xóa bỏ mọi mặc cảm, định kiến, phân biệt đối xử về quá khứ, thành phần giai cấp", "Đề cao truyền thống nhân nghĩa, khoan dung, xây dựng tinh thần cởi mở, tin cậy lẫn nhau", "Chỉ ra nhiều biện pháp, hình thức, nhằm phát huy dân chủ"], "answer": "B", "key": "3.105", "explanation": "Đại đoàn kết → xóa mặc cảm, định kiến, phân biệt về quá khứ và thành phần.", "topic": "2006–2008 · Đại hội X", "extra": false, "review": false, "tier": 8, "sources": [], "hint": "Xét biện pháp tháo bỏ rào cản tâm lý, lịch sử giữa các bộ phận trong khối đoàn kết."}, {"chapter": 3, "number": 106, "id": "415540212", "question": "Theo văn kiện Đại hội đại biểu toàn quốc lần thứ X của Đảng (2006) để “đẩy mạnh toàn diện công cuộc đổi mới” cần tập trung vào các lĩnh vực chủ yếu, một trong số đó là?", "options": ["Tiếp tục hoàn thiện thể chế kinh tế thị trường", "Tiếp tục hoàn thiện thể chế kinh tế thị trường xã hội chủ nghĩa", "Tiếp tục hoàn thiện thể chế kinh tế thị trường định hướng xã hội chủ nghĩa", "Tiếp tục hoàn thiện thể chế kinh tế thị trường có sự quản lý của nhà nước"], "answer": "C", "key": "3.106", "explanation": "Đại hội X → hoàn thiện thể chế kinh tế thị trường định hướng XHCN.", "topic": "2006–2008 · Đại hội X", "extra": false, "review": false, "tier": 8, "sources": [], "hint": "Đọc đủ cụm về thể chế, cơ chế thị trường và định hướng; tránh phương án rút thiếu thành tố."}, {"chapter": 3, "number": 107, "id": "415540213", "question": "Hãy chỉ ra một trong những đặc trưng mới của chủ nghĩa xã hội được Đại hội lần thứ X của Đảng (2006) đề ra?", "options": ["Dân giàu, nước mạnh, công bằng, dân chủ, văn minh", "Dân giàu, nước mạnh, dân chủ, công bằng, văn minh", "Do nhân dân làm chủ", "Có nền văn hóa tiên tiến, đậm đà bản sắc dân tộc"], "answer": "A", "key": "3.107", "explanation": "Nguồn dùng thứ tự 2006 → công bằng trước dân chủ; 2011 → dân chủ trước công bằng.", "topic": "2006–2008 · Đại hội X", "extra": false, "review": true, "tier": 8, "sources": [], "hint": "Chú ý đúng thứ tự hai từ công bằng và dân chủ trong công thức của năm 2006."}, {"chapter": 3, "number": 108, "id": "415540214", "question": "Đại hội đại biểu toàn quốc lần thứ X của Đảng (2006) bầu đồng chí nào làm Tổng Bí thư?", "options": ["Đ/c Trường Chinh", "Đ/c Đỗ Mười", "Đ/c Lê Khả Phiêu", "Đ/c Nông Đức Mạnh"], "answer": "D", "key": "3.108", "explanation": "Đại hội X năm 2006 → Nông Đức Mạnh tiếp tục làm Tổng Bí thư.", "topic": "2006–2008 · Đại hội X", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Đại hội này tiếp tục bầu người đã giữ chức từ năm 2001."}, {"chapter": 3, "number": 109, "id": "415540215", "question": "Theo Nghị quyết số 09-NQ/TW ngày 9/2/2007 về Chiến lược biển Việt Nam đến năm 2020, việc xây dựng chiến lược nhằm mục đích chủ yếu nào?", "options": ["Nhằm phát triển kinh tế biển Việt Nam phù hợp với xu hướng phát triển của thế giới khi thế kỷ XXI được coi là thế kỷ của đại dương", "Nhằm phát huy tiềm năng, thế mạnh của biển Việt Nam", "Nhằm tăng tỉ lệ đóng góp của biển Việt Nam vào GDP quốc gia", "Phát huy mạnh mẽ hơn nữa vai trò của biển Việt Nam đối với sự nghiệp xây dựng và bảo vệ Tổ quốc"], "answer": "D", "key": "3.109", "explanation": "Chiến lược biển → phát huy vai trò biển trong cả xây dựng và bảo vệ Tổ quốc.", "topic": "2006–2008 · Đại hội X", "extra": false, "review": false, "tier": 8, "sources": [], "hint": "Mục tiêu phải bao quát cả phát triển lẫn bảo vệ đất nước, không chỉ tăng tỷ trọng GDP."}, {"chapter": 3, "number": 110, "id": "415540216", "question": "Lần đầu tiên những quyết sách mạnh mẽ về giải quyết đồng thời ba vấn đề nông nghiệp, nông dân, nông thôn được đề ra tại Hội nghị Trung ương 7 khóa X (8/2008). Theo đó, công nghiệp hóa, hiện đại hóa nông nghiệp, nông thôn được coi là?", "options": ["Một nhiệm vụ quan trọng hàng đầu của quá trình công nghiệp hóa, hiện đại hóa đất nước", "Một nhiệm vụ cấp bách hàng đầu của quá trình công nghiệp hóa, hiện đại hóa đất nước", "Một nhiệm vụ then chốt của quá trình công nghiệp hóa, hiện đại hóa đất nước", "Một nhiệm vụ trung tâm của quá trình công nghiệp hóa, hiện đại hóa đất nước"], "answer": "A", "key": "3.110", "explanation": "Tam nông → công nghiệp hóa nông nghiệp, nông thôn là nhiệm vụ quan trọng hàng đầu.", "topic": "2006–2008 · Đại hội X", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Đề hỏi vị trí của công nghiệp hóa nông nghiệp, nông thôn trong toàn bộ quá trình công nghiệp hóa."}, {"chapter": 3, "number": 111, "id": "415540217", "question": "Theo Nghị quyết số 25-NQ/TW ngày 25/7/2008 về tăng cường sự lãnh đạo của Đảng đối với công tác thanh niên thời kỳ đẩy mạnh công nghiệp hóa, hiện đại hóa, nội dung nào dưới đây là không đúng?", "options": ["Thanh niên là rường cột của nước nhà", "Thanh niên là trụ cột của nước nhà", "Thanh niên là chủ nhân tương lai của đất nước", "Thanh niên là lực lượng xung kích trong xây dựng và bảo về Tổ quốc"], "answer": "B", "key": "3.111", "explanation": "Câu phủ định về từ ngữ → văn kiện dùng RƯỜNG CỘT, không phải trụ cột.", "topic": "2006–2008 · Đại hội X", "extra": false, "review": false, "tier": 8, "sources": [], "hint": "Câu phủ định về chữ dùng: nghị quyết dùng một hình ảnh truyền thống nói về vai trò thanh niên."}, {"chapter": 3, "number": 112, "id": "415540218", "question": "Theo Nghị quyết số 08-NQ/TW ngày 5/02/2007 về một số chủ trương, chính sách lớn để nền kinh tế phát triển nhanh và bền vững khi Việt Nam là thành viên của Tổ chức Thương mại thế giới WTO, nội dung nào dưới đây là không đúng?", "options": ["Thực hiện mục tiêu dân giàu, nước mạnh, dân chủ, công bằng, văn minh", "Hội nhập quốc tế là công việc của toàn dân", "Giữ vững ổn định chính trị, kinh tế - xã hội", "Gắn khai thác với sử dụng có hiệu quả cao nội lực và các nguồn lực bên ngoài"], "answer": "A", "key": "3.112", "explanation": "Nguồn so sánh đúng câu chữ 2007 → công bằng, dân chủ; tránh áp thứ tự 2011 vào mốc trước.", "topic": "2006–2008 · Đại hội X", "extra": false, "review": true, "tier": 8, "sources": [], "hint": "So thứ tự dân chủ và công bằng theo cách diễn đạt của mốc 2007, không áp công thức 2011."}, {"chapter": 3, "number": 113, "id": "415540219", "question": "Hội nghị Trung ương 7 khóa X (7/2008) ban hành Nghị quyết về “Xây dựng đội ngũ trí thức trong thời kỳ đẩy mạnh công nghiệp hóa, hiện đại hóa đất nước và hội nhập kinh tế quốc tế”, quan điểm chỉ đạo là:", "options": ["Trí thức Việt Nam là lực lượng lao động đặc biệt phục vụ cho sự nghiệp đổi    mới đất nước", "Trí thức Việt Nam là lực lượng chính phục vụ cho sự nghiệp công nghiệp hóa, hiện đại hóa đất nước", "Trí thức Việt Nam là lực lượng then chốt thúc đẩy nghiên cứu và ứng dụng khoa học công nghệ", "Trí thức Việt Nam là lực lượng lao động sáng tạo đặc biệt quan trọng trong tiến trình đẩy mạnh công nghiệp hóa, hiện đại hóa đất nước và hội nhập quốc tế"], "answer": "D", "key": "3.113", "explanation": "Trí thức → lực lượng lao động sáng tạo đặc biệt quan trọng.", "topic": "2006–2008 · Đại hội X", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Nhóm này có đặc trưng lao động sáng tạo và vai trò đặc biệt đối với tri thức, công nghệ."}, {"chapter": 3, "number": 114, "id": "415540220", "question": "Đại hội đại biểu toàn quốc lần thứ XI của Đảng (2011) bầu đồng chí nào làm Tổng Bí thư?", "options": ["Đ/c Đỗ Mười", "Đ/c Lê Khả Phiêu", "Đ/c Nông Đức Mạnh", "Đ/c Nguyễn Phú Trọng"], "answer": "D", "key": "3.114", "explanation": "Đại hội XI năm 2011 → Nguyễn Phú Trọng làm Tổng Bí thư.", "topic": "2011 · Đại hội XI", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Nhớ vị lãnh đạo được bầu tại đại hội thông qua Cương lĩnh bổ sung năm 2011."}, {"chapter": 3, "number": 115, "id": "415540221", "question": "Cương lĩnh xây dựng đất nước trong thời kỳ quá độ lên chủ nghĩa xã hội (bổ sung, phát triển năm 2011) đã bổ sung hai vấn đề mới vào những vấn đề toàn cầu cấp bách liên quan đến vận mệnh loài người, một trong số đó là?", "options": ["Bảo vệ môi trường sống", "Ứng phó với biến đổi khí hậu toàn cầu", "Phòng ngừa và đẩy lùi bệnh tật hiểm nghèo", "Hạn chế sự bùng nổ về dân số"], "answer": "B", "key": "3.115", "explanation": "Vấn đề toàn cầu bổ sung năm 2011 → ứng phó biến đổi khí hậu.", "topic": "2011 · Đại hội XI", "extra": false, "review": false, "tier": 8, "sources": [], "hint": "Tìm thách thức toàn cầu về môi trường được bổ sung, khác bảo vệ môi trường sống nói chung."}, {"chapter": 3, "number": 116, "id": "415540222", "question": "Cương lĩnh xây dựng đất nước trong thời kỳ quá độ lên chủ nghĩa xã hội (bổ sung, phát triển năm 2011) đã bổ sung hai vấn đề mới vào những vấn đề toàn cầu cấp bách liên quan đến vận mệnh loài người, một trong số đó là?", "options": ["Gìn giữ hòa bình, đẩy lùi nguy cơ chiến tranh", "Chống khủng bố", "Hạn chế sự bùng nổ về dân số", "Phòng ngừa và đẩy lùi bệnh tật hiểm nghèo"], "answer": "B", "key": "3.116", "explanation": "Vấn đề toàn cầu bổ sung còn lại → chống khủng bố.", "topic": "2011 · Đại hội XI", "extra": false, "review": false, "tier": 8, "sources": [], "hint": "Tìm nguy cơ an ninh phi truyền thống được nhấn mạnh thêm sau những biến động đầu thế kỷ XXI."}, {"chapter": 3, "number": 117, "id": "415540223", "question": "Cương lĩnh xây dựng đất nước trong thời kỳ quá độ lên chủ nghĩa xã hội (bổ sung, phát triển năm 2011) đã bổ sung hai đặc trưng bao trùm tổng quát về xã hội xã hội chủ nghĩa mà nhân dân ta xây dựng, một trong số đó là?", "options": ["Dân giàu, nước mạnh, dân chủ, công bằng, văn minh", "Có nền văn hóa tiên tiến, đậm đà bản sắc dân tộc", "Con người có cuộc sống ấm no, tự do, hạnh phúc, có điều kiện phát triển toàn diện", "Các dân tộc trong cộng đồng Việt Nam bình đẳng, đoàn kết, tôn trọng và giúp nhau cùng phát triển"], "answer": "A", "key": "3.117", "explanation": "Đặc trưng bao trùm 2011 → dân giàu, nước mạnh, dân chủ, công bằng, văn minh.", "topic": "2011 · Đại hội XI", "extra": false, "review": false, "tier": 8, "sources": [], "hint": "Đề hỏi đặc trưng BAO TRÙM: tìm công thức mục tiêu tổng quát, không chỉ từng mặt xã hội."}, {"chapter": 3, "number": 118, "id": "415540224", "question": "Cương lĩnh xây dựng đất nước trong thời kỳ quá độ lên chủ nghĩa xã hội (bổ sung, phát triển năm 2011) đã bổ sung hai đặc trưng bao trùm tổng quát về xã hội xã hội chủ nghĩa mà nhân dân ta xây dựng, một trong số đó là?", "options": ["Có nền kinh tế phát triển cao dựa trên lực lượng sản xuất hiện đại và quan hệ sản xuất tiến bộ, phù hợp", "Có nền văn hóa tiên tiến, đậm đà bản sắc dân tộc", "Có Nhà nước pháp quyền xã hội chủ nghĩa của nhân dân, do nhân dân, vì nhân dân do Đảng Cộng sản lãnh đạo", "Có quan hệ hữu nghị và hợp tác với các nước trên thế giới"], "answer": "C", "key": "3.118", "explanation": "Đặc trưng mới → Nhà nước pháp quyền XHCN của dân, do dân, vì dân.", "topic": "2011 · Đại hội XI", "extra": false, "review": false, "tier": 8, "sources": [], "hint": "Tìm đặc trưng về tổ chức quyền lực nhà nước được bổ sung, không phải đặc trưng văn hóa đã có."}, {"chapter": 3, "number": 119, "id": "415540225", "question": "Cương lĩnh xây dựng đất nước trong thời kỳ quá độ lên chủ nghĩa xã hội (bổ sung, phát triển năm 2011) đã xác định mục tiêu phát triển đến giữa thế kỷ XXI là?", "options": ["Là nước đang phát triển, có công nghiệp hiện đại, thu nhập trung bình cao", "Là nước phát triển, thu nhập cao", "Là nước công nghiệp hiện đại, theo định hướng xã hội chủ nghĩa", "Là nước phát triển, theo định hướng xã hội chủ nghĩa"], "answer": "C", "key": "3.119", "explanation": "Giữa thế kỷ XXI theo Cương lĩnh 2011 → nước công nghiệp hiện đại, định hướng XHCN.", "topic": "2011 · Đại hội XI", "extra": false, "review": false, "tier": 8, "sources": [], "hint": "Đọc theo mục tiêu trong bản 2011, không thay bằng cách diễn đạt thu nhập hay mục tiêu ban hành sau."}, {"chapter": 3, "number": 120, "id": "415540226", "question": "Cương lĩnh xây dựng đất nước trong thời kỳ quá độ lên chủ nghĩa xã hội (bổ sung, phát triển năm 2011) đã đề ra những định hướng lớn về phát triển kinh tế. Theo đó, nội dung nào sau đây không đúng?", "options": ["Kinh tế tập thể không ngừng được củng cố và phát triển", "Kinh tế nhà nước cùng với kinh tế tập thể ngày càng trở thành nền tảng vững chắc của nền kinh tế quốc dân", "Kinh tế tư nhân là một trong những động lực của nền kinh tế", "Kinh tế có vốn đầu tư nước ngoài được tạo điều kiện phát triển"], "answer": "D", "key": "3.120", "explanation": "Nguồn chọn D do khác câu chữ: nguyên văn là được KHUYẾN KHÍCH phát triển; không có nghĩa phủ nhận đầu tư nước ngoài.", "topic": "2011 · Đại hội XI", "extra": false, "review": true, "tier": 8, "sources": [{"label": "Cương lĩnh 2011 · nguyên văn", "url": "https://tulieuvankien.dangcongsan.vn/ban-chap-hanh-trung-uong-dang/dai-hoi-dang/lan-thu-xi/cuong-linh-xay-dung-dat-nuoc-trong-thoi-ky-qua-do-len-chu-nghia-xa-hoi-bo-sung-phat-trien-nam-2011-1528"}], "hint": "Nguồn bắt khác biệt câu chữ; đọc lưu ý và nguyên văn về khuyến khích phát triển, tránh suy luận phủ nhận đầu tư nước ngoài."}, {"chapter": 3, "number": 121, "id": "415540227", "question": "Cương lĩnh xây dựng đất nước trong thời kỳ quá độ lên chủ nghĩa xã hội (bổ sung, phát triển năm 2011) đã đề ra những định hướng lớn về phát triển văn hóa. Theo đó, trung tâm của chiến lược là?", "options": ["Xây dựng nền văn hóa tiến tiến, đậm đà bản sắc dân tộc", "Phát triển giáo dục và đào tạo cùng với phát triển khoa học và công nghệ", "Con người", "Xây dựng một cộng đồng xã hội văn minh"], "answer": "C", "key": "3.121", "explanation": "Chiến lược phát triển → con người ở trung tâm.", "topic": "2011 · Đại hội XI", "extra": false, "review": false, "tier": 8, "sources": [], "hint": "Trung tâm chiến lược phải là chủ thể phát triển và đối tượng được phục vụ."}, {"chapter": 3, "number": 122, "id": "415540228", "question": "Theo Cương lĩnh xây dựng đất nước trong thời kỳ quá độ lên chủ nghĩa xã hội (bổ sung, phát triển năm 2011), chủ trương đối ngoại của Việt Nam là?", "options": ["Linh hoạt, mềm dẻo, đa phương hóa, đa dạng hóa các mối quan hệ quốc tế", "Việt Nam muốn là bạn với tất cả các nước trong cộng đồng thế giới", "Việt Nam sẵn sàng là bạn, là đối tác tin cậy của các nước trong cộng đồng quốc tế", "Việt Nam là bạn, đối tác tin cậy và thành viên có trách nhiệm trong cộng đồng quốc tế"], "answer": "D", "key": "3.122", "explanation": "2011 → bạn, đối tác tin cậy và thành viên có trách nhiệm trong cộng đồng quốc tế.", "topic": "2011 · Đại hội XI", "extra": false, "review": false, "tier": 8, "sources": [], "hint": "Cách diễn đạt năm 2011 bổ sung vai trò tham gia có trách nhiệm, vượt nấc chỉ sẵn sàng làm bạn."}, {"chapter": 3, "number": 123, "id": "415540229", "question": "Chỉ ra một trong ba đột phá chiến lược được đưa ra tại Đại hội lần thứ XI của Đảng (2011)?", "options": ["Đẩy mạnh phát triển Giáo dục và đào tạo, Khoa học và công nghệ", "Tập trung cải cách hành chính", "Xây dựng hệ thống kết cấu hạ tầng đồng bộ", "Xây dựng hệ thống giao thông đồng bộ tại các thành phố lớn"], "answer": "C", "key": "3.123", "explanation": "Ba đột phá → thể chế, nhân lực, hạ tầng; ở đây chọn hạ tầng đồng bộ.", "topic": "2011 · Đại hội XI", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Nhớ ba nhóm đột phá: thể chế, nguồn nhân lực và điều kiện vật chất kết nối phát triển."}, {"chapter": 3, "number": 124, "id": "415540230", "question": "Đại hội lần thứ XI của Đảng (2011) đưa ra định hướng phát triển kinh tế - xã hội là?", "options": ["Tái cấu trúc nền kinh tế", "Tái cơ cấu lại nền kinh tế", "Đổi mới mô hình tăng trưởng, cơ cấu lại nền kinh tế", "Đẩy mạnh chống tham nhũng"], "answer": "C", "key": "3.124", "explanation": "Đại hội XI → đổi mới mô hình tăng trưởng, cơ cấu lại nền kinh tế.", "topic": "2011 · Đại hội XI", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Định hướng nhắm thay đổi cả cách tạo tăng trưởng lẫn cấu trúc các bộ phận nền kinh tế."}, {"chapter": 3, "number": 125, "id": "415540231", "question": "Đại hội nào của Đảng được gọi là Đại hội “Đoàn kết - Dân chủ - Kỷ cương - Đổi mới”?", "options": ["Đại hội lần thứ IX (2001)", "Đại hội lần thứ X (2006)", "Đại hội lần thứ XI (2011)", "Đại hội lần thứ XII (2016)"], "answer": "D", "key": "3.125", "explanation": "Đại hội XII năm 2016 → Đoàn kết – Dân chủ – Kỷ cương – Đổi mới.", "topic": "2016–2017 · Đại hội XII", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Đừng nhầm khẩu hiệu với Đại hội VII; mốc cần tìm nằm sau Đại hội XI năm năm."}, {"chapter": 3, "number": 126, "id": "415540232", "question": "Hội nghị Trung ương 5, khóa XII (5/2017) đánh giá vai trò kinh tế tư nhân như thế nào?", "options": ["Trở thành nền tảng vững chắc của nền kinh tế thị trường định hướng XHCN", "Trở thành nền tảng quan trọng của nền kinh tế thị trường định hướng XHCN", "Trở thành động lực quan trọng của nền kinh tế thị trường định hướng XHCN", "Trở thành động lực của nền kinh tế thị trường định hướng XHCN"], "answer": "C", "key": "3.126", "explanation": "Trung ương 5 khóa XII → kinh tế tư nhân là động lực QUAN TRỌNG.", "topic": "2016–2017 · Đại hội XII", "extra": false, "review": false, "tier": 7, "sources": [], "hint": "Chú ý tính từ nhấn mạnh vai trò của khu vực tư nhân, không đánh đồng với nền tảng của nền kinh tế."}, {"chapter": 3, "number": 127, "id": "415540233", "question": "Nội dung nào sau đây là một phần chủ đề của Đại hội đại biểu toàn quốc lần thứ XIII của Đảng (2021)?", "options": ["Tiếp tục đẩy mạnh công nghiệp hóa, hiện đại hóa đất nước", "Tiếp tục đẩy mạnh toàn diện, đồng bộ công nghiệp hóa, hiện đại hóa đất nước", "Tiếp tục đẩy mạnh toàn diện, đồng bộ công cuộc đổi mới đất nước", "Tiếp tục đẩy mạnh toàn diện, đồng bộ, có kế thừa công cuộc đổi mới đất nước"], "answer": "C", "key": "3.127", "explanation": "Đại hội XIII → tiếp tục đổi mới toàn diện, đồng bộ.", "topic": "2021 · Đại hội XIII", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Đọc đúng chủ đề: trọng tâm là toàn bộ công cuộc đổi mới, không chỉ công nghiệp hóa."}, {"chapter": 3, "number": 128, "id": "415540234", "question": "Theo Nghị quyết Đại hội đại biểu toàn quốc lần thứ XIII của Đảng (2021), nhiệm vụ đảm bảo quốc phòng an ninh được xác định là?", "options": ["Trung tâm", "Then chốt", "Trọng yếu, thường xuyên", "Quan trọng nhất"], "answer": "C", "key": "3.128", "explanation": "Quốc phòng, an ninh → TRỌNG YẾU, THƯỜNG XUYÊN.", "topic": "2021 · Đại hội XIII", "extra": false, "review": false, "tier": 7, "sources": [], "hint": "Phân biệt vị trí quốc phòng, an ninh với vai trò trung tâm của kinh tế và then chốt của xây dựng Đảng."}, {"chapter": 3, "number": 129, "id": "415540235", "question": "Theo Nghị quyết Đại hội đại biểu toàn quốc lần thứ XIII của Đảng (2021) về kết hợp sức mạnh dân tộc với sức mạnh thời đại, nguồn lực nào được coi là quan trọng nhất?", "options": ["Vốn", "Khoa học công nghệ", "Con người", "Tài nguyên thiên nhiên"], "answer": "C", "key": "3.129", "explanation": "Nguồn lực quan trọng nhất → con người, chủ thể phát triển.", "topic": "2021 · Đại hội XIII", "extra": false, "review": false, "tier": 7, "sources": [], "hint": "Tìm nguồn lực có khả năng tạo ra tri thức, tổ chức sản xuất và sử dụng các nguồn lực khác."}, {"chapter": 3, "number": 130, "id": "415540236", "question": "Đại hội đại biểu toàn quốc lần thứ XIII của Đảng (2021) xác định có chính sách hỗ trợ hiệu quả hoạt động của doanh nghiệp, nhất là doanh nghiệp hoạt động trong lĩnh vực nào?", "options": ["Nông nghiệp", "Công nghiệp", "Xây dựng", "Dịch vụ"], "answer": "A", "key": "3.130", "explanation": "Theo đoạn văn kiện được hỏi → hỗ trợ doanh nghiệp, nhất là lĩnh vực nông nghiệp.", "topic": "2021 · Đại hội XIII", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Theo đoạn văn kiện được trích, chú ý ngành liên quan sản xuất lương thực và đời sống nông thôn."}, {"chapter": 3, "number": 131, "id": "415540237", "question": "Đại hội đại biểu toàn quốc lần thứ XIII của Đảng (2021) xác định hoàn thiện hệ thống pháp luật, nhất là pháp luật về?", "options": ["Bất động sản", "Tài chính, cổ phiếu, chứng khoán", "Sở hữu trí tuệ và các tranh chấp dân sự", "Các thành phần kinh tế đặc biệt là thành phần kinh tế có vốn đầu tư nước ngoài"], "answer": "C", "key": "3.131", "explanation": "Hoàn thiện pháp luật → sở hữu trí tuệ và tranh chấp dân sự theo nội dung nguồn.", "topic": "2021 · Đại hội XIII", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Tìm nhóm pháp luật liên quan quyền đối với sản phẩm sáng tạo và xử lý quan hệ dân sự."}, {"chapter": 3, "number": 132, "id": "415540238", "question": "Đại hội đại biểu toàn quốc lần thứ XIII của Đảng (2021) xác định phát triển nguồn nhân lực, nhất là nguồn nhân lực chất lượng cao, trong đó ưu tiên phát triển nguồn nhân lực cho?", "options": ["Công tác xây dựng và phát triển nền văn hóa tiên tiến, đậm đà bản sắc dân tộc", "Công tác nghiên cứu, chuyển giao ứng dụng và phát triển mạnh khoa học và công nghệ", "Công tác giáo dục và đào tạo", "Công tác lãnh đạo, quản lý và các lĩnh vực then chốt"], "answer": "D", "key": "3.132", "explanation": "Nhân lực chất lượng cao → ưu tiên lãnh đạo, quản lý và các lĩnh vực then chốt.", "topic": "2021 · Đại hội XIII", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Ưu tiên nhân lực gắn với nơi quyết định định hướng, điều hành và các lĩnh vực có vai trò lớn."}, {"chapter": 3, "number": 133, "id": "415540239", "question": "Đại hội đại biểu toàn quốc lần thứ XIII của Đảng (2021) xác định xây dựng hệ thống kết cấu hạ tầng đồng bộ, hiện đại cả về kinh tế và xã hội, trong đó ưu tiên phát triển một số công trình trọng điểm quốc gia về?", "options": ["Khoa học công nghệ, thích ứng với sự phát triển của cuộc cách mạng công nghiệp lần thứ tư", "Văn hóa, thích ứng với quá trình hội nhập quốc tế sâu, rộng của đất nước", "Nhà ở, thích ứng với quá trình tập trung dân số tại các thành phố lớn", "Giao thông, thích ứng với biến đổi khí hậu"], "answer": "D", "key": "3.133", "explanation": "Hạ tầng ưu tiên → giao thông, thích ứng với biến đổi khí hậu.", "topic": "2021 · Đại hội XIII", "extra": false, "review": false, "tier": 6, "sources": [], "hint": "Đề hỏi công trình trọng điểm kết hợp khả năng kết nối và thích ứng điều kiện khí hậu."}, {"chapter": 3, "number": 134, "id": "415540240", "question": "Quan điểm chỉ đạo của Đảng trong Đại hội lần thứ XIII (2021) về việc khẳng định vai trò của khối đại đoàn kết dân tộc là …?", "options": ["Bảo đảo cao nhất lợi ích quốc gia - dân tộc trên cơ sở các nguyên tắc cơ bản của Hiến chương Liên hợp quốc và luật pháp quốc tế", "Kiên định và vận dụng, phát triển sáng tạo chủ nghĩa Mác-Lênin, Tư tưởng Hồ Chí Minh", "Khơi dậy mạnh mẽ tinh thần yêu nước, ý chí tự cường dân tộc sức mạnh đại đoàn kết toàn dân tộc và khát vọng phát triển đất nước phồn vinh hạnh phúc", "Tăng cường xây dựng chỉnh đốn Đảng, phát huy bản chất giai cấp công nhân của Đảng"], "answer": "C", "key": "3.134", "explanation": "Đại đoàn kết → khơi dậy yêu nước, tự cường và khát vọng phồn vinh, hạnh phúc.", "topic": "2021 · Đại hội XIII", "extra": false, "review": false, "tier": 7, "sources": [], "hint": "Quan điểm về đại đoàn kết nhấn mạnh nguồn sức mạnh tinh thần của cả dân tộc và khát vọng phát triển."}, {"chapter": 3, "number": 135, "id": "3636363636", "question": "Tài liệu này được tải miễn phí từ website?", "options": ["tungmarketing.id.vn", "utt.edu.vn", "tiktok.com", "Tất cả phương án đều đúng"], "answer": "A", "key": "3.135", "explanation": "Câu quảng bá nguồn tải, không phải kiến thức môn học → để riêng, không tính điểm ôn tập.", "topic": "Phụ lục · Nguồn tài liệu", "extra": true, "review": false, "tier": 6, "sources": [], "hint": "Đây là câu ghi nguồn tải tài liệu, không phải kiến thức lịch sử và không tính điểm luyện."}];
